INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (18, NULL, 'perehodim-v-plej-off-2', '2025-05-17 00:00:00.000', 'Переходим в плей-офф!', 'По итогам матчей в группах у нас сформировались следующие пары\n\nПлей-офф за 5-8 места:\n15:45 (мск) «Сан Лоренсо» — «Динамо-Минск»\n17:00 (мск) «Фенербахче» — «Кайрат»\n\nПлей-офф за 1-4 места:\n18:15 (мск) «Алмаз-Антей» — «Палмейрас»\n19:30 (мск) «Зенит» — «Црвена Звезда»\n\n#BurchalkinCup', 'По итогам матчей в группах у нас сформировались следующие пары\n\nПлей-офф за 5-8 места:\n\n15:45 (мск) «Сан Лоренсо» — «Динамо-Минск»\n\n17:00 (мск) «Фенербахче» — «Кайрат»\n\nПлей-офф за 1-4 места:\n\n18:15 (мск) «Алмаз-Антей» — «Палмейрас»\n\n19:30 (мск) «Зенит» — «Црвена Звезда»\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>По итогам матчей в группах у нас сформировались следующие пары</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365104/burcup/news/perehodim-v-plej-off-2/images/c9m-pseqdzg-1776365103644.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365104/burcup/news/perehodim-v-plej-off-2/images/c9m-pseqdzg-1776365103644.jpg\" alt=\"\" /></a></p>\n<p>Плей-офф за 5-8 места:<br />\n15:45 (мск) «Сан Лоренсо» — «Динамо-Минск»<br />\n17:00 (мск) «Фенербахче» — «Кайрат»</p>\n<p>Плей-офф за 1-4 места:<br />\n18:15 (мск) «Алмаз-Антей» — «Палмейрас»<br />\n19:30 (мск) «Зенит» — «Црвена Звезда»</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=perehodim-v-plej-off-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365104/burcup/news/perehodim-v-plej-off-2/images/c9m-pseqdzg-1776365103644.jpg', NULL, 1, '2026-04-21 11:19:47.000', '2026-04-21 11:19:47.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (19, NULL, 'raspisanie-finalnogo-dnya-turnira', '2025-05-17 00:00:00.000', 'Расписание финального дня турнира', 'Готовы к завтрашнему финальному дню? Вот какие игры нас ждут\n\nМатч за 7 место\n10:00 (мск) «Динамо Минск» — «Кайрат»\nМатч за 5 место\n11:15 (мск) «Сан Лоренсо» — «Фенербахче»\n\nМатч за 3 место\n12:30 (мск) «Палмейрас» — «Црвена Звезда»\nФинал\n13:45 (мск) «Алмаз-Антей» — «Зенит»\n\n#BurchalkinCup', 'Готовы к завтрашнему финальному дню? Вот какие игры нас ждут\n\nМатч за 7 место\n\n10:00 (мск) «Динамо Минск» — «Кайрат»\n\nМатч за 5 место\n\n11:15 (мск) «Сан Лоренсо» — «Фенербахче»\n\nМатч за 3 место\n\n12:30 (мск) «Палмейрас» — «Црвена Звезда»\n\nФинал\n\n13:45 (мск) «Алмаз-Антей» — «Зенит»\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>Готовы к завтрашнему финальному дню? Вот какие игры нас ждут</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365103/burcup/news/raspisanie-finalnogo-dnya-turnira/images/vrz5vhtqel4-1776365102239.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365103/burcup/news/raspisanie-finalnogo-dnya-turnira/images/vrz5vhtqel4-1776365102239.jpg\" alt=\"\" /></a></p>\n<p>Матч за 7 место<br />\n10:00 (мск) «Динамо Минск» — «Кайрат»<br />\nМатч за 5 место<br />\n11:15 (мск) «Сан Лоренсо» — «Фенербахче»</p>\n<p>Матч за 3 место<br />\n12:30 (мск) «Палмейрас» — «Црвена Звезда»<br />\nФинал<br />\n13:45 (мск) «Алмаз-Антей» — «Зенит»</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=raspisanie-finalnogo-dnya-turnira', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365103/burcup/news/raspisanie-finalnogo-dnya-turnira/images/vrz5vhtqel4-1776365102239.jpg', NULL, 1, '2026-04-21 11:19:47.000', '2026-04-21 11:19:47.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (20, NULL, 'vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-startoval-v-peterburge', '2025-05-16 00:00:00.000', 'VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина стартовал в Петербурге', 'Торжественная церемония открытия VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 16 мая 2025 года.\n\nБороться за Кубок Льва Бурчалкина приехали футболисты из восьми команд семи стран: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче...', 'Торжественная церемония открытия VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 16 мая 2025 года.\n\nБороться за Кубок Льва Бурчалкина приехали футболисты из восьми команд семи стран: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия) и «Алмаз-Антей» (Россия).\n\nПеред официальной церемонией открытия прошла специальная экологическая акция «Дерево дружбы». Участники команды «Сан-Лоренсо де Альмагро», впервые принимающие участие в турнире, высадили деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), «Фенербахче С.К.» (Турция), «Кайрат» (Казахстан), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).\n\nТоржественная церемония открытия началась с выступления коллектива барабанщиц. Затем на футбольном поле прошел парад команд-участниц. Когда юные спортсмены выстроились на поле перед собравшимися, хореографический ансамбль «Ритмы века» в костюмах в стиле времен Великой Отечественной войны исполнил танцевальный номер.\n\nОфициально старт турниру дали заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода, президент ФК «Алмаз-Антей» Михаил Подвязников, председатель Законодательного Собрания Санкт-Петербурга, вице-президент РФС, президент Федерации футбола Санкт-Петербурга Александр Бельский и председатель ПАО «Банк ПСБ» Петр Фрадков.\n\nАлександр Бельский поздравил участников и гостей Турнира с началом мероприятия:\n\n«Для нас большая честь приветствовать вас здесь, в Санкт-Петербурге, тем более, Турнир приурочен к 80-летию Великой Победы! Ленинград – непокорённый город, овеянный бессмертной славой, – сказал Александр Бельский. – Я всех сердечно поздравляю с прошедшим Днем Победы! Желаю всем участникам турнира мирного неба над головой, счастья и здоровья!».\n\nВ свою очередь Петр Фрадков поблагодарил руководство Обуховского завода и организаторов турнира:\n\n«Для нас, как для партнера Концерна «Алмаз-Антей» и Обуховского завода, очень важно работать и в таком формате. Я уверен, праздник получится! Всем интересного и красивого футбола. Удачи!».\n\nМихаил Подвязников от имени Концерна ВКО «Алмаз-Антей» поприветствовал юных спортсменов и любителей футбола, а также поблагодарил иностранные команды, проделавшие длинный путь в Санкт-Петербург.\n\n«Я желаю молодым людям прекрасно провести время, на мой взгляд, в лучшем городе планеты – Санкт-Петербурге! Футбол – это замечательная игра, в которую могут играть все, – сказал Михаил Подвязников. – Я уверен, мы увидим прекрасные матчи и уважительное отношение соперников друг к другу. Этот турнир обязательно запомнится его участникам на всю жизнь! Желаю всем удачи!».\n\nСледующей частью программы первого турнирного дня стал матч открытия, который сыграли команды «Алмаз-Антей» и «Динамо-Минск». Он завершился победой хозяев соревнований со счётом 3:1. Игры будут идти ежедневно по 18 мая включительно. Каждая команда сыграет пять матчей по 25 минут каждый тайм.\n\nПосетить VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина могут все желающие. Трансляция доступна на сайте турнира burcup-production.up.railway.app и на странице футбольного клуба «Алмаз-Антей» в социальной сети «ВКонтакте». Там же можно ознакомиться с подробным расписанием.\n\nВ заключительный день турнира (18 мая) соревнования начнутся с 10:00. Финал стартует в 13:45. Награждение победителей и торжественная церемония закрытия пройдут в 15:20.\n\nВ этом году информационными партнерами Турнира стали: ИТАР-ТАСС, «Спорт-Экспресс», «Фонтанка.ру», «Спорт День за Днем», «Комсомольская правда», «Радио Зенит», «Санкт-Петербургские Ведомости», телеканал «Санкт-Петербург», Российский футбольный союз и Федерация футбола Санкт-Петербурга.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз – Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. По мнению организаторов, он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году турнир приурочен к 80-летию Победы в Великой Отечественной войне. 16 мая, день старта соревнований, совпал с Днем рождения Обуховского завода (входит в Концерн ВКО «Алмаз – Антей»), предприятию исполнилось 162 года.', '<p><strong>Торжественная церемония открытия VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 16 мая 2025 года. </strong></p>\n<p>Бороться за Кубок Льва Бурчалкина приехали футболисты из восьми команд семи стран: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия) и «Алмаз-Антей» (Россия).</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/05/img_4304-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365112/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/img-4304-1776365108944.jpg\" alt=\"\" /></a></p>\n<p>Перед официальной церемонией открытия прошла специальная экологическая акция «Дерево дружбы». Участники команды «Сан-Лоренсо де Альмагро», впервые принимающие участие в турнире, высадили деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), «Фенербахче С.К.» (Турция), «Кайрат» (Казахстан), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).</p>\n<p>Торжественная церемония открытия началась с выступления коллектива барабанщиц. Затем на футбольном поле прошел парад команд-участниц. Когда юные спортсмены выстроились на поле перед собравшимися, хореографический ансамбль «Ритмы века» в костюмах в стиле времен Великой Отечественной войны исполнил танцевальный номер.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/05/img_4305-scaled.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365114/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/img-4305-1776365113054.jpg\" alt=\"\" /></a></p>\n<p>Официально старт турниру дали заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода, президент ФК «Алмаз-Антей» <strong>Михаил Подвязников, </strong>председатель Законодательного Собрания Санкт-Петербурга, вице-президент РФС, президент Федерации футбола Санкт-Петербурга Александр Бельский и председатель ПАО «Банк ПСБ» Петр Фрадков.</p>\n<p><strong> Александр Бельский</strong> поздравил участников и гостей Турнира с началом мероприятия:</p>\n<blockquote><p>«Для нас большая честь приветствовать вас здесь, в Санкт-Петербурге, тем более, Турнир приурочен к 80-летию Великой Победы! Ленинград – непокорённый город, овеянный бессмертной славой, – сказал Александр Бельский. – Я всех сердечно поздравляю с прошедшим Днем Победы! Желаю всем участникам турнира мирного неба над головой, счастья и здоровья!».</p></blockquote>\n<p>В свою очередь <strong>Петр Фрадков</strong> поблагодарил руководство Обуховского завода и организаторов турнира:</p>\n<blockquote><p>«Для нас, как для партнера Концерна «Алмаз-Антей» и Обуховского завода, очень важно работать и в таком формате. Я уверен, праздник получится! Всем интересного и красивого футбола. Удачи!».</p></blockquote>\n<p><strong>Михаил Подвязников</strong> от имени Концерна ВКО «Алмаз-Антей» поприветствовал юных спортсменов и любителей футбола, а также поблагодарил иностранные команды, проделавшие длинный путь в Санкт-Петербург.</p>\n<blockquote><p>«Я желаю молодым людям прекрасно провести время, на мой взгляд, в лучшем городе планеты –  Санкт-Петербурге! Футбол – это замечательная игра, в которую могут играть все, – сказал Михаил Подвязников. – Я уверен, мы увидим прекрасные матчи и уважительное отношение соперников друг к другу. Этот турнир обязательно запомнится его участникам на всю жизнь! Желаю всем удачи!».</p></blockquote>\n<p>Следующей частью программы первого турнирного дня стал матч открытия, который сыграли команды «Алмаз-Антей» и «Динамо-Минск». Он завершился победой хозяев соревнований со счётом 3:1. Игры будут идти ежедневно по 18 мая включительно. Каждая команда сыграет пять матчей по 25 минут каждый тайм.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/05/img_4306-scaled.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365116/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/img-4306-1776365115428.jpg\" alt=\"\" /></a></p>\n<p><strong>Посетить VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина  могут все желающие. Трансляция доступна на сайте турнира burchalkin-cup.ru и на странице футбольного клуба «Алмаз-Антей» в социальной сети «ВКонтакте». Там же можно ознакомиться с подробным расписанием.</strong></p>\n<p>В <strong>заключительный день</strong> турнира (18 мая) соревнования начнутся <strong>с 10:00</strong>. Финал стартует <strong>в 13:45</strong>. Награждение победителей и торжественная церемония закрытия пройдут <strong>в 15:20</strong>.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/05/img_4307-scaled.jpg\" data-rel=\"lightbox-image-3\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365118/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/img-4307-1776365117492.jpg\" alt=\"\" /></a></p>\n<p><strong>В этом году информационными партнерами Турнира стали: ИТАР-ТАСС, «Спорт-Экспресс», «Фонтанка.ру»,  «Спорт День за Днем», «Комсомольская правда», «Радио Зенит», «Санкт-Петербургские Ведомости», телеканал «Санкт-Петербург», Российский футбольный союз и Федерация футбола Санкт-Петербурга.</strong></p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз – Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. По мнению организаторов, он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году турнир приурочен к 80-летию Победы в Великой Отечественной войне. 16 мая, день старта соревнований, совпал с Днем рождения Обуховского завода (входит в Концерн ВКО «Алмаз – Антей»), предприятию исполнилось 162 года.</p>', 'news-article.html?slug=vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-startoval-v-peterburge', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365108/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/images/img-4303-1776365106917.jpg', NULL, 1, '2026-04-21 11:19:47.000', '2026-04-21 11:19:47.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (21, NULL, 'predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-3', '2025-05-15 00:00:00.000', 'Представляем участника — «Алмаз-Антей» (Санкт-Петербург)', 'Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга. А их более старшие товарищи борются за самые высокие места в ЮФЛ и Молодежной футбольной лиге (Дивизион Б).\n\nВ городского чемпионате после четырех туров команда идёт на третьем месте.\n\nИстория выступлений на Кубке...', 'Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга. А их более старшие товарищи борются за самые высокие места в ЮФЛ и Молодежной футбольной лиге (Дивизион Б).\n\nВ городского чемпионате после четырех туров команда идёт на третьем месте.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2016 г. — 7 место\n\n2017 г. — 3 место🥉\n\n2018 г. — 5 место\n\n2019 г. — 4 место\n\n2023 г. — 4 место\n\n2024 г. — 3 место 🥉\n\nГлавный тренер ребят 2012 г.р. — Дмитрий Прошин\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365120/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-3/images/almaz-1776365119452.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365120/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-3/images/almaz-1776365119452.png\" alt=\"\" /></a></p>\n<p>Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга. А их более старшие товарищи борются за самые высокие места в ЮФЛ и Молодежной футбольной лиге (Дивизион Б).</p>\n<p>В городского чемпионате после четырех туров команда идёт на третьем месте.</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2016 г. — 7 место<br />\n2017 г. — 3 место&#x1f949;<br />\n2018 г. — 5 место<br />\n2019 г. — 4 место<br />\n2023 г. — 4 место<br />\n2024 г. — 3 место &#x1f949;</p>\n<p>Главный тренер ребят 2012 г.р. — Дмитрий Прошин</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-3', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365120/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-3/images/almaz-1776365119452.png', NULL, 1, '2026-04-21 11:19:48.000', '2026-04-21 11:19:48.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (22, NULL, 'vse-matchi-kubka-burchalkina-my-pokazhem-v-pryamom-efire', '2025-05-14 00:00:00.000', 'Все матчи Кубка Бурчалкина мы покажем в прямом эфире!', 'Трансляции будут доступны:\n\n— в нашей группе ВКонтакте\n\n— на нашем сайте в разделе «Мультимедиа»\n#КубокБурчалкина', 'Трансляции будут доступны:\n\n— в нашей группе ВКонтакте\n\nvkvideo.ru/playlist/-120721420_5: https://vk.com/away.php?to=https%3A%2F%2Fvkvideo.ru%2Fplaylist%2F-120721420_5&utf=1\n\n— на YouTube:\n\nyoutube.com/@fcalmazan…: https://vk.com/away.php?to=https%3A%2F%2Fyoutube.com%2F%40fcalmazantey%3Fsi%3Ds0rzqU9g2_fK_eFY&utf=1\n\n— на нашем сайте в разделе «Мультимедиа»\n\nburcup-production.up.railway.app/multimedia/: https://vk.com/away.php?to=http%3A%2F%2Fburcup-production.up.railway.app%2Fmultimedia%2F&utf=1\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>Трансляции будут доступны:</p>\n<p>— в нашей группе ВКонтакте<br />\n<a href=\"https://vk.com/away.php?to=https%3A%2F%2Fvkvideo.ru%2Fplaylist%2F-120721420_5&amp;utf=1\" target=\"_blank\" rel=\"nofollow noopener\">vkvideo.ru/playlist/-120721420_5</a></p>\n<p>— на YouTube:<br />\n<a href=\"https://vk.com/away.php?to=https%3A%2F%2Fyoutube.com%2F%40fcalmazantey%3Fsi%3Ds0rzqU9g2_fK_eFY&amp;utf=1\" target=\"_blank\" rel=\"nofollow noopener\">youtube.com/@fcalmazan&#8230;</a></p>\n<p>— на нашем сайте в разделе «Мультимедиа»<br />\n<a href=\"https://vk.com/away.php?to=http%3A%2F%2Fburchalkin-cup.ru%2Fmultimedia%2F&amp;utf=1\" target=\"_blank\" rel=\"nofollow noopener\">burchalkin-cup.ru/multimedia/</a></p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91