INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (23, NULL, 'smi-o-starte-kubka-burchalkina', '2025-05-14 00:00:00.000', 'СМИ о старте Кубка Бурчалкина', 'Российские СМИ анонсируют старт VII Кубка Бурчалкина:\n\nКомсомольская правда:', 'Российские СМИ анонсируют старт VII Кубка Бурчалкина:\n\nКомсомольская правда:https://www.spb.kp.ru/daily/27699/5087891/\n\nРадио Зенит: https://www.radiozenit.ru/news/id/25637\n\nСпорт День за Днём: https://www.sportsdaily.ru/news/v-peterburge-proydet-vii-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina\n\nСпорт-Экспресс: https://m.sport-express.ru/football/news/mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-2326730/\n\nТАСС: https://tass.ru/sport/23957793', '<p>Российские СМИ анонсируют старт VII Кубка Бурчалкина:</p>\n<p><strong>Комсомольская правда:</strong><a href=\"https://www.spb.kp.ru/daily/27699/5087891/\"> https://www.spb.kp.ru/daily/27699/5087891/ </a></p>\n<p><strong>Радио Зенит:</strong> <a href=\"https://www.radiozenit.ru/news/id/25637\">https://www.radiozenit.ru/news/id/25637</a></p>\n<p><strong>Спорт День за Днём:</strong> <a href=\"https://www.sportsdaily.ru/news/v-peterburge-proydet-vii-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina\">https://www.sportsdaily.ru/news/v-peterburge-proydet-vii-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina</a></p>\n<p><strong>Спорт-Экспресс:</strong> <a href=\"https://m.sport-express.ru/football/news/mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-2326730/\">https://m.sport-express.ru/football/news/mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-2326730/ </a></p>\n<p><strong>ТАСС:</strong> <a href=\"https://tass.ru/sport/23957793\">https://tass.ru/sport/23957793</a></p>', 'news-article.html?slug=smi-o-starte-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365126/burcup/news/smi-o-starte-kubka-burchalkina/images/env5mcdroge-1776365125284.jpg', NULL, 1, '2026-04-21 11:19:48.000', '2026-04-21 11:19:48.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (24, NULL, 'vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdyot-v-peterburge', '2025-05-14 00:00:00.000', 'VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина пройдёт в Петербурге', 'VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 16 по 18 мая 2025 года\n\nВ нём примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.\nБороться за Кубок Льва Бурчалкина будут футболисты не старше 13 лет из восьми команд...', 'VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 16 по 18 мая 2025 года\n\nВ нём примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.\n\nБороться за Кубок Льва Бурчалкина будут футболисты не старше 13 лет из восьми команд семи стран: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия) и «Алмаз-Антей» (Россия). Местом проведения международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге (проспект Обуховской Обороны, 130).\n\n16 мая в 09:30 перед официальной церемонией открытия стартует специальная экологическая акция «Дерево дружбы». Участники команды «Сан-Лоренсо де Альмагро», впервые принимающие участие в турнире, будут высаживать деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), «Фенербахче С.К.» (Турция), «Кайрат» (Казахстан), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).\n\nВ 10:00 начнется торжественная церемония открытия VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. В ней примут участие представители руководства Концерна ВКО «Алмаз-Антей», Федерации футбола Санкт-Петербурга, почётные гости. Состоится парад юных футболистов из 8 команд, принимающих участие в мероприятии.\n\nВ 10:45 начнётся матч открытия группового этапа. Первыми в борьбу за главную награду вступят команды «Алмаз-Антей» и «Динамо-Минск». Игры будут идти весь день, начало последней запланировано на 19:30.\n\nВ финале первого дня соревнований впервые состоится матч Медиа лиги между командами Азамата Мусагалиева ФК «10» и Михаила Литвина LIT ENERGY. Встреча начнется в 20:30.\n\nБолее подробное расписание первого игрового дня:\n\nВо второй соревновательный день состоятся матчи группового этапа и плей-офф. Начало первой игры запланировано на 10:00, последней – на 19:30. Каждая команда сыграет пять матчей по 25 минут каждый тайм.\n\nВ заключительный день турнира (18 мая) соревнования начнутся с 10:00. Финал стартует в 13:45. Награждение победителей и торжественная церемония закрытия пройдут в 15:20.\n\nПриглашаем представителей СМИ принять участие в освещении VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. Сбор журналистов 16 мая в 9:10 на стадионе «Алмаз-Антей».\n\nАккредитация СМИ на мероприятие проводится по тел. 8 (812) 207-21-10 или по почте pr-reklama@goz.ru. Окончание аккредитации 15.05.2025г. в 15.00.\n\nМатчи открыты для всех желающих. Трансляция будет доступна на сайте турнира burcup-production.up.railway.app и на странице футбольного клуба «Алмаз-Антей» в социальной сети «ВКонтакте».\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга.\n\nОсновная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. По мнению организаторов, он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.\n\nВ этом году турнир приурочен к 80-летию Победы в Великой Отечественной войне. 16 мая, день старта соревнований, совпадает с Днем рождения Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»), предприятию исполнится 162 года.', '<p><strong>VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 16 по 18 мая 2025 года</strong></p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365122/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/images/ypqgmgsx-4-photoroom-1776365121597.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365122/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/images/ypqgmgsx-4-photoroom-1776365121597.png\" alt=\"\" /></a></p>\n<p>В нём примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.</p>\n<p>Бороться за Кубок Льва Бурчалкина будут футболисты не старше 13 лет из восьми команд семи стран: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия) и «Алмаз-Антей» (Россия). Местом проведения международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге (проспект Обуховской Обороны, 130).</p>\n<p><strong>16 мая в 09:30</strong> перед официальной церемонией открытия стартует специальная экологическая акция «Дерево дружбы». Участники команды «Сан-Лоренсо де Альмагро», впервые принимающие участие в турнире, будут высаживать деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), «Фенербахче С.К.» (Турция), «Кайрат» (Казахстан), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).</p>\n<p><strong>В 10:00</strong> начнется торжественная церемония открытия VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. В ней примут участие представители руководства Концерна ВКО «Алмаз-Антей», Федерации футбола Санкт-Петербурга, почётные гости. Состоится парад юных футболистов из 8 команд, принимающих участие в мероприятии.</p>\n<p><strong>В 10:45</strong> начнётся матч открытия группового этапа. Первыми в борьбу за главную награду вступят команды «Алмаз-Антей» и «Динамо-Минск». Игры будут идти весь день, начало последней запланировано <strong>на 19:30</strong>.</p>\n<p>В финале первого дня соревнований впервые состоится матч Медиа лиги между командами Азамата Мусагалиева ФК «10» и Михаила Литвина LIT ENERGY. Встреча начнется <strong>в 20:30</strong>.</p>\n<p>Более подробное расписание первого игрового дня:</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365124/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/rasp-1-den-1776365123588.png\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365124/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/gallery/rasp-1-den-1776365123588.png\" alt=\"\" /></a></p>\n<p>Во второй соревновательный день состоятся матчи группового этапа и плей-офф. Начало первой игры запланировано <strong>на 10:00</strong>, последней – <strong>на 19:30</strong>. Каждая команда сыграет пять матчей по 25 минут каждый тайм.</p>\n<p><strong>В</strong> <strong>заключительный день</strong> турнира (18 мая) соревнования начнутся <strong>с 10:00</strong>. Финал стартует <strong>в 13:45</strong>. Награждение победителей и торжественная церемония закрытия пройдут <strong>в 15:20</strong>.</p>\n<p><strong>Приглашаем представителей СМИ принять участие в освещении VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. Сбор журналистов 16 мая в 9:10 на стадионе «Алмаз-Антей».</strong></p>\n<p><strong>Аккредитация СМИ на мероприятие проводится по тел. </strong>8 (812) 207-21-10<strong> или по почте</strong> pr-reklama@goz.ru. Окончание аккредитации 15.05.2025г. в 15.00.</p>\n<p>Матчи открыты для всех желающих. Трансляция будет доступна на сайте турнира burchalkin-cup.ru и на странице футбольного клуба «Алмаз-Антей» в социальной сети «ВКонтакте».</p>\n\n<blockquote>\n<p data-sep=\"17\"><em>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга.</em></p>\n<p><em>Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. По мнению организаторов, он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.</em></p>\n<p><em>В этом году турнир приурочен к 80-летию Победы в Великой Отечественной войне. 16 мая, день старта соревнований, совпадает с Днем рождения Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»), предприятию исполнится 162 года.</em></p>\n</blockquote>', 'news-article.html?slug=vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdyot-v-peterburge', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365122/burcup/news/vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina/images/ypqgmgsx-4-photoroom-1776365121597.png', NULL, 1, '2026-04-21 11:19:48.000', '2026-04-21 11:19:48.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (25, NULL, 'predstavlyaem-uchastnika-san-lorenso-de-almagro', '2025-05-12 00:00:00.000', 'Представляем участника — «Сан Лоренсо де Альмагро»', 'Главная команда «Сан Лоренсо» — один из сильнейших и популярнейших аргентинских футбольных клубов из Буэнос-Айреса. В его истории были 12 побед в чемпионате Аргентины, завоевание Кубка Либертадорес и Южноамериканского кубка.\n\nКлуб активно участвует в развитии молодежного спорта и имеет собственную академию для юных футболистов. Воспитанники...', 'Главная команда «Сан Лоренсо» — один из сильнейших и популярнейших аргентинских футбольных клубов из Буэнос-Айреса. В его истории были 12 побед в чемпионате Аргентины, завоевание Кубка Либертадорес и Южноамериканского кубка.\n\nКлуб активно участвует в развитии молодежного спорта и имеет собственную академию для юных футболистов. Воспитанники 2012 года рождения выступают в столичном чемпионате Infantiles de AFA, а также принимают участие в международных турнирах. Недавно ребята вернулись из Аякучо (город на юге Перу), где стали победителями местного турнира.\n\nНа Кубок Бурчалкина команда «Сан Лоренсо» приедет впервые! 💥\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365128/burcup/news/predstavlyaem-uchastnika-san-lorenso-de-almagro/images/san-lorenso-1776365127932.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365128/burcup/news/predstavlyaem-uchastnika-san-lorenso-de-almagro/images/san-lorenso-1776365127932.png\" alt=\"\" /></a></p>\n<p>Главная команда «Сан Лоренсо» — один из сильнейших и популярнейших аргентинских футбольных клубов из Буэнос-Айреса. В его истории были 12 побед в чемпионате Аргентины, завоевание Кубка Либертадорес и Южноамериканского кубка.</p>\n<p>Клуб активно участвует в развитии молодежного спорта и имеет собственную академию для юных футболистов. Воспитанники 2012 года рождения выступают в столичном чемпионате Infantiles de AFA, а также принимают участие в международных турнирах. Недавно ребята вернулись из Аякучо (город на юге Перу), где стали победителями местного турнира.</p>\n<p>На Кубок Бурчалкина команда «Сан Лоренсо» приедет впервые! &#x1f4a5;</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-san-lorenso-de-almagro', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365128/burcup/news/predstavlyaem-uchastnika-san-lorenso-de-almagro/images/san-lorenso-1776365127932.png', NULL, 1, '2026-04-21 11:19:48.000', '2026-04-21 11:19:48.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (26, NULL, 'predstavlyaem-uchastnika-kajrat-kazahstan-2', '2025-05-11 00:00:00.000', 'Представляем участника — «Кайрат» (Казахстан)', 'Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается больше 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.\n\nТакже развитию футбольных навыков юных спортсменов помогает масштабный детский...', 'Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается больше 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.\n\nТакже развитию футбольных навыков юных спортсменов помогает масштабный детский чемпионат — «Кайрат-Лига». В нем участвуют около 100 команд филиалов и франшиз клуба в пяти разных возрастных группах.\n\nВ марте команда 2012 г.р. приняла участие в международном турнире «Науруз Кап», где одержала победу.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2024 г. — 5 место\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365130/burcup/news/predstavlyaem-uchastnika-kajrat-kazahstan-2/images/kajrat-1776365129693.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365130/burcup/news/predstavlyaem-uchastnika-kajrat-kazahstan-2/images/kajrat-1776365129693.png\" alt=\"\" /></a></p>\n<p>Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается больше 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.</p>\n<p>Также развитию футбольных навыков юных спортсменов помогает масштабный детский чемпионат — «Кайрат-Лига». В нем участвуют около 100 команд филиалов и франшиз клуба в пяти разных возрастных группах.</p>\n<p>В марте команда 2012 г.р. приняла участие в международном турнире «Науруз Кап», где одержала победу.</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2024 г. — 5 место</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-kajrat-kazahstan-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365130/burcup/news/predstavlyaem-uchastnika-kajrat-kazahstan-2/images/kajrat-1776365129693.png', NULL, 1, '2026-04-21 11:19:49.000', '2026-04-21 11:19:49.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (27, NULL, 'do-starta-kubka-burchalkina-ostalos-10-dnej', '2025-05-08 00:00:00.000', 'Представляем участника — «Палмейрас» (Бразилия)', 'Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.\n\nЦентр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из...', 'Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.\n\nЦентр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из основных в Бразилии. На счету его воспитанников десятки крупных титулов и большое количество рекордов.\n\nВ Академии занимаются ребята девяти возрастов. Одной из особенностей подготовки является участие в соревнованиях за границей. Так как ребята приобретают важный опыт, играя с ведущими клубами мира.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2023 г. — 2 место 🥈\n\n2024 г. — 1 место 🥇\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365139/burcup/news/do-starta-kubka-burchalkina-ostalos-10-dnej/images/palmejras-1776365138499.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365139/burcup/news/do-starta-kubka-burchalkina-ostalos-10-dnej/images/palmejras-1776365138499.png\" alt=\"\" /></a></div>\n<p>Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.</p>\n<p>Центр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из основных в Бразилии. На счету его воспитанников десятки крупных титулов и большое количество рекордов.</p>\n<p>В Академии занимаются ребята девяти возрастов. Одной из особенностей подготовки является участие в соревнованиях за границей. Так как ребята приобретают важный опыт, играя с ведущими клубами мира.</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2023 г. — 2 место &#x1f948;<br />\n2024 г. — 1 место &#x1f947;</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=do-starta-kubka-burchalkina-ostalos-10-dnej', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365139/burcup/news/do-starta-kubka-burchalkina-ostalos-10-dnej/images/palmejras-1776365138499.png', NULL, 1, '2026-04-21 11:19:49.000', '2026-04-21 11:19:49.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (28, NULL, 'tradiczionnaya-akcziya-derevo-druzhby', '2025-05-08 00:00:00.000', 'Традиционная акция «Дерево дружбы»', 'Перед стартом турнира команды, которые впервые участвуют в Кубке Бурчалкина, высаживают свои именные деревья на Аллее дружбы. Эта специальная экологическая акция проходит у нас ежегодно.\n\nА те клубы, которые приезжают к нам на турнир вновь, могут пронаблюдать, как растет и крепнет их деревце.\n\n#КубокБурчалкина', 'Перед стартом турнира команды, которые впервые участвуют в Кубке Бурчалкина, высаживают свои именные деревья на Аллее дружбы. Эта специальная экологическая акция проходит у нас ежегодно.\n\nА те клубы, которые приезжают к нам на турнир вновь, могут пронаблюдать, как растет и крепнет их деревце.\n\n\\: https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365134/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/zraphpule2m-1776365133264.jpg https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365136/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/n-gn4salljm-1776365135039.jpg\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>Перед стартом турнира команды, которые впервые участвуют в Кубке Бурчалкина, высаживают свои именные деревья на Аллее дружбы. Эта специальная экологическая акция проходит у нас ежегодно.</p>\n<p>А те клубы, которые приезжают к нам на турнир вновь, могут пронаблюдать, как растет и крепнет их деревце.</p>\n<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365134/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/zraphpule2m-1776365133264.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365134/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/zraphpule2m-1776365133264.jpg\" alt=\"\" /></a></div>\n<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365134/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/zraphpule2m-1776365133264.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\">\\</a> <a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365136/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/n-gn4salljm-1776365135039.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365136/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/n-gn4salljm-1776365135039.jpg\" alt=\"\" /><br />\n</a></div>\n\n<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365137/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/bg2or9ltc9w-1776365136757.jpg\" data-rel=\"lightbox-image-3\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365137/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/gallery/bg2or9ltc9w-1776365136757.jpg\" alt=\"\" /></a></div>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=tradiczionnaya-akcziya-derevo-druzhby', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365132/burcup/news/tradiczionnaya-akcziya-derevo-druzhby/images/uef1bcyn3sa-1776365131535.jpg', NULL, 1, '2026-04-21 11:19:49.000', '2026-04-21 11:19:49.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (29, NULL, 'predstavlyaem-uchastnika-dinamo-minsk-belorussiya', '2025-05-07 00:00:00.000', 'Представляем участника — «Динамо-Минск» (Белоруссия)', 'Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в...', 'Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в динамовской Академии занимаются более 400 человек.\n\nДважды в год (май и сентябрь) проводится открытый просмотр для ребят в возрасте от 5 до 8 лет. Также регулярно проводятся отборы в группы подготовки для девочек.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2024 г. — 7 место\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365141/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belorussiya/images/dinamo-m-1776365140168.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365141/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belorussiya/images/dinamo-m-1776365140168.png\" alt=\"\" /></a></p>\n<p>Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в динамовской Академии занимаются более 400 человек.</p>\n<p>Дважды в год (май и сентябрь) проводится открытый просмотр для ребят в возрасте от 5 до 8 лет. Также регулярно проводятся отборы в группы подготовки для девочек.</p>\n<p><strong>История выступлений на Кубке Бурчалкина:</strong></p>\n<p>2024 г. — 7 место</p>\n\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-dinamo-minsk-belorussiya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365141/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belorussiya/images/dinamo-m-1776365140168.png', NULL, 1, '2026-04-21 11:19:49.000', '2026-04-21 11:19:49.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (30, NULL, 'ot-kubka-burchalkina-do-sbornoj-rossii', '2025-05-03 00:00:00.000', 'От Кубка Бурчалкина до сборной России', '2018 год: воспитанник «Зенита» Никита Лобов принимает участие в Кубке Бурчалкина и становится бронзовым призёром турнира.\n\n2025 год: Никита Лобов — игрок национальной молодежной сборной России. В мартовском товарищеском матче против сборной Колумбии он вышел в стартовом составе и провел на поле все 90 минут.\n\nКак быстро растут наши дети!...', '2018 год: воспитанник «Зенита» Никита Лобов принимает участие в Кубке Бурчалкина и становится бронзовым призёром турнира.\n\n2025 год: Никита Лобов — игрок национальной молодежной сборной России. В мартовском товарищеском матче против сборной Колумбии он вышел в стартовом составе и провел на поле все 90 минут.\n\nКак быстро растут наши дети! Гордимся 👏', '<p>2018 год: воспитанник «Зенита» Никита Лобов принимает участие в Кубке Бурчалкина и становится бронзовым призёром турнира.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365146/burcup/news/ot-kubka-burchalkina-do-sbornoj-rossii/gallery/bez-imeni-1-1776365145152.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365146/burcup/news/ot-kubka-burchalkina-do-sbornoj-rossii/gallery/bez-imeni-1-1776365145152.png\" alt=\"\" /></a></p>\n<p>2025 год: Никита Лобов — игрок национальной молодежной сборной России. В мартовском товарищеском матче против сборной Колумбии он вышел в стартовом составе и провел на поле все 90 минут.</p>\n<p>Как быстро растут наши дети! Гордимся &#x1f44f;</p>', 'news-article.html?slug=ot-kubka-burchalkina-do-sbornoj-rossii', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365143/burcup/news/ot-kubka-burchalkina-do-sbornoj-rossii/images/bez-imeni-1-1-1776365142490.png', NULL, 1, '2026-04-21 11:19:50.000', '2026-04-21 11:19:50.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (31, NULL, 'predstavlyaem-uchastnika-czrvena-zvezda-serbiya-2', '2025-04-30 00:00:00.000', 'Представляем участника — «Црвена звезда» (Сербия)', '«Црвена звезда» сегодня считается самой масштабной, самой популярной и самой титулованной спортивной командой балканского региона. Свои домашние матчи команда проводит на стадионе «Райко Митич», который болельщики называют «Мараканой». В переводе с сербского «Црвена Звезда» означает «Красная звезда».\n\nГлавная команда «красно-белых» по...', '«Црвена звезда» сегодня считается самой масштабной, самой популярной и самой титулованной спортивной командой балканского региона. Свои домашние матчи команда проводит на стадионе «Райко Митич», который болельщики называют «Мараканой». В переводе с сербского «Црвена Звезда» означает «Красная звезда».\n\nГлавная команда «красно-белых» по итогам этого сезона досрочно оформила 36-й титул чемпионов страны 🏆\n\nАкадемия «Црвены звезды» — ведущая футбольная академия Сербии. Интересный факт: до 13 лет детские тренеры школы не разделяют футболистов по амплуа. А в работе с ребятами из команд U-13 упор делается на связывание технико-тактических и практических навыков игры.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2023 г. — 5 место\n\n2024 г. — 4 место\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<div data-testid=\"showmoretext\">\n<div data-testid=\"showmoretext-in-expanded\">\n<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365148/burcup/news/predstavlyaem-uchastnika-czrvena-zvezda-serbiya-2/images/czrvena-1776365147338.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365148/burcup/news/predstavlyaem-uchastnika-czrvena-zvezda-serbiya-2/images/czrvena-1776365147338.png\" alt=\"\" /></a></p>\n\n<p>«Црвена звезда» сегодня считается самой масштабной, самой популярной и самой титулованной спортивной командой балканского региона. Свои домашние матчи команда проводит на стадионе «Райко Митич», который болельщики называют «Мараканой». В переводе с сербского «Црвена Звезда» означает «Красная звезда».</p>\n\n<p>Главная команда «красно-белых» по итогам этого сезона досрочно оформила 36-й титул чемпионов страны &#x1f3c6;</p>\n\n<p>Академия «Црвены звезды» — ведущая футбольная академия Сербии. Интересный факт: до 13 лет детские тренеры школы не разделяют футболистов по амплуа. А в работе с ребятами из команд U-13 упор делается на связывание технико-тактических и практических навыков игры.</p>\n\n<p><strong>История выступлений на Кубке Бурчалкина:</strong></p>\n\n<p>2023 г. — 5 место<br />\n2024 г. — 4 место</p>\n\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></div>\n</div>\n</div>', 'news-article.html?slug=predstavlyaem-uchastnika-czrvena-zvezda-serbiya-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365148/burcup/news/predstavlyaem-uchastnika-czrvena-zvezda-serbiya-2/images/czrvena-1776365147338.png', NULL, 1, '2026-04-21 11:19:50.000', '2026-04-21 11:19:50.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (32, NULL, 'nazad-v-2024-god', '2025-04-28 00:00:00.000', 'Назад в 2024 год', 'Как это было в 2024 году? Собрали для вас самые яркие моменты VI Кубка Бурчалкина 🔥', 'Как это было в 2024 году? Собрали для вас самые яркие моменты VI Кубка Бурчалкина 🔥', '<p>Как это было в 2024 году? Собрали для вас самые яркие моменты VI Кубка Бурчалкина &#x1f525;</p>', 'news-article.html?slug=nazad-v-2024-god', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365071/burcup/news/pervye-uchastniki-kubka-burchalkina-2026/images/img-7103-1776365070508.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776367687/burcup/news/nazad-v-2024-god/videos/6703305460276-1776367684868.mp4', 1, '2026-04-21 11:19:50.000', '2026-04-21 11:19:50.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (33, NULL, 'predstavlyaem-uchastnika-zenit-sankt-peterburg-3', '2025-04-27 00:00:00.000', 'Представляем участника — «Зенит» (Санкт-Петербург)', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».\n\nВ конце прошлого года...', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».\n\nВ конце прошлого года «Зенит» U-13 стал победителем IV Кубка Варламова и турнира памяти Галимова, который проходил в Казани. Также в конце марта «сине-бело-голубые» вернулись из Казахстана, где они стали бронзовыми призерами международного турнира «Науруз Кап».\n\nИстория выступлений на Кубке Бурчалкина:\n\n2016 г. — 2 место🥈\n\n2017 г. — 7 место\n\n2018 г. — 3 место🥉\n\n2019 г. — 2 место🥈\n\n2023 г. — 1 место 🥇\n\n2024 г. — 2 место 🥈\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365150/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-3/images/zenit-13-1776365149987.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365150/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-3/images/zenit-13-1776365149987.png\" alt=\"\" /></a></p>\n<p>Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».</p>\n<p>В конце прошлого года «Зенит» U-13 стал победителем IV Кубка Варламова и турнира памяти Галимова, который проходил в Казани. Также в конце марта «сине-бело-голубые» вернулись из Казахстана, где они стали бронзовыми призерами международного турнира «Науруз Кап».</p>\n<p><strong>История выступлений на Кубке Бурчалкина:</strong></p>\n<p>2016 г. — 2 место&#x1f948;<br />\n2017 г. — 7 место<br />\n2018 г. — 3 место&#x1f949;<br />\n2019 г. — 2 место&#x1f948;<br />\n2023 г. — 1 место &#x1f947;<br />\n2024 г. — 2 место &#x1f948;</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-zenit-sankt-peterburg-3', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365150/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-3/images/zenit-13-1776365149987.png', NULL, 1, '2026-04-21 11:19:50.000', '2026-04-21 11:19:50.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (34, NULL, 'obmenu-mezhdunarodnym-opytom-byt', '2025-04-24 00:00:00.000', 'Обмену международным опытом БЫТЬ!', 'В рамках Кубка Льва Бурчалкина организован тренерский семинар, на котором выступят представители команд «Сан Лоренсо де Альмагро» (Аргентина) и «Палмейрас» (Бразилия). Коллеги из Аргентины расскажут о недельном цикле команды U-13, а тренеры из Бразилии – об особенностях физической подготовки игроков в возрасте 12-17 лет.\n\nВстреча...', 'В рамках Кубка Льва Бурчалкина организован тренерский семинар, на котором выступят представители команд «Сан Лоренсо де Альмагро» (Аргентина) и «Палмейрас» (Бразилия). Коллеги из Аргентины расскажут о недельном цикле команды U-13, а тренеры из Бразилии – об особенностях физической подготовки игроков в возрасте 12-17 лет.\n\nВстреча пройдёт 17 мая в 21:00 в гостинице «Москва» (пл. Александра Невского, 2. Тверской зал, 2 этаж)\n\nУчастие бесплатное!\n\nКоличество мест ограничено, спешите зарегистрироваться по ссылке:\n\nhttps://forms.yandex.ru/u/6808c45550569051e292b2a0/: https://vk.com/away.php?to=https%3A%2F%2Fforms.yandex.ru%2Fu%2F6808c45550569051e292b2a0%2F&utf=1\n\n#КубокБурчалкина #BurchalkinCup', '<p>В рамках Кубка Льва Бурчалкина организован тренерский семинар, на котором выступят представители команд <strong>«Сан Лоренсо де Альмагро»</strong> (Аргентина) и <strong>«Палмейрас»</strong> (Бразилия). Коллеги из Аргентины расскажут о недельном цикле команды U-13, а тренеры из Бразилии – об особенностях физической подготовки игроков в возрасте 12-17 лет.</p>\n<p>Встреча пройдёт <strong>17 мая в 21:00</strong> в гостинице «Москва» (пл. Александра Невского, 2. Тверской зал, 2 этаж)</p>\n<p>Участие бесплатное!<br />\nКоличество мест ограничено, спешите зарегистрироваться по ссылке:</p>\n<p><a href=\"https://vk.com/away.php?to=https%3A%2F%2Fforms.yandex.ru%2Fu%2F6808c45550569051e292b2a0%2F&amp;utf=1\" target=\"_blank\" rel=\"noopener noreferrer\">https://forms.yandex.ru/u/6808c45550569051e292b2a0/</a></p>\n<p>#КубокБурчалкина #BurchalkinCup</p>', 'news-article.html?slug=obmenu-mezhdunarodnym-opytom-byt', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365153/burcup/news/obmenu-mezhdunarodnym-opytom-byt/images/anons-01-1776365151809.png', NULL, 1, '2026-04-21 11:19:50.000', '2026-04-21 11:19:50.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (35, NULL, 'predstavlyaem-uchastnika-fenerbahche-turcziya-2', '2025-04-23 00:00:00.000', 'Представляем участника — «Фенербахче» (Турция)', 'Является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.\n\nНаряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в саду» и...', 'Является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.\n\nНаряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в саду» и происходит от одноимённого района Кадыкёй в Стамбуле.\n\nВ академии «Фенербахче» занимаются юные футболисты с 9 до 19 лет. До 75% из них затем делают профессиональную карьеру. Также по последним данным на территории Турции насчитывается больше 170 филиалов академии.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2024 г. — 6 место\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365154/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya-2/images/fener-1776365153755.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365154/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya-2/images/fener-1776365153755.png\" alt=\"\" /></a></p>\n<p>Является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.</p>\n<p>Наряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в саду» и происходит от одноимённого района Кадыкёй в Стамбуле.</p>\n<p>В академии «Фенербахче» занимаются юные футболисты с 9 до 19 лет. До 75% из них затем делают профессиональную карьеру. Также по последним данным на территории Турции насчитывается больше 170 филиалов академии.</p>\n<p><strong>История выступлений на Кубке Бурчалкина:</strong></p>\n<p>2024 г. — 6 место</p>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-fenerbahche-turcziya-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365154/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya-2/images/fener-1776365153755.png', NULL, 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (36, NULL, 'reportazh-telekanala-sankt-peterburg-s-zherebevki-kubka-burchalkina-2025', '2025-04-22 00:00:00.000', 'Репортаж телеканала «Санкт-Петербург» с жеребьевки Кубка Бурчалкина-2025', 'Видео: телеканал «Санкт-Петербург»: https://tvspb.ru/programs/releases/3514285', 'Видео: телеканал «Санкт-Петербург»: https://tvspb.ru/programs/releases/3514285', '<p>Видео: <a href=\"https://tvspb.ru/programs/releases/3514285\">телеканал «Санкт-Петербург»</a></p>', 'news-article.html?slug=reportazh-telekanala-sankt-peterburg-s-zherebevki-kubka-burchalkina-2025', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365156/burcup/news/reportazh-telekanala-sankt-peterburg-s-zherebevki-kubka-burchalkina-2025/images/img-6390-1776365155514.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365188/burcup/news/reportazh-telekanala-sankt-peterburg-s-zherebevki-kubka-burchalkina-2025/videos/19-sport-16-04-25-site-1776365157133.mp4', 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (37, NULL, '4693', '2025-04-21 00:00:00.000', 'Особенности VII Кубка Бурчалкина', 'Новая схема турнира, которую мы представили в прошлом году, пришлась всем по вкусу!\n\nВместе с главным судьей турнира Иваном Абросимовым подмечаем основные моменты:\n— Мы второй год будем проводить соревнования по новой схеме. Планируется два этапа: групповой и плей-офф. Время матчей: два тайма по 25 минут. Есть небольшое условие по заменам:...', 'Новая схема турнира, которую мы представили в прошлом году, пришлась всем по вкусу!\n\nВместе с главным судьей турнира Иваном Абросимовым подмечаем основные моменты:\n\n— Мы второй год будем проводить соревнования по новой схеме. Планируется два этапа: групповой и плей-офф. Время матчей: два тайма по 25 минут. Есть небольшое условие по заменам: у команд будет три слота за игру. Если игрок получает желтые карточки в двух разных матчах, третий матч он пропускает. Судить будут молодые перспективные арбитры.\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>Новая схема турнира, которую мы представили в прошлом году, пришлась всем по вкусу!</p>\n<p>Вместе с главным судьей турнира <strong>Иваном Абросимовым</strong> подмечаем основные моменты:</p>\n<blockquote><p>— Мы второй год будем проводить соревнования по новой схеме. Планируется два этапа: групповой и плей-офф. Время матчей: два тайма по 25 минут. Есть небольшое условие по заменам: у команд будет три слота за игру. Если игрок получает желтые карточки в двух разных матчах, третий матч он пропускает. Судить будут молодые перспективные арбитры.</p></blockquote>\n<div><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365191/burcup/news/4693/images/zlllvyxwdme-1776365190217.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365191/burcup/news/4693/images/zlllvyxwdme-1776365190217.jpg\" alt=\"\" /></a></div>\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=4693', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365191/burcup/news/4693/images/zlllvyxwdme-1776365190217.jpg', NULL, 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (38, NULL, 'nashi-smi-ob-itogah-zherebevki-vii-kubka-burchalkina', '2025-04-17 00:00:00.000', 'Наши СМИ об итогах жеребьевки VII Кубка Бурчалкина', 'Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка предстоящего турнира.\n\nСпорт день за днем:', 'Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка предстоящего турнира.\n\nСпорт день за днем: https://m.sportsdaily.ru/articles/match-medialigi-novyy-uchastnik-iz-argentiny-chto-zhdet-zriteley-na-kubke-lva-burchalkina\n\nКомсомольская правда: https://www.spb.kp.ru/daily/27687/5076695/\n\nСпорт-Экспресс:\n\nhttps://www.sport-express.ru/football/yflrussia/news/ispanskie-i-vengerskie-komandy-otkazalis-ot-uchastiya-v-kubke-burchalkina-2319074/\n\nТАСС: https://tass.ru/novosti-partnerov/23718735\n\nBezFormata: https://sanktpeterburg.bezformata.com/listnews/futbolniy/145090572/\n\nФонтанка.ру: https://www.fontanka.ru/2025/04/18/75351884/?erid=2SDnjeEgWbw', '<p>Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка предстоящего турнира.</p>\n<p><strong>Спорт день за днем: </strong><a href=\"https://m.sportsdaily.ru/articles/match-medialigi-novyy-uchastnik-iz-argentiny-chto-zhdet-zriteley-na-kubke-lva-burchalkina\">https://m.sportsdaily.ru/articles/match-medialigi-novyy-uchastnik-iz-argentiny-chto-zhdet-zriteley-na-kubke-lva-burchalkina </a></p>\n<p><strong>Комсомольская правда:</strong> <a href=\"https://www.spb.kp.ru/daily/27687/5076695/\">https://www.spb.kp.ru/daily/27687/5076695/</a></p>\n<p><strong>Спорт-Экспресс:</strong></p>\n<p><a href=\"https://www.sport-express.ru/football/yflrussia/news/ispanskie-i-vengerskie-komandy-otkazalis-ot-uchastiya-v-kubke-burchalkina-2319074/\">https://www.sport-express.ru/football/yflrussia/news/ispanskie-i-vengerskie-komandy-otkazalis-ot-uchastiya-v-kubke-burchalkina-2319074/ </a></p>\n<p><strong>ТАСС:</strong> <a href=\"https://tass.ru/novosti-partnerov/23718735\">https://tass.ru/novosti-partnerov/23718735 </a></p>\n<p><strong>BezFormata:</strong> <a href=\"https://sanktpeterburg.bezformata.com/listnews/futbolniy/145090572/\">https://sanktpeterburg.bezformata.com/listnews/futbolniy/145090572/</a></p>\n<p><strong>Фонтанка.ру:</strong> <a href=\"https://www.fontanka.ru/2025/04/18/75351884/?erid=2SDnjeEgWbw\">https://www.fontanka.ru/2025/04/18/75351884/?erid=2SDnjeEgWbw</a></p>', 'news-article.html?slug=nashi-smi-ob-itogah-zherebevki-vii-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365194/burcup/news/nashi-smi-ob-itogah-zherebevki-vii-kubka-burchalkina/images/218ab566159497909e3e9fc455e0d2a9-1776365194002.jpg', NULL, 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (39, NULL, 'predstavlyaem-raspisanie-vseh-treh-dnej-turnir', '2025-04-17 00:00:00.000', 'Представляем расписание всех трех дней турнир', 'Футбольную программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Динамо Минск».\n\nЗнакомимся с полным расписанием нашего турнира:', 'Футбольную программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Динамо Минск».\n\nЗнакомимся с полным расписанием нашего турнира:\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Футбольную программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Динамо Минск».</p>\n<p>Знакомимся с полным расписанием нашего турнира:</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365193/burcup/news/predstavlyaem-raspisanie-vseh-treh-dnej-turnir/images/twx3ky31j-q-1-1776365192363.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365193/burcup/news/predstavlyaem-raspisanie-vseh-treh-dnej-turnir/images/twx3ky31j-q-1-1776365192363.jpg\" alt=\"\" /></a></p>\n\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-raspisanie-vseh-treh-dnej-turnir', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365193/burcup/news/predstavlyaem-raspisanie-vseh-treh-dnej-turnir/images/twx3ky31j-q-1-1776365192363.jpg', NULL, 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (40, NULL, 'obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-futbolu-na-kubok-lva-burchalkina', '2025-04-16 00:00:00.000', 'Объявлены итоги жеребьёвки VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина', '6 апреля 2025 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 16 по 18 мая.\n«За время проведения соревнований формат...', '16 апреля 2025 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц VII Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 16 по 18 мая.\n\n«За время проведения соревнований формат турнира менялся. Каждая команда и в этом году проведет пять матчей, а не три, как было раньше, – сказал в ходе пресс-конференции заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор АО «Обуховский завод», президент футбольного клуба «Алмаз-Антей» Михаил Подвязников. – Это будет интересно как для юных футболистов, так и для болельщиков. Команды своими глазами увидят наш красивый и гостеприимный город Санкт-Петербург в период белых ночей. Многие из них, наверняка, никогда не были у нас в стране».\n\nВ этом году в соревнованиях примут участие футболисты до 13 лет из двух российских и шести зарубежных команд. Впервые в турнире поучаствует аргентинский клуб «Сан-Лоренсо де Альмагро». В ходе жеребьёвки они разделены на две группы.\n\nГруппа А\nГруппа В\n\n«Алмаз – Антей» (Россия)\n«Зенит» (Россия)\n\n«Динамо-Минск» (Белоруссия)\n«Кайрат» (Казахстан)\n\n«Црвена Звезда» (Сербия)\n«Палмейрас» (Бразилия)\n\n«Фенербахче С.К.» (Турция)\n«Сан-Лоренсо де Альмагро» (Аргентина)\n\nДепутат Законодательного собрания Санкт-Петербурга – член исполкома Федерации футбола Санкт-Петербурга Михаил Барышников отметил важность проведения соревнований:\n\n«В это непростое время организовать такой массовый международный турнир и пригласить такие команды со всего мира – это большая заслуга ФК «Алмаз-Антея». Федерация футбола Санкт-Петербурга гордится, что в нашем городе есть клуб, который выступает на равных с «Зенитом» и «Динамо», а в каких-то моментах и показывает лучшие результаты».\n\nВ свою очередь, президент Медиа лиги Николай Осипов рассказал, что в первый день проведения соревнований, 16 мая, состоится матч между командами Азамата Мусагалиева ФК «10» и Михаила Литвина LIT ENERGY.\n\nМестом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге. Спортсмены приедут в Северную столицу за день до начала соревнований. Накануне первых стартов для них будет организована культурная программа. В первый турнирный день перед церемонией открытия команда «Сан-Лоренсо де Альмагро», впервые участвующая в турнире, посадит дерево на Аллее дружбы. Традиционный матч-открытие состоится между ФК «Алмаз-Антей» и «Динамо-Минск».\n\n«Мы второй год будем проводить соревнования по новой схеме. Планируется два этапа: групповой и плей-офф. Время матчей: два тайма по 25 минут. Есть небольшое условие по заменам: у команд будет три слота за игру. Если игрок получает желтые карточки в двух разных матчах, третий матч он пропускает. Судить будут молодые перспективные арбитры», – рассказал в ходе пресс-конференции главный судья турнира Иван Абросимов.\n\nГлава Невского района Санкт-Петербурга Алексей Гульчук поблагодарил организаторов турнира за то, что в седьмой раз такой праздник пройдет в Северной столице.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке АО «Обуховский завод», АО «Концерн ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.\n\nБолее подробная информация о VII Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина размещена на сайте burcup-production.up.railway.app: https://burcup-production.up.railway.app/\n\nКонтакты для аккредитации СМИ на турнир:\n\nтел.: 8 (812) 207-21-10, почта: pr-reklama@goz.ru: mailto:pr-reklama@goz.ru', '<p><strong>16 апреля 2025 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц </strong><strong>VII</strong><strong> Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 16 по 18 мая.</strong></p>\n<blockquote><p>«За время проведения соревнований формат турнира менялся. Каждая команда и в этом году проведет пять матчей, а не три, как было раньше, – сказал в ходе пресс-конференции заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор АО «Обуховский завод», президент футбольного клуба «Алмаз-Антей» <strong>Михаил Подвязников.</strong> – Это будет интересно как для юных футболистов, так и  для болельщиков. Команды своими глазами увидят наш красивый и гостеприимный город Санкт-Петербург в период белых ночей. Многие из них, наверняка, никогда не были у нас в стране».</p></blockquote>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/04/dsc00755-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365204/burcup/news/obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-f/gallery/dsc00755-1776365200144.jpg\" alt=\"\" /></a></p>\n<p>В этом году в соревнованиях примут участие футболисты до 13 лет из двух российских и шести зарубежных команд. Впервые в турнире поучаствует аргентинский клуб «Сан-Лоренсо де Альмагро». В ходе жеребьёвки они разделены на две группы.</p>\n\n<table>\n<tbody>\n<tr>\n<td>Группа А</td>\n<td>Группа В</td>\n</tr>\n<tr>\n<td>«Алмаз – Антей» (Россия)</td>\n<td>«Зенит» (Россия)</td>\n</tr>\n<tr>\n<td>«Динамо-Минск» (Белоруссия)</td>\n<td>«Кайрат» (Казахстан)</td>\n</tr>\n<tr>\n<td>«Црвена Звезда» (Сербия)</td>\n<td>«Палмейрас» (Бразилия)</td>\n</tr>\n<tr>\n<td>«Фенербахче С.К.» (Турция)</td>\n<td>«Сан-Лоренсо де Альмагро» (Аргентина)</td>\n</tr>\n</tbody>\n</table>\n\n<p>Депутат Законодательного собрания Санкт-Петербурга  – член исполкома Федерации футбола Санкт-Петербурга <strong>Михаил Барышников</strong> отметил важность проведения соревнований:</p>\n<blockquote><p>«В это непростое время организовать такой массовый международный турнир и пригласить такие команды со всего мира – это большая заслуга ФК «Алмаз-Антея». Федерация футбола Санкт-Петербурга гордится, что в нашем городе есть клуб, который выступает на равных с «Зенитом» и «Динамо», а в каких-то моментах и показывает лучшие результаты».</p></blockquote>\n<p>В свою очередь, президент Медиа лиги <strong>Николай Осипов</strong> рассказал, что в первый день проведения соревнований, 16 мая, состоится матч между командами Азамата Мусагалиева <strong>ФК «10»</strong> и Михаила Литвина <strong>LIT ENERGY.</strong></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/04/dsc00679-scaled.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365211/burcup/news/obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-f/gallery/dsc00679-1776365205260.jpg\" alt=\"\" /></a></p>\n<p>Местом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге. Спортсмены приедут в Северную столицу за день до начала соревнований. Накануне первых стартов для них будет организована культурная программа. В первый турнирный день перед церемонией открытия команда «Сан-Лоренсо де Альмагро», впервые участвующая в турнире, посадит дерево на Аллее дружбы. Традиционный матч-открытие состоится между ФК «Алмаз-Антей» и «Динамо-Минск».</p>\n<blockquote><p>«Мы второй год будем проводить соревнования по новой схеме. Планируется два этапа: групповой и плей-офф. Время матчей: два тайма по 25 минут. Есть небольшое условие по заменам: у команд будет три слота за игру. Если игрок получает желтые карточки в двух разных матчах, третий матч он пропускает. Судить будут молодые перспективные арбитры», – рассказал в ходе пресс-конференции главный судья турнира <strong>Иван Абросимов.</strong></p></blockquote>\n<p>Глава Невского района Санкт-Петербурга<strong> Алексей Гульчук</strong> поблагодарил организаторов турнира за то, что в седьмой раз такой праздник пройдет в Северной столице.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2025/04/dsc00792-scaled.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365218/burcup/news/obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-f/gallery/dsc00792-1776365212021.jpg\" alt=\"\" /></a></p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке АО «Обуховский завод», АО «Концерн ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.</p>\n\n<p>Более подробная информация о VII Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина размещена на сайте <a href=\"https://burcup-production.up.railway.app/\">burchalkin-cup.ru </a></p>\n<p><em>Контакты для аккредитации СМИ на турнир: </em></p>\n<p>тел.: 8 (812) 207-21-10, почта: <a href=\"mailto:pr-reklama@goz.ru\">pr-reklama@goz.ru</a></p>', 'news-article.html?slug=obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-futbolu-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365199/burcup/news/obyavleny-itogi-zherebyovki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-f/images/dsc00750-1776365197789.jpg', NULL, 1, '2026-04-21 11:19:52.000', '2026-04-21 11:19:52.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (41, NULL, 'rezultaty-zherebevki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva-burchalkina', '2025-04-16 00:00:00.000', 'Результаты жеребьевки VII Международного детско-юношеского турнира на Кубок Льва Бурчалкина', 'Турнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 16 по 18 мая 2025 года.\n\n#BurchalkinCup', 'Турнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 16 по 18 мая 2025 года.\n\n#КубокБурчалкина: https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0§ion=search #BurchalkinCup: https://vk.com/feed?q=%23BurchalkinCup§ion=search', '<p>Турнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 16 по 18 мая 2025 года.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365196/burcup/news/rezultaty-zherebevki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lv/images/zherebyevka-2025-itogi-montazhnaya-oblast-1-1776365195533.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365196/burcup/news/rezultaty-zherebevki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lv/images/zherebyevka-2025-itogi-montazhnaya-oblast-1-1776365195533.png\" alt=\"\" /></a></p>\n\n<p><a href=\"https://vk.com/feed?q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0&amp;section=search\" data-testid=\"post-text-hashtag\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?q=%23BurchalkinCup&amp;section=search\" data-testid=\"post-text-hashtag\">#BurchalkinCup</a></p>', 'news-article.html?slug=rezultaty-zherebevki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365196/burcup/news/rezultaty-zherebevki-vii-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lv/images/zherebyevka-2025-itogi-montazhnaya-oblast-1-1776365195533.png', NULL, 1, '2026-04-21 11:19:51.000', '2026-04-21 11:19:51.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (42, NULL, 'federacziya-futbola-sankt-peterburga-priglashaet-na-nash-turnir', '2025-04-11 00:00:00.000', 'Федерация футбола Санкт-Петербурга приглашает на наш турнир', 'В Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина\n\nС 16 по 18 мая в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\n\nТрофей разыграют 8 команд мальчиков до 13 лет: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция),...', 'В Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина\n\nС 16 по 18 мая в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\n\nТрофей разыграют 8 команд мальчиков до 13 лет: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз – Антей» (Россия).\n\nЖеребьевка соревнований состоится 16 апреля конференц-зале Главной проходной Обуховского завода.\n\nТурнир проводится в память легендарного форварда ФК «Зенит», начинавшего свою футбольную карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»).\n\nИсточник: https://stat.ffspb.org/news/1677515', '<h1>В Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина</h1>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365220/burcup/news/federacziya-futbola-sankt-peterburga-priglashaet-na-nash-turnir/images/newsktcmlvxcbs-1776365219291.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365220/burcup/news/federacziya-futbola-sankt-peterburga-priglashaet-na-nash-turnir/images/newsktcmlvxcbs-1776365219291.jpg\" alt=\"\" /></a></p>\n<p><strong>С 16 по 18 мая в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.</strong></p>\n<p>Трофей разыграют 8 команд мальчиков до 13 лет: «Сан-Лоренсо де Альмагро» (Аргентина), «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз – Антей» (Россия).</p>\n<p>Жеребьевка соревнований состоится 16 апреля конференц-зале Главной проходной Обуховского завода.</p>\n<p>Турнир проводится в память легендарного форварда ФК «Зенит», начинавшего свою футбольную карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»).</p>\n<p><strong><em>Источник:</em> <a href=\"https://stat.ffspb.org/news/1677515\">https://stat.ffspb.org/news/1677515</a> </strong></p>', 'news-article.html?slug=federacziya-futbola-sankt-peterburga-priglashaet-na-nash-turnir', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365220/burcup/news/federacziya-futbola-sankt-peterburga-priglashaet-na-nash-turnir/images/newsktcmlvxcbs-1776365219291.jpg', NULL, 1, '2026-04-21 11:19:52.000', '2026-04-21 11:19:52.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (43, NULL, 'retro-puteshestvie-s-lvom-burchalkinym', '2025-04-10 00:00:00.000', 'Ретро путешествие с Львом Бурчалкиным', 'Защитник Александр Дерёмов, нападающий Лев Бурчалкин и защитник Михаил Лохов на базе «Зенита» летом 1972 года 🤩\n\n📸', 'Защитник Александр Дерёмов, нападающий Лев Бурчалкин и защитник Михаил Лохов на базе «Зенита» летом 1972 года 🤩\n\n📸 История «Зенита»: https://vk.com/zenithistory?from=groups', '<p>Защитник Александр Дерёмов, нападающий Лев Бурчалкин и защитник Михаил Лохов на базе «Зенита» летом 1972 года &#x1f929;</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365221/burcup/news/retro-puteshestvie-s-lvom-burchalkinym/images/xb6nosi1jcm-1776365220726.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365221/burcup/news/retro-puteshestvie-s-lvom-burchalkinym/images/xb6nosi1jcm-1776365220726.jpg\" alt=\"\" /></a></p>\n<p>&#x1f4f8; <a href=\"https://vk.com/zenithistory?from=groups\">История «Зенита»</a></p>', 'news-article.html?slug=retro-puteshestvie-s-lvom-burchalkinym', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365221/burcup/news/retro-puteshestvie-s-lvom-burchalkinym/images/xb6nosi1jcm-1776365220726.jpg', NULL, 1, '2026-04-21 11:19:52.000', '2026-04-21 11:19:52.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (44, NULL, 'v-peterburge-projdet-press-konferencziya-o-vii-mezhdunarodnom-detsko-yunosheskom-turnire-po-futbolu-na-kubok-lva-burchalkina', '2025-04-09 00:00:00.000', 'В Петербурге пройдет пресс-конференция о VII Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина', '6 апреля в 11:00 состоится пресс-конференция, посвященная VII Международному детско-юношескому турниру по футболу на Кубок Льва Бурчалкина.\n\nМероприятие пройдет в конференц-зале Главной проходной Обуховского завода (пр-т Обуховской обороны, д. 120), где организаторы и представители футбольной общественности подробно расскажут о...', '16 апреля в 11:00 состоится пресс-конференция, посвященная VII Международному детско-юношескому турниру по футболу на Кубок Льва Бурчалкина.\n\nМероприятие пройдет в конференц-зале Главной проходной Обуховского завода (пр-т Обуховской обороны, д. 120), где организаторы и представители футбольной общественности подробно расскажут о предстоящем турнире. Там же пройдёт жеребьёвка среди детско-юношеских команд. В этом году в турнире примут участие две российские и шесть иностранных футбольных команд.\n\nС 16 по 18 мая 2025 года в Санкт-Петербург побороться за награду приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит», «Алмаз-Антей» (Россия) и впервые «Сан-Лоренсо де Альмагро» (Аргентина).\n\nМестом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в саду «Спартак». Турнир состоится при поддержке АО «Концерн ВКО «Алмаз-Антей», Российского футбольного союза и Федерации футбола Санкт-Петербурга.\n\nПриглашаем представителей СМИ принять участие в пресс-конференции. Сбор в 10:30.\n\nКонтакты для аккредитации:\n\n• тел.: 8 (812) 207-21-10\n\n• почта: pr-reklama@goz.ru: mailto:pr-reklama@goz.ru, press@goz.ru: mailto:press@goz.ru\n\nНеобходимые данные: ФИО, паспорт, список техники, номер машины, данные водителя. На территорию предприятия запрещен пронос техники Apple. Аккредитация заканчивается 15.04.2025 г. в 13.00.', '<p><strong>16 апреля в 11:00</strong> <strong>состоится пресс-конференция, посвященная VII Международному детско-юношескому турниру по футболу на Кубок Льва Бурчалкина.</strong></p>\n<p>Мероприятие пройдет в конференц-зале Главной проходной Обуховского завода (пр-т Обуховской обороны, д. 120), где организаторы и представители футбольной общественности подробно расскажут о предстоящем турнире. Там же пройдёт жеребьёвка среди детско-юношеских команд. В этом году в турнире примут участие две российские и шесть иностранных футбольных команд.</p>\n<p>С <strong>16 по 18 мая 2025 года</strong> в Санкт-Петербург побороться за награду приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: <strong>«Фенербахче С.К.»</strong> (Турция), <strong>«Палмейрас»</strong> (Бразилия), <strong>«Црвена Звезда»</strong> (Сербия), <strong>«Кайрат»</strong> (Казахстан), <strong>«Динамо-Минск»</strong> (Белоруссия), <strong>«Зенит»</strong>, <strong>«Алмаз-Антей»</strong> (Россия) и впервые <strong>«Сан-Лоренсо де Альмагро»</strong> (Аргентина).</p>\n<p>Местом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в саду «Спартак». Турнир состоится при поддержке АО «Концерн ВКО «Алмаз-Антей», Российского футбольного союза и Федерации футбола Санкт-Петербурга.</p>\n<p><strong>Приглашаем представителей СМИ принять участие в пресс-конференции. Сбор в 10:30.</strong></p>\n<p>Контакты для аккредитации:</p>\n<ul>\n<li>тел.: 8 (812) 207-21-10</li>\n<li>почта: <a href=\"mailto:pr-reklama@goz.ru\">pr-reklama@goz.ru</a>, <a href=\"mailto:press@goz.ru\">press@goz.ru</a></li>\n</ul>\n<p>Необходимые данные: ФИО, паспорт, список техники, номер машины, данные водителя. На территорию предприятия запрещен пронос техники Apple. Аккредитация заканчивается <strong>15.04.2025 г. в 13.00.</strong></p>', 'news-article.html?slug=v-peterburge-projdet-press-konferencziya-o-vii-mezhdunarodnom-detsko-yunosheskom-turnire-po-futbolu-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365223/burcup/news/v-peterburge-projdet-press-konferencziya-o-vii-mezhdunarodnom-detsko-yunosheskom/images/46nzn6rt27q-1776365222267.jpg', NULL, 1, '2026-04-21 11:19:52.000', '2026-04-21 11:19:52.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (45, NULL, 'konczern-vko-almaz-antej-provedyot-vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina', '2025-03-27 00:00:00.000', 'Концерн ВКО «Алмаз-Антей» проведёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина', 'С 16 по 18 мая 2025 года в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\nПобороться за награду приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат»...', 'С 16 по 18 мая 2025 года в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\n\nПобороться за награду приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия), «Алмаз-Антей» (Россия) и впервые «Сан-Лоренсо де Альмагро» (Аргентина).\n\nМестом проведения международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга.\n\nОсновная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также будет направлено на укрепление позитивного имиджа Российской Федерации и популяризацию спорта среди подрастающего поколения.\n\n16 апреля состоится пресс-конференция, на которой будет подробно рассказано о VII Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина. В рамках встречи пройдёт жеребьёвка команд.\n\nВся информация об этапах подготовки и проведения турнира будет представлена на официальном сайте: https://vk.com/away.php?to=http%3A%2F%2Fburcup-production.up.railway.app&cc_key= соревнований, а также в сообществе ВК: https://vk.com/burchalkincup. В период соревнований в официальной группе ВКонтакте будет организована прямая трансляция матчей.', '<p><strong>С 16 по 18 мая 2025 года в Санкт-Петербурге пройдёт VII Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.</strong></p>\n<p>Побороться за награду приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» (Россия), «Алмаз-Антей» (Россия) и впервые «Сан-Лоренсо де Альмагро» (Аргентина).</p>\n<p>Местом проведения международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге.</p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга.</p>\n<p>Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также будет направлено на укрепление позитивного имиджа Российской Федерации и популяризацию спорта среди подрастающего поколения.</p>\n<p data-sep=\"10\"><strong>16 апреля</strong> состоится <strong>пресс-конференция</strong>, на которой будет подробно рассказано о VII Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина. В рамках встречи пройдёт жеребьёвка команд.</p>\n<p>Вся информация об этапах подготовки и проведения турнира будет представлена на официальном <strong><a href=\"https://vk.com/away.php?to=http%3A%2F%2Fburchalkin-cup.ru&amp;cc_key=\" target=\"_blank\" rel=\"nofollow noopener\">сайте</a></strong> соревнований, а также в сообществе <strong><a href=\"https://vk.com/burchalkincup\">ВК</a></strong>. В период соревнований в официальной группе ВКонтакте будет организована прямая трансляция матчей.</p>', 'news-article.html?slug=konczern-vko-almaz-antej-provedyot-vii-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365225/burcup/news/konczern-vko-almaz-antej-provedyot-vii-mezhdunarodnyj-detsko-yunosheskij-turnir-/images/afisha-7-turnir-burchalkina-2025-01-1776365224102.png', NULL, 1, '2026-04-21 11:19:53.000', '2026-04-21 11:19:53.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (46, NULL, 'reportazh-telekanala-sankt-peterburg-o-zaklyuchitelnom-dne-turnira', '2024-05-21 00:00:00.000', 'Репортаж телеканала «Санкт-Петербург» о заключительном дне турнира', 'Видео: телеканал «Санкт-Петербург»', 'Видео: телеканал «Санкт-Петербург»', '<p>Видео: телеканал «Санкт-Петербург»</p>', 'news-article.html?slug=reportazh-telekanala-sankt-peterburg-o-zaklyuchitelnom-dne-turnira', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365231/burcup/news/reportazh-telekanala-sankt-peterburg-o-zaklyuchitelnom-dne-turnira/images/img-4780-1776365230246.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365234/burcup/news/reportazh-telekanala-sankt-peterburg-o-zaklyuchitelnom-dne-turnira/videos/reportazh-telekanala-sankt-peterburg-1776365232090.mp4', 1, '2026-04-21 11:19:54.000', '2026-04-21 11:19:54.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (47, NULL, 'fotografii-vseh-dnej-vi-kubka-burchalkina', '2024-05-21 00:00:00.000', 'Фотографии всех дней VI Кубка Бурчалкина', 'В нашей официальной группе в ВКонтакте теперь можно найти фотографии всех трех дней нашего турнира:\n\nПервый день:', 'В нашей официальной группе в ВКонтакте теперь можно найти фотографии всех трех дней нашего турнира:\n\nПервый день: https://vk.com/album-120721420_302832920\n\nВторой день: https://vk.com/album-120721420_302839138\n\nТретий день: https://vk.com/album-120721420_302846732\n\nИ бонус — Моментальные фото: https://vk.com/burchalkincup?z=album-120721420_302852416\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>В нашей официальной группе в ВКонтакте теперь можно найти фотографии всех трех дней нашего турнира:</p>\n<p><strong>Первый день:</strong> <a href=\"https://vk.com/album-120721420_302832920\">https://vk.com/album-120721420_302832920</a></p>\n<p><strong>Второй день:</strong> <a href=\"https://vk.com/album-120721420_302839138\">https://vk.com/album-120721420_302839138</a></p>\n<p><strong>Третий день:</strong> <a href=\"https://vk.com/album-120721420_302846732\">https://vk.com/album-120721420_302846732</a></p>\n<p>И бонус &#8212; Моментальные фото: <a href=\"https://vk.com/burchalkincup?z=album-120721420_302852416\">https://vk.com/burchalkincup?z=album-120721420_302852416 </a></p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=fotografii-vseh-dnej-vi-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367695/burcup/news/fotografii-vseh-dnej-vi-kubka-burchalkina/images/240519-0083-1776367694376.jpg', NULL, 1, '2026-04-21 11:19:53.000', '2026-04-21 11:19:53.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (48, NULL, 'vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-zavershilsya-v-sankt-peterburge', '2024-05-21 00:00:00.000', 'VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге', 'Торжественная церемония закрытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 19 мая 2024 года. Победу в состязаниях одержала команда «Палмейрас», серебро завоевал клуб «Зенит», бронза досталась футболистам...', 'Торжественная церемония закрытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 19 мая 2024 года. Победу в состязаниях одержала команда «Палмейрас», серебро завоевал клуб «Зенит», бронза досталась футболистам «Алмаз-Антея».\n\nВ этом году турнир прошел в обновлённом формате: впервые в нём приняли участие шесть иностранных и две российских команды. Количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут). В течение трех дней (с 17 по 19 мая 2024 года) футболисты не старше 13 лет из клубов «Фенербахче» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия) соревновались за главный трофей.\n\n17 и 18 мая 2024 года проходили групповые матчи турнира, во второй половине дня 18 мая 2024 года – плей-офф. Юные спортсмены не только боролись за победу, но и обменивались опытом.\n\nВ воскресенье, 19 мая 2024 года, команды играли за 7, 5, 3 и 1 места. Первыми финальный день соревнований открыли команды из Ирана и Белоруссии. Основное время окончилось со счётом 0:0, поэтому победителя, которым стала команда «Динамо-Минск», пришлось определять по серии пенальти. Затем в борьбу за пятое место вступили футбольные клубы «Фенербахче» и «Кайрат». Игра также завершилась со счётом 0:0. По результатам пенальти, победу одержали гости из Казахстана.\n\nВ матче за третье место встретились ФК «Алмаз-Антей» и «Црвена Звезда». Представители Сербии уступили хозяевам турнира: игра завершилась со счётом 0:1. Таким образом, «Алмаз-Антей» повторил успех 2017 года. Тогда команда заняла третье место, обыграв португальскую команду «Витория».\n\nВ финале встретились команды «Палмейрас» и победитель прошлого года «Зенит». Лучшими в VI Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина стали бразильцы, завершив финальный матч со счетом 3:0. За игрой наблюдали Полномочный представитель Президента России в Северо-Западном федеральном округе Александр Гуцан, представители Концерна ВКО «Алмаз-Антей» и администрации АО «Обуховский завод», а также Максим Бурчалкин, сын легендарного советского форварда, в честь которого названы соревнования. Поддержать спортсменов пришли жители и гости Северной столицы, поэтому на трибунах стадиона в этот день не было свободных мест.\n\nПосле игры прошла торжественная церемония закрытия турнира. К гостям и участникам с приветственным словом обратился заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода Михаил Подвязников.\n\n– Я хотел бы поблагодарить юных футболистов, особенно команды наших зарубежных партнеров из дружественных стран, за то, что приехали на наш турнир и приняли в нем участие. Как и все зрители, я получил искреннее удовольствие от той игры, которая была показана на поле. Мы будем рады увидеть вас снова», — сказал Михаил Подвязников.\n\nЦеремония подведения итогов началась с парада команд-участниц. Перед зрителями выступили черлидерши с талисманом клуба «Алмаз-Антей» Тигрушей. Памятные призы и дипломы получили все участники соревнований, а победители были награждены кубком. Некоторые игроки были отмечены специальными призами. Так, лучшим вратарём признан Дорук Языджи («Фенербахче»), защитником – Лазар Евтич («Црвена Звезда»). В номинации «Лучший полузащитник» победил Александр Агеев («Зенит»), «Лучший нападающий» – Габриэль Буэно («Палмейрас»), «Лучший бомбардир» – Кирилл Шадрин («Алмаз – Антей»), «Лучший игрок» – Лукас Морайс («Палмерайс»). Автором самого красивого гола был признан Нурман Бекнур («Кайрат»). В номинации «Лучший сейв» награду получил Амирсалех Мазахери («Сепахан»). Призом зрительских симпатий отмечен Мурило Альвес («Палмейрас»).\n\nСпециальную награду от информационного партнера турнира «Санкт-Петербургские ведомости» вручил генеральный директор издания Борис Грумбков – кубок в номинации «Лучший наставник».\n\nВ этом году он достался тренеру Велингтону Рамосу («Палмейрас»), который в свою очередь поблагодарил организаторов.\n\n– Мне очень понравилось, как организованы соревнования, уровень реализации и гостеприимства людей. Благодаря всем, с кем я общался здесь, я чувствовал себя как дома, в Бразилии. Ваша теплота, душевность – мы в этом очень похожи, – подчеркнул Велингтон Рамос.\n\nМеждународный детско-юношеского турнир по футболу на Кубок Льва Бурчалкина прошёл в Санкт-Петербурге в шестой раз. Первые четыре раза победу одерживал испанский клуб «Вильярреал», в 2023 году – ФК «Зенит», в 2024 году – бразильский «Палмейрас».\n\nИнформационными партнерами VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина выступили Российский футбольный союз, Федерация футбола Санкт-Петербурга, издания «Санкт-Петербургские ведомости», «Спорт-Экспресс», «Спорт День за Днем», «Фонтанка.ру», «Комсомольская правда», телеканал «Санкт-Петербург» и радио «Зенит». Прямую трансляцию финального матча вело информационное агентство ТАСС.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»).\n\nПресс-служба АО «Северо-Западный региональный центр Концерна ВКО «Алмаз-Антей» — Обуховский завод»', '<div>\n<div>\n<div id=\"article_view_-120721420_182958\" data-article-url=\"/@burchalkincup-vi-mezhdunarodnyi-detsko-unosheskii-turnir-po-futbol\" data-audio-context=\"article:-120721420_182958\" data-visible=\"1\">\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<p data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=75x50&amp;quality=95&amp;sign=03434caba859bfa8a5b5822594fbf0e3&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=130x87&amp;quality=95&amp;sign=558de3679011a92c634d738028db9724&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=604x403&amp;quality=95&amp;sign=2cbcc8757c47eea1ef6ab27732771c10&amp;type=album&quot;,604,403],&quot;y&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=807x538&amp;quality=95&amp;sign=9cd2a51af59f1aa0ed83bb02faaffd31&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=1280x853&amp;quality=95&amp;sign=8db8f852b10c0cb401707712a8b9b0f7&amp;type=album&quot;,1280,853],&quot;w&quot;:[&quot;https:\\/\\/sun9-73.userapi.com\\/impg\\/R8MWVCcXGtj-5v2a7jNomMQXSDBkpiBQ9ZQb7Q\\/bjpRf4rloTg.jpg?size=2560x1707&amp;quality=95&amp;sign=e40386ce9aa2a28bb29824f1517971a8&amp;type=album&quot;,2560,1707]}]\"><strong>Торжественная церемония закрытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 19 мая 2024 года. Победу в состязаниях одержала команда «Палмейрас», серебро завоевал клуб «Зенит», бронза досталась футболистам «Алмаз-Антея».</strong></p>\n</div>\n</div>\n</figure>\n<p>В этом году турнир прошел в обновлённом формате: впервые в нём приняли участие шесть иностранных и две российских команды. Количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут). В течение трех дней (с 17 по 19 мая 2024 года) футболисты не старше 13 лет из клубов «Фенербахче» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия) соревновались за главный трофей.</p>\n<p>17 и 18 мая 2024 года проходили групповые матчи турнира, во второй половине дня 18 мая 2024 года – плей-офф. Юные спортсмены не только боролись за победу, но и обменивались опытом.</p>\n<p>В воскресенье, 19 мая 2024 года, команды играли за 7, 5, 3 и 1 места. Первыми финальный день соревнований открыли команды из Ирана и Белоруссии. Основное время окончилось со счётом 0:0, поэтому победителя, которым стала команда «Динамо-Минск», пришлось определять по серии пенальти. Затем в борьбу за пятое место вступили футбольные клубы «Фенербахче» и «Кайрат». Игра также завершилась со счётом 0:0. По результатам пенальти, победу одержали гости из Казахстана.</p>\n<p>В матче за третье место встретились ФК «Алмаз-Антей» и «Црвена Звезда». Представители Сербии уступили хозяевам турнира: игра завершилась со счётом 0:1. Таким образом, «Алмаз-Антей» повторил успех 2017 года. Тогда команда заняла третье место, обыграв португальскую команду «Витория».</p>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=75x50&amp;quality=95&amp;sign=7ffcaaf4f147237cdd8abc45e2f074cc&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=130x87&amp;quality=95&amp;sign=1e6b600c4d28a21ea46254103eb911c9&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=604x403&amp;quality=95&amp;sign=732a254c1227107543f0018e3fd4cb56&amp;type=album&quot;,604,403],&quot;y&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=807x538&amp;quality=95&amp;sign=3b51ac5df3c57f45119768bd57d86546&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=1280x853&amp;quality=95&amp;sign=e16bb4ff5dacc53bb5a5f37ecd557f9a&amp;type=album&quot;,1280,853],&quot;w&quot;:[&quot;https:\\/\\/sun9-56.userapi.com\\/impg\\/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ\\/UkjPN-wu3eg.jpg?size=2560x1707&amp;quality=95&amp;sign=a1642994195742e4df1c69df9c514e23&amp;type=album&quot;,2560,1707]}]\"><img src=\"https://sun9-56.userapi.com/impg/IhvhdH87xs5g91_8KEBcxQbt3VAKjI_UMjWmYQ/UkjPN-wu3eg.jpg?size=807x538&quality=95&sign=3b51ac5df3c57f45119768bd57d86546&type=album\" alt=\"VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге, изображение №2\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<p>В финале встретились команды «Палмейрас» и победитель прошлого года «Зенит». Лучшими в VI Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина стали бразильцы, завершив финальный матч со счетом 3:0. За игрой наблюдали Полномочный представитель Президента России в Северо-Западном федеральном округе <strong>Александр Гуцан,</strong> представители Концерна ВКО «Алмаз-Антей» и администрации АО «Обуховский завод», а также <strong>Максим Бурчалкин,</strong> сын легендарного советского форварда, в честь которого названы соревнования. Поддержать спортсменов пришли жители и гости Северной столицы, поэтому на трибунах стадиона в этот день не было свободных мест.</p>\n\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=75x50&amp;quality=95&amp;sign=7e3a39f0b2b2a2f6f576b1f03cecca31&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=130x87&amp;quality=95&amp;sign=193d5efde817e3c3eb8d997038c881cc&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=604x403&amp;quality=95&amp;sign=8a7c42c329a18c83ebd06abfd2a2a255&amp;type=album&quot;,604,403],&quot;y&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=807x538&amp;quality=95&amp;sign=5467d5ad43ab97823347c8ce108f3e61&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=1280x853&amp;quality=95&amp;sign=b560f87c0ecaa37e0ce85806825c2278&amp;type=album&quot;,1280,853],&quot;w&quot;:[&quot;https:\\/\\/sun9-59.userapi.com\\/impg\\/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw\\/HR6wmsnvw6E.jpg?size=2560x1707&amp;quality=95&amp;sign=ff81d0c91c4de22c474e88e9dcde98f6&amp;type=album&quot;,2560,1707]}]\"><img src=\"https://sun9-59.userapi.com/impg/7Myb8cDm7eke7CnDfRmQGtEo6QqS5VHe8vW9Xw/HR6wmsnvw6E.jpg?size=807x538&quality=95&sign=5467d5ad43ab97823347c8ce108f3e61&type=album\" alt=\"VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге, изображение №3\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<p>После игры прошла торжественная церемония закрытия турнира. К гостям и участникам с приветственным словом обратился заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода <strong>Михаил Подвязников.</strong></p>\n<blockquote><p><em>– Я хотел бы поблагодарить юных футболистов, особенно команды наших зарубежных партнеров из дружественных стран, за то, что приехали на наш турнир и приняли в нем участие. Как и все зрители, я получил искреннее удовольствие от той игры, которая была показана на поле. Мы будем рады увидеть вас снова», &#8212; сказал Михаил Подвязников.</em></p></blockquote>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=75x50&amp;quality=95&amp;sign=e539bd891c957d665da2bed07c5aaf95&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=130x87&amp;quality=95&amp;sign=d3a811704a9357f5ebe818fe4d2caf61&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=604x403&amp;quality=95&amp;sign=aed87dbbc431b571319a120338887ab6&amp;type=album&quot;,604,403],&quot;y&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=807x538&amp;quality=95&amp;sign=596e4b2ee4cae40813dd606550ee6388&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=1280x853&amp;quality=95&amp;sign=705c74d12a77d89986d7654db9074816&amp;type=album&quot;,1280,853],&quot;w&quot;:[&quot;https:\\/\\/sun9-3.userapi.com\\/impg\\/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q\\/Mye19aEOHcI.jpg?size=2560x1707&amp;quality=95&amp;sign=c45825eaade0b35db83a059780f27d3e&amp;type=album&quot;,2560,1707]}]\"><img src=\"https://sun9-3.userapi.com/impg/ko5gSL_h2UW28GJMccT_nKMYe7Y5fX5476OL1Q/Mye19aEOHcI.jpg?size=807x538&quality=95&sign=596e4b2ee4cae40813dd606550ee6388&type=album\" alt=\"VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге, изображение №4\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<p>Церемония подведения итогов началась с парада команд-участниц. Перед зрителями выступили черлидерши с талисманом клуба «Алмаз-Антей» Тигрушей. Памятные призы и дипломы получили все участники соревнований, а победители были награждены кубком. Некоторые игроки были отмечены специальными призами. Так, лучшим вратарём признан Дорук Языджи («Фенербахче»), защитником – Лазар Евтич («Црвена Звезда»). В номинации «Лучший полузащитник» победил Александр Агеев («Зенит»), «Лучший нападающий» – Габриэль Буэно («Палмейрас»), «Лучший бомбардир» – Кирилл Шадрин («Алмаз – Антей»), «Лучший игрок» – Лукас Морайс («Палмерайс»). Автором самого красивого гола был признан Нурман Бекнур («Кайрат»). В номинации «Лучший сейв» награду получил Амирсалех Мазахери («Сепахан»). Призом зрительских симпатий отмечен Мурило Альвес («Палмейрас»).</p>\n<figure data-type=\"101\" data-mode=\"1\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=75x50&amp;quality=95&amp;sign=35f2fe330a69c8d847d600775c48f438&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=130x87&amp;quality=95&amp;sign=5da3931d2ae344120c0133860acabc2a&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=604x402&amp;quality=95&amp;sign=750a329da1aab679f8d832d7d4eee87d&amp;type=album&quot;,604,402],&quot;y&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=807x538&amp;quality=95&amp;sign=9f03c0d511f30444c16600800b65c2de&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=1280x853&amp;quality=95&amp;sign=f698b00409e37e744ff6a22e9dababc8&amp;type=album&quot;,1280,853],&quot;w&quot;:[&quot;https:\\/\\/sun9-46.userapi.com\\/impg\\/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA\\/e6W9JpXj8R0.jpg?size=2560x1706&amp;quality=95&amp;sign=bbf1b519b9c49d82a5970de0573aeeeb&amp;type=album&quot;,2560,1706]}]\"><img fetchpriority=\"high\" src=\"https://sun9-46.userapi.com/impg/DQ64X1EQVL-QpptWG9HMq4Ev-q8S64rblJE8YA/e6W9JpXj8R0.jpg?size=604x402&quality=95&sign=750a329da1aab679f8d832d7d4eee87d&type=album\" alt=\"VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге, изображение №5\" data-baseurl=\"\" /></div>\n</div>\n<div>Специальную награду от информационного партнера турнира «Санкт-Петербургские ведомости» вручил генеральный директор издания Борис Грумбков – кубок в номинации «Лучший наставник».</div>\n</div>\n</figure>\n<p>В этом году он достался тренеру <strong>Велингтону Рамосу</strong> («Палмейрас»), который в свою очередь поблагодарил организаторов.</p>\n<blockquote><p><em>– Мне очень понравилось, как организованы соревнования, уровень реализации и гостеприимства людей. Благодаря всем, с кем я общался здесь, я чувствовал себя как дома, в Бразилии. Ваша теплота, душевность – мы в этом очень похожи, – подчеркнул Велингтон Рамос.</em></p></blockquote>\n<p>Международный детско-юношеского турнир по футболу на Кубок Льва Бурчалкина прошёл в Санкт-Петербурге в шестой раз. Первые четыре раза победу одерживал испанский клуб «Вильярреал», в 2023 году – ФК «Зенит», в 2024 году – бразильский «Палмейрас».</p>\n<p>Информационными партнерами VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина выступили Российский футбольный союз, Федерация футбола Санкт-Петербурга, издания «Санкт-Петербургские ведомости», «Спорт-Экспресс», «Спорт День за Днем», «Фонтанка.ру», «Комсомольская правда», телеканал «Санкт-Петербург» и радио «Зенит». Прямую трансляцию финального матча вело информационное агентство ТАСС.</p>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/TX2fuGTmMa32KidOFZuiQlfUkBPcdFqMvNYAkA\\/5BUle871I_U.jpg?size=75x54&amp;quality=95&amp;sign=6ee1a23d823f52bb0f8f5641031e56cb&amp;type=album&quot;,75,54],&quot;m&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/TX2fuGTmMa32KidOFZuiQlfUkBPcdFqMvNYAkA\\/5BUle871I_U.jpg?size=130x94&amp;quality=95&amp;sign=c0fae59f0916cd9a78bcf037945ba477&amp;type=album&quot;,130,94],&quot;x&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/TX2fuGTmMa32KidOFZuiQlfUkBPcdFqMvNYAkA\\/5BUle871I_U.jpg?size=604x436&amp;quality=95&amp;sign=f262560b372c15de1ef09aa901d3e5ce&amp;type=album&quot;,604,436],&quot;y&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/TX2fuGTmMa32KidOFZuiQlfUkBPcdFqMvNYAkA\\/5BUle871I_U.jpg?size=661x477&amp;quality=95&amp;sign=bd524fb2e8ab935d8ea29e0fbcc8333d&amp;type=album&quot;,661,477]}]\"><img src=\"https://sun9-74.userapi.com/impg/TX2fuGTmMa32KidOFZuiQlfUkBPcdFqMvNYAkA/5BUle871I_U.jpg?size=661x477&quality=95&sign=bd524fb2e8ab935d8ea29e0fbcc8333d&type=album\" alt=\"VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина завершился в Санкт-Петербурге, изображение №6\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<p><em>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»).</em></p>\n<p><strong>Пресс-служба АО «Северо-Западный региональный центр Концерна ВКО «Алмаз-Антей» — Обуховский завод»</strong></p>\n</div>\n</div>\n</div>\n<div>\n<div>\n\n</div>\n</div>', 'news-article.html?slug=vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-zavershilsya-v-sankt-peterburge', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365228/burcup/news/vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-/images/240519-0120-1776365226975.jpg', NULL, 1, '2026-04-21 11:19:53.000', '2026-04-21 11:19:53.000');
