INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (51, NULL, 'kommentatorskij-tandem-v-efire-matcha-za-bronzu-kubka-burchalkina', '2024-05-19 00:00:00.000', 'Комментаторский тандем в эфире матча за бронзу Кубка Бурчалкина', 'Игрок команды «Алмаз-Антей» U-16 Никита Шумаков вместе с Иваном Канаевым прокомментирует для вас встречу «Црвена Звезда» — «Алмаз-Антей». В этом матче определится обладатель бронзовых медалей нашего турнира.\n\nТрансляцию можно будет посмотреть здесь:', 'Игрок команды «Алмаз-Антей» U-16 Никита Шумаков вместе с Иваном Канаевым прокомментирует для вас встречу «Црвена Звезда» — «Алмаз-Антей». В этом матче определится обладатель бронзовых медалей нашего турнира.\n\nТрансляцию можно будет посмотреть здесь: https://www.youtube.com/watch?v=fOBi2-mpaYM\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Игрок команды «Алмаз-Антей» U-16 Никита Шумаков вместе с Иваном Канаевым прокомментирует для вас встречу «Црвена Звезда» — «Алмаз-Антей». В этом матче определится обладатель бронзовых медалей нашего турнира.</p>\n<p>Трансляцию можно будет посмотреть здесь: <a href=\"https://www.youtube.com/watch?v=fOBi2-mpaYM\">https://www.youtube.com/watch?v=fOBi2-mpaYM</a></p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365244/burcup/news/kommentatorskij-tandem-v-efire-matcha-za-bronzu-kubka-burchalkina/images/bt0zasnhfdg-1776365243562.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365244/burcup/news/kommentatorskij-tandem-v-efire-matcha-za-bronzu-kubka-burchalkina/images/bt0zasnhfdg-1776365243562.jpg\" alt=\"\" /></a></p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=kommentatorskij-tandem-v-efire-matcha-za-bronzu-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365244/burcup/news/kommentatorskij-tandem-v-efire-matcha-za-bronzu-kubka-burchalkina/images/bt0zasnhfdg-1776365243562.jpg', NULL, 1, '2026-04-21 11:19:54.000', '2026-04-21 11:19:54.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (52, NULL, 'rezultaty-vi-kubka-burchalkina', '2024-05-19 00:00:00.000', 'Результаты VI Кубка Бурчалкина', 'Итоговое положение команд на VI Кубке Бурчалкина:\n1 место — «Палмейрас» (Бразилия)\n2 место — «Зенит» (Санкт-Петербург)\n3 место — «Алмаз-Антей» (Санкт-Петербург)\n4. «Црвена Звезда» (Сербия)\n5. «Кайрат» (Казахстан)\n6. «Фенербахче» (Турция)\n7. «Динамо-Минск» (Белоруссия)\n8. «Сепахан» (Иран)\n\nБлагодарим все команды за участие в турнире!', 'Итоговое положение команд на VI Кубке Бурчалкина:\n\n1 место — «Палмейрас» (Бразилия)\n\n2 место — «Зенит» (Санкт-Петербург)\n\n3 место — «Алмаз-Антей» (Санкт-Петербург)\n\n4. «Црвена Звезда» (Сербия)\n\n5. «Кайрат» (Казахстан)\n\n6. «Фенербахче» (Турция)\n\n7. «Динамо-Минск» (Белоруссия)\n\n8. «Сепахан» (Иран)\n\nБлагодарим все команды за участие в турнире!', '<h4>Итоговое положение команд на VI Кубке Бурчалкина:</h4>\n<p>1 место — «Палмейрас» (Бразилия)<br />\n2 место — «Зенит» (Санкт-Петербург)<br />\n3 место — «Алмаз-Антей» (Санкт-Петербург)<br />\n4. «Црвена Звезда» (Сербия)<br />\n5. «Кайрат» (Казахстан)<br />\n6. «Фенербахче» (Турция)<br />\n7. «Динамо-Минск» (Белоруссия)<br />\n8. «Сепахан» (Иран)</p>\n<p>Благодарим все команды за участие в турнире!</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365242/burcup/news/rezultaty-vi-kubka-burchalkina/gallery/itogi-ing-1776365240950.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365242/burcup/news/rezultaty-vi-kubka-burchalkina/gallery/itogi-ing-1776365240950.png\" alt=\"\" /></a></p>', 'news-article.html?slug=rezultaty-vi-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365240/burcup/news/rezultaty-vi-kubka-burchalkina/images/itogi-rus-1776365238849.png', NULL, 1, '2026-04-21 11:19:54.000', '2026-04-21 11:19:54.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (53, NULL, 'perehodim-v-plej-off', '2024-05-18 00:00:00.000', 'Переходим в плей-офф!', 'По итогам матчей в группах у нас сформировались следующие пары 👇\n\n⚽ Плей-офф за 1-4 места:\n15:00 (мск) «Зенит» — «Алмаз-Антей»\n16:15 (мск) «Палмейрас» — «Црвена Звезда»\n\n⚽ Плей-офф за 5-8 места:\n17:30 (мск) «Кайрат» — «Динамо-Минск»\n18:45 (мск) «Сепахан» — «Фенербахче»', 'По итогам матчей в группах у нас сформировались следующие пары 👇\n\n⚽ Плей-офф за 1-4 места:\n\n15:00 (мск) «Зенит» — «Алмаз-Антей»\n\n16:15 (мск) «Палмейрас» — «Црвена Звезда»\n\n⚽ Плей-офф за 5-8 места:\n\n17:30 (мск) «Кайрат» — «Динамо-Минск»\n\n18:45 (мск) «Сепахан» — «Фенербахче»\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>По итогам матчей в группах у нас сформировались следующие пары &#x1f447;</p>\n<p>&#x26bd; Плей-офф за 1-4 места:<br />\n15:00 (мск) «Зенит» — «Алмаз-Антей»<br />\n16:15 (мск) «Палмейрас» — «Црвена Звезда»</p>\n<p>&#x26bd; Плей-офф за 5-8 места:<br />\n17:30 (мск) «Кайрат» — «Динамо-Минск»<br />\n18:45 (мск) «Сепахан» — «Фенербахче»</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=perehodim-v-plej-off', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367746/burcup/news/perehodim-v-plej-off/images/240517-1034-1776367746314.jpg', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (54, NULL, 'razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya', '2024-05-18 00:00:00.000', 'Разгон взят! Рассказываем о событиях первого игрового дня', 'В первый игровой день Burchalkin Cup события сменяли друг друга, как погода может несколько раз смениться в Петербурге. Столь насыщенных матчей с переизбытком интриги давно не видели поля стадиона «Алмаз-Антей». Но давайте пойдём по порядку.\n\n«Алмаз-Антей» 2:1 «Фенербахче»\nВообще первый игровой день можно сравнить с каким-то...', 'В первый игровой день Burchalkin Cup события сменяли друг друга, как погода может несколько раз смениться в Петербурге. Столь насыщенных матчей с переизбытком интриги давно не видели поля стадиона «Алмаз-Антей». Но давайте пойдём по порядку.\n\n«Алмаз-Антей» 2:1 «Фенербахче»\n\nВообще первый игровой день можно сравнить с каким-то музыкальным фестивалем. Тот самый момент, когда на старте выступают знакомые популярные исполнители и заряжают зрителей на весь день, случился именно в первом матче. Трибуны, которые болели за «Алмаз», конечно, добавили атмосферы. Хорошая и яркая атмосфера. Обмен голами, причём очень яркими, в первой половине встречи и доминация хозяев во второй – вполне логично привели к победе петербуржцев. Зрители получили и заряд адреналина и хорошее настроение на целый день.\n\n«Зенит» 2:0 «Динамо-Минск»\n\nТут уже выступление попроще, но со вкусом. Снова местные ребята зажигали. Минчане, как показалось со стороны, достаточно неплохо защищались, но в этот день «Зенит» было так просто не остановить. Сине-бело-голубые невскими волнами просачивались через защиту «Динамо» и создали моментов на пять или шесть голов. Но реализовать удалось только 2 момента. Что, в целом, для первой игры тоже неплохо. Ведь не стоит показывать всё самое лучшее уже на старте. Петербуржцы приберегли силы и на второй матч.\n\n«Кайрат» 0:2 «Палмейрас»\n\nФеерии от бразильцев ожидали многие. Всё же первая гостевая дуэль на турнире. Тем более «Кайрат» всегда славился достаточно крепкими командами в своей академии, и можно было предположить, что нас ждет хороший боевик. Но показалось, что физически самая одаренная команда здесь и сейчас только разгонялась. Да, «Палмейрас» не забивал и не возил соперника в центре поля, но дежурные два гола забил. Команда из Казахстана тоже могла ответить, и не раз. Но мяч отказывался идти в ворота. И как итог очень обидное поражение.\n\n«Црвена Звезда» 2:0 «Сепахан»\n\nВ этой паре сразу прослеживался фаворит. Всё же сербские футболисты известны всему миру, а академия белградской команды подарила футболу немало звёзд. Так что вполне логично, что большую часть матча игрокам «Сепахана» приходилось обороняться и искать варианты, как попробовать выбраться в атаку. Иногда с этой задачей они справлялись, но вот навязать конкурентную борьбу «Звезде» не получилось.\n\n«Алмаз-Антей» 2:1 «Кайрат»\n\nОдни из тех, кто начинал наш концерт на Burchalkin Сup, вернулись на сцену вновь. Но если в первом матче это был мощный заряд, то здесь уже больше похоже на балладу. Хозяева турнира сыграли как будто проще, спокойнее и без лишних движений. Да, великолепный гол со штрафного «Кайрата» должен увидеть каждый, но у команды из Казахстана было слишком мало времени на восстановление, и это сказывалось. Поэтому «Алмаз» довёл встречу до нужного результата и отправился на отдых, чтобы подготовиться к атлетичным бразильцам.\n\n«Зенит» 2:1 «Црвена Звезда»\n\nОдна из главных звёзд на нашей афише – этот матч. Многие ожидали настоящей рубки и изобилие голов. Но сказалось, что для обеих команд этот матч был вторым за день. По ходу первой половины была уверенность, что это будет ничья, причём справедливая. Однако «Зенит» открыл счёт на последней минуте тайма. Сербы попытались ответить во втором, но петербуржцы быстро восстановили комфортную разницу в счёте и довели дело до победы, хоть и не без труда.\n\n«Фенербахче» 1:2 «Палмейрас»\n\nЕщё один звёздный матч, который подготовил всех к основному блюду. Переиграть атлетичных бразильцев – задача со звёздочкой для всех на этом турнире. Турецкой команде это нужно было как воздух. Поэтому с первых минут они искали варианты разорвать оборону соперника и как-то завести мяч в ворота. Но в итоге в финале первого тайма дважды отличились футболисты «Палмейраса», взломав правый фланг обороны соперника. Ответить во втором тайме игроки «Фенербахче» смогли, однако случилось это лишь раз. И как итог обидное поражение. Но с гордо поднятой головой.\n\n«Динамо» (Минск) 2:3 «Сепахан»\n\nЭти парни стали настоящими хедлайнерами первого игрового дня турнира. Обе команды очень хотели победить, поэтому подходов к воротам друг друга было в достатке. Но в первом тайме лишь один гол, который мог смутить зрителей, но зато потом – настоящая феерия. В счёте вели футболисты из Ирана. Минчане отыгрались, но пропустили тут же. Потом динамовцы второй раз сравняли счёт и за минуту до конца основного времени, когда казалось, что развязка уже была – ещё один мяч в исполнении «Сепахана». И им достаётся первая победа на турнире Burchalkin Cup!\n\nУже завтра нас ждёт развязка относительно лидера группы «А» и распределение мест в группе «Б». А после – первый раунд плей-офф. Так что второй день настоящего фестиваля футбола будет ещё мощнее первого. Не пропустите и следите за играми либо живьём на стадионе «Алмаз-Антей», либо подключайтесь к трансляциям. Пропускать такие матчи просто нельзя!', '<p><span style=\"font-weight: 400;\">В первый игровой день Burchalkin Cup события сменяли друг друга, как погода может несколько раз смениться в Петербурге. Столь насыщенных матчей с переизбытком интриги давно не видели поля стадиона «Алмаз-Антей». Но давайте пойдём по порядку. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1020-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367706/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1020-1776367706322.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Алмаз-Антей» 2:1 «Фенербахче» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Вообще первый игровой день можно сравнить с каким-то музыкальным фестивалем. Тот самый момент, когда на старте выступают знакомые популярные исполнители и заряжают зрителей на весь день, случился именно в первом матче. Трибуны, которые болели за «Алмаз», конечно, добавили атмосферы. Хорошая и яркая атмосфера. Обмен голами, причём очень яркими, в первой половине встречи и доминация хозяев во второй – вполне логично привели к победе петербуржцев. Зрители получили и заряд адреналина и хорошее настроение на целый день. </span></p>\n<h3><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1038-scaled.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367732/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1038-1776367731530.jpg\" alt=\"\" /></a></h3>\n<h3><b><i>«Зенит» 2:0 «Динамо-Минск</i></b><b><i>»</i></b></h3>\n<p><span style=\"font-weight: 400;\">Тут уже выступление попроще, но со вкусом. Снова местные ребята зажигали. Минчане, как показалось со стороны, достаточно неплохо защищались, но в этот день «Зенит» было так просто не остановить. Сине-бело-голубые невскими волнами просачивались через защиту «Динамо» и создали моментов на пять или шесть голов. Но реализовать удалось только 2 момента. Что, в целом, для первой игры тоже неплохо. Ведь не стоит показывать всё самое лучшее уже на старте. Петербуржцы приберегли силы и на второй матч.</span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1068-scaled.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365262/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1068-1776365260560.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Кайрат» 0:2 «Палмейрас» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Феерии от бразильцев ожидали многие. Всё же первая гостевая дуэль на турнире. Тем более «Кайрат» всегда славился достаточно крепкими командами в своей академии, и можно было предположить, что нас ждет хороший боевик. Но показалось, что физически самая одаренная команда здесь и сейчас только разгонялась. Да, «Палмейрас» не забивал и не возил соперника в центре поля, но дежурные два гола забил. Команда из Казахстана тоже могла ответить, и не раз. Но мяч отказывался идти в ворота. И как итог очень обидное поражение. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1096-scaled.jpg\" data-rel=\"lightbox-image-3\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365269/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1096-1776365263224.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Црвена Звезда» 2:0 «Сепахан» </i></b></h3>\n<p><span style=\"font-weight: 400;\">В этой паре сразу прослеживался фаворит. Всё же сербские футболисты известны всему миру, а академия белградской команды подарила футболу немало звёзд. Так что вполне логично, что большую часть матча игрокам «Сепахана» приходилось обороняться и искать варианты, как попробовать выбраться в атаку. Иногда с этой задачей они справлялись, но вот навязать конкурентную борьбу «Звезде» не получилось. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1116-scaled.jpg\" data-rel=\"lightbox-image-4\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367737/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1116-1776367736607.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Алмаз-Антей» 2:1 «Кайрат» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Одни из тех, кто начинал наш концерт на Burchalkin Сup, вернулись на сцену вновь. Но если в первом матче это был мощный заряд, то здесь уже больше похоже на балладу. Хозяева турнира сыграли как будто проще, спокойнее и без лишних движений. Да, великолепный гол со штрафного «Кайрата» должен увидеть каждый, но у команды из Казахстана было слишком мало времени на восстановление, и это сказывалось. Поэтому «Алмаз» довёл встречу до нужного результата и отправился на отдых, чтобы подготовиться к атлетичным бразильцам. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1130-scaled.jpg\" data-rel=\"lightbox-image-5\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365273/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1130-1776365271715.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Зенит» 2:1 «Црвена Звезда» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Одна из главных звёзд на нашей афише – этот матч. Многие ожидали настоящей рубки и изобилие голов. Но сказалось, что для обеих команд этот матч был вторым за день. По ходу первой половины была уверенность, что это будет ничья, причём справедливая. Однако «Зенит» открыл счёт на последней минуте тайма. Сербы попытались ответить во втором, но петербуржцы быстро восстановили комфортную разницу в счёте и довели дело до победы, хоть и не без труда. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1148-scaled.jpg\" data-rel=\"lightbox-image-6\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367742/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1148-1776367741545.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Фенербахче» 1:2 «Палмейрас» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Ещё один звёздный матч, который подготовил всех к основному блюду. Переиграть атлетичных бразильцев – задача со звёздочкой для всех на этом турнире. Турецкой команде это нужно было как воздух. Поэтому с первых минут они искали варианты разорвать оборону соперника и как-то завести мяч в ворота. Но в итоге в финале первого тайма дважды отличились футболисты «Палмейраса», взломав правый фланг обороны соперника. Ответить во втором тайме игроки «Фенербахче» смогли, однако случилось это лишь раз. И как итог обидное поражение. Но с гордо поднятой головой. </span></p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/05/240517_1166-scaled.jpg\" data-rel=\"lightbox-image-7\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365285/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/gallery/240517-1166-1776365275609.jpg\" alt=\"\" /></a></p>\n<h3><b><i>«Динамо» (Минск) 2:3 «Сепахан» </i></b></h3>\n<p><span style=\"font-weight: 400;\">Эти парни стали настоящими хедлайнерами первого игрового дня турнира. Обе команды очень хотели победить, поэтому подходов к воротам друг друга было в достатке. Но в первом тайме лишь один гол, который мог смутить зрителей, но зато потом – настоящая феерия. В счёте вели футболисты из Ирана. Минчане отыгрались, но пропустили тут же. Потом динамовцы второй раз сравняли счёт и за минуту до конца основного времени, когда казалось, что развязка уже была – ещё один мяч в исполнении «Сепахана». И им достаётся первая победа на турнире Burchalkin Cup! </span></p>\n\n<p><span style=\"font-weight: 400;\">Уже завтра нас ждёт развязка относительно лидера группы </span>«<span style=\"font-weight: 400;\">А</span>» <span style=\"font-weight: 400;\">и распределение мест в группе </span>«<span style=\"font-weight: 400;\">Б</span>»<span style=\"font-weight: 400;\">. А после – первый раунд плей-офф. Так что второй день настоящего фестиваля футбола будет ещё мощнее первого. Не пропустите и следите за играми либо живьём на стадионе «Алмаз-Антей», либо подключайтесь к трансляциям. Пропускать такие матчи просто нельзя! </span></p>', 'news-article.html?slug=razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365257/burcup/news/razgon-vzyat-rasskazyvaem-o-sobytiyah-pervogo-igrovogo-dnya/images/240517-1033-1776365255704.jpg', NULL, 1, '2026-04-21 11:19:55.000', '2026-04-21 11:19:55.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (55, NULL, 'smi-o-starte-vi-rozygrysha-kubka-burchalkina', '2024-05-18 00:00:00.000', 'СМИ о старте VI розыгрыша Кубка Бурчалкина', 'Наши информационные партнёры рассказывают о Кубке Бурчалкина!\n\nСДЗД:', 'Наши информационные партнёры рассказывают о Кубке Бурчалкина!\n\nСДЗД: https://m.sportsdaily.ru/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-startoval-v-peterburge\n\nРФС: https://rfs.ru/news/220412\n\nФонтанка.ру: https://www.fontanka.ru/2024/05/17/73592252/\n\nСанкт-Петербургские Ведомости: https://spbvedomosti.ru/news/gorod/kubok-burchalkina-startoval-v-peterburge/', '<p>Наши информационные партнёры рассказывают о Кубке Бурчалкина!</p>\n<p>СДЗД: <a href=\"https://m.sportsdaily.ru/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-startoval-v-peterburge\">https://m.sportsdaily.ru/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-startoval-v-peterburge</a></p>\n<p>РФС: <a href=\"https://rfs.ru/news/220412\">https://rfs.ru/news/220412</a></p>\n<p>Фонтанка.ру: <a href=\"https://www.fontanka.ru/2024/05/17/73592252/\">https://www.fontanka.ru/2024/05/17/73592252/</a></p>\n<p>Санкт-Петербургские Ведомости: <a href=\"https://spbvedomosti.ru/news/gorod/kubok-burchalkina-startoval-v-peterburge/\">https://spbvedomosti.ru/news/gorod/kubok-burchalkina-startoval-v-peterburge/</a></p>', 'news-article.html?slug=smi-o-starte-vi-rozygrysha-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367701/burcup/news/smi-o-starte-vi-rozygrysha-kubka-burchalkina/images/240517-1001-1776367700984.jpg', NULL, 1, '2026-04-21 11:19:54.000', '2026-04-21 11:19:54.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (56, NULL, 'vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-startoval-v-peterburge', '2024-05-17 00:00:00.000', 'VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина стартовал в Петербурге', 'Торжественная церемония открытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 17 мая 2024 года. В соревнованиях впервые принимают участие шесть иностранных команд и два российских клуба.\n\nБороться за Кубок Льва Бурчалкина приехали...', 'Торжественная церемония открытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 17 мая 2024 года. В соревнованиях впервые принимают участие шесть иностранных команд и два российских клуба.\n\nБороться за Кубок Льва Бурчалкина приехали футболисты из клубов «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия).\n\nПеред официальной церемонией открытия прошла специальная экологическая акция «Дерево дружбы». Футбольные команды «Фенербахче С.К.», «Динамо-Минск» и «Кайрат», впервые принимающие участие в турнире, высадили деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).\n\nТоржественная церемония открытия началась с выступления коллектива барабанщиц. Затем на футбольном поле прошел парад команд-участниц. Когда юные спортсмены выстроились перед гостями, рядом с ними девушки в народных костюмах продемонстрировали театрализованный номер, посвященный русским традициям.\n\nОфициально старт турниру дали заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода Михаил Подвязников и президент Федерации футбола Санкт-Петербурга Алексей Игонин, который в рамках своего выступления озвучил приветственное обращение главы Российского футбольного союза Александра Дюкова.\n\n«Я очень рад, что состав участников постоянно расширяется. В этом году он объединил уже семь стран из трех континентов. Соревнования на Кубок Льва Бурчалкина объединяют не только футболистов, но и страны, культуры. Они реализуют одну из важнейших функций футбола – быть символом дружбы и партнерства. Хочу пожелать всем участникам турнира использовать эту возможность, чтобы не только завоевать трофей, но и познакомиться с ребятами из других стран», – зачитал Алексей Игонин.\n\nВ свою очередь Михаил Подвязников призвал участников соревнований не только играть в футбол, но и знакомиться между собой. «Я хотел бы поблагодарить наших друзей из Бразилии, Ирана, Турции, Сербии, Казахстана, Белоруссии. Все вы приехали к нам на турнир, несмотря на сложности, мы вам признательны за это. Дорогие участники соревнований, этот турнир проводится, чтобы вы могли сыграть в самую прекрасную игру на свете, показать все, на что способны, подружиться и познакомиться с нашим прекрасным городом Санкт-Петербургом», – сказал генеральный директор Обуховского завода.\n\nСледующей частью первого дня турнира стал матч открытия, который сыграли команды «Алмаз-Антей» и «Фенербахче С.К.». Он завершился победой хозяев соревнований со счётом 2:1. Игры будут идти по 19 мая включительно. В этом году количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут).\n\nМатчи открыты для всех желающих. Трансляция доступна на сайте турнира burcup-production.up.railway.app и на страницах футбольного клуба «Алмаз – Антей» в YouTube и социальной сети «ВКонтакте». Там же можно ознакомиться с подробным расписанием.\n\nВ заключительный день турнира (19 мая) соревнования начнутся с 10:00. Финал стартует в 13:45. Награждение победителей и торжественная церемония закрытия пройдут в 15:20.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз – Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз – Антей»).', '<p><strong>Торжественная церемония открытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина прошла на стадионе спортивного комплекса «Алмаз-Антей» в Санкт-Петербурге 17 мая 2024 года. </strong>В соревнованиях впервые принимают участие шесть иностранных команд и два российских клуба.</p>\n<p>Бороться за Кубок Льва Бурчалкина приехали футболисты из клубов «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия).</p>\n<p>Перед официальной церемонией открытия прошла специальная экологическая акция «Дерево дружбы». Футбольные команды «Фенербахче С.К.», «Динамо-Минск» и «Кайрат», впервые принимающие участие в турнире, высадили деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).</p>\n<p>Торжественная церемония открытия началась с выступления коллектива барабанщиц. Затем на футбольном поле прошел парад команд-участниц. Когда юные спортсмены выстроились перед гостями, рядом с ними девушки в народных костюмах продемонстрировали театрализованный номер, посвященный русским традициям.</p>\n<p>Официально старт турниру дали заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор Обуховского завода <strong>Михаил Подвязников</strong> и президент Федерации футбола Санкт-Петербурга <strong>Алексей Игонин</strong>, который в рамках своего выступления озвучил приветственное обращение главы Российского футбольного союза Александра Дюкова.</p>\n<blockquote><p>«Я очень рад, что состав участников постоянно расширяется. В этом году он объединил уже семь стран из трех континентов. Соревнования на Кубок Льва Бурчалкина объединяют не только футболистов, но и страны, культуры. Они реализуют одну из важнейших функций футбола – быть символом дружбы и партнерства. Хочу пожелать всем участникам турнира использовать эту возможность, чтобы не только завоевать трофей, но и познакомиться с ребятами из других стран», – зачитал Алексей Игонин.</p></blockquote>\n<p>В свою очередь Михаил Подвязников призвал участников соревнований не только играть в футбол, но и знакомиться между собой. <em>«Я хотел бы поблагодарить наших друзей из Бразилии, Ирана, Турции, Сербии, Казахстана, Белоруссии. Все вы приехали к нам на турнир, несмотря на сложности, мы вам признательны за это. Дорогие участники соревнований, этот турнир проводится, чтобы вы могли сыграть в самую прекрасную игру на свете, показать все, на что способны, подружиться и познакомиться с нашим прекрасным городом Санкт-Петербургом», – сказал генеральный директор Обуховского завода.</em></p>\n<p>Следующей частью первого дня турнира стал матч открытия, который сыграли команды «Алмаз-Антей» и «Фенербахче С.К.». Он завершился победой хозяев соревнований со счётом 2:1. Игры будут идти по 19 мая включительно. В этом году количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут).</p>\n<p><strong>Матчи открыты для всех желающих. Трансляция доступна на сайте турнира burchalkin-cup.ru и на страницах футбольного клуба «Алмаз – Антей» в </strong><strong>YouTube</strong><strong> и социальной сети «ВКонтакте». Там же можно ознакомиться с подробным расписанием.</strong></p>\n<p>В <strong>заключительный день</strong> турнира (19 мая) соревнования начнутся <strong>с 10:00</strong>. Финал стартует <strong>в 13:45</strong>. Награждение победителей и торжественная церемония закрытия пройдут <strong>в 15:20</strong>.</p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз – Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз – Антей»).</p>', 'news-article.html?slug=vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-startoval-v-peterburge', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367752/burcup/news/vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-/images/240517-1012-1776367752050.jpg', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (57, NULL, 'ya-nazovu-planetu-imenem-tvoim', '2024-05-15 00:00:00.000', 'Я назову планету именем твоим…', 'У всех футбольных команд есть прозвища — неофициальные названия, которые активно используют болельщики или средства массовой информации.\n\nДавайте узнаем, какие вторые (а где-то и третьи) имена есть у клубов-участников Кубка Бурчалкина:\n\nКайрат: «желто-чёрные»\nДинамо-Минск: «динамовцы», «бело-синие»\nПалмейрас: «зелёно-белые», «зеленейшие»,...', 'У всех футбольных команд есть прозвища — неофициальные названия, которые активно используют болельщики или средства массовой информации.\n\nДавайте узнаем, какие вторые (а где-то и третьи) имена есть у клубов-участников Кубка Бурчалкина:\n\nКайрат: «желто-чёрные»\n\nДинамо-Минск: «динамовцы», «бело-синие»\n\nПалмейрас: «зелёно-белые», «зеленейшие», «поросята»\n\nЗенит: «сине-бело-голубые», «зенитчики»\n\nФенербахче: «жёлтые канарейки», «жёлто-тёмно-синие»\n\nЦрвена Звезда»: «красно-белые»\n\nСепахан: «жёлтые львы», «золотые»\n\nАлмаз-Антей: «заводчане», «заводская команда»', '<p>У всех футбольных команд есть прозвища — неофициальные названия, которые активно используют болельщики или средства массовой информации.</p>\n<p>Давайте узнаем, какие вторые (а где-то и третьи) имена есть у клубов-участников Кубка Бурчалкина:</p>\n<p>Кайрат: «желто-чёрные»<br />\nДинамо-Минск: «динамовцы», «бело-синие»<br />\nПалмейрас: «зелёно-белые», «зеленейшие», «поросята»<br />\nЗенит: «сине-бело-голубые», «зенитчики»<br />\nФенербахче: «жёлтые канарейки», «жёлто-тёмно-синие»<br />\nЦрвена Звезда»: «красно-белые»<br />\nСепахан: «жёлтые львы», «золотые»<br />\nАлмаз-Антей: «заводчане», «заводская команда»</p>', 'news-article.html?slug=ya-nazovu-planetu-imenem-tvoim', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365290/burcup/news/ya-nazovu-planetu-imenem-tvoim/images/2m-9v9fnj-k-1776365289180.jpg', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (58, NULL, 'smi-o-nas', '2024-05-14 00:00:00.000', 'СМИ о нас', 'Старт Кубка Бурчалкина уже на этой неделе! Приглашаем всех посетить наш турнир!\n\n«Спорт день за днем»:', 'Старт Кубка Бурчалкина уже на этой неделе! Приглашаем всех посетить наш турнир!\n\n«Спорт день за днем»: https://m.sportsdaily.ru/news/v-kubke-lva-burchalkina-sygrayut-shest-inostrannykh-klubov\n\n«Комсомольская правда»: https://www.spb.kp.ru/daily/27604/4930841/\n\nТелеканал «Санкт-Петербург»: https://tvspb.ru/news/2024/05/13/detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdet-v-peterburge\n\n«Санкт-Петербургские ведомости»: https://spbvedomosti.ru/news/gorod/almaz-antey-zenit-fenerbakhche-s-k-palmeyras-sepakhan-tsrvena-zvezda-kayrat-dinamo-minsk-budut-na-st/\n\n«Спорт-Экспресс»: https://www.sport-express.ru/football/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-s-17-po-19-maya-2211115/\n\nТАСС: https://tass.ru/sport/20824447', '<p>Старт Кубка Бурчалкина уже на этой неделе! Приглашаем всех посетить наш турнир!</p>\n<p><strong>«Спорт день за днем»</strong><strong>:</strong> <a href=\"https://m.sportsdaily.ru/news/v-kubke-lva-burchalkina-sygrayut-shest-inostrannykh-klubov\">https://m.sportsdaily.ru/news/v-kubke-lva-burchalkina-sygrayut-shest-inostrannykh-klubov </a></p>\n<p><strong>«Комсомольская правда»:</strong> <a href=\"https://www.spb.kp.ru/daily/27604/4930841/\">https://www.spb.kp.ru/daily/27604/4930841/</a></p>\n<p><strong>Телеканал «Санкт-Петербург»:</strong> <a href=\"https://tvspb.ru/news/2024/05/13/detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdet-v-peterburge\">https://tvspb.ru/news/2024/05/13/detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdet-v-peterburge </a></p>\n<p><strong>«Санкт-Петербургские ведомости»:</strong> <a href=\"https://spbvedomosti.ru/news/gorod/almaz-antey-zenit-fenerbakhche-s-k-palmeyras-sepakhan-tsrvena-zvezda-kayrat-dinamo-minsk-budut-na-st/\">https://spbvedomosti.ru/news/gorod/almaz-antey-zenit-fenerbakhche-s-k-palmeyras-sepakhan-tsrvena-zvezda-kayrat-dinamo-minsk-budut-na-st/ </a></p>\n<p><strong>«Спорт-Экспресс»: </strong><a href=\"https://www.sport-express.ru/football/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-s-17-po-19-maya-2211115/\">https://www.sport-express.ru/football/news/vi-mezhdunarodnyy-detsko-yunosheskiy-turnir-na-kubok-lva-burchalkina-proydet-v-peterburge-s-17-po-19-maya-2211115/</a></p>\n<p><strong>ТАСС:</strong> <a href=\"https://tass.ru/sport/20824447\">https://tass.ru/sport/20824447</a></p>', 'news-article.html?slug=smi-o-nas', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365291/burcup/news/smi-o-nas/images/bch1-1776365291289.webp', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (59, NULL, 'vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdyot-v-peterburge-s-17-po-19-maya', '2024-05-13 00:00:00.000', 'VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина пройдёт в Петербурге с 17 по 19 мая', 'VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 17 по 19 мая 2024 г. в обновленном формате. В нём впервые примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.\n\nБороться за Кубок Льва Бурчалкина будут футболисты не...', 'VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 17 по 19 мая 2024 г. в обновленном формате. В нём впервые примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.\n\nБороться за Кубок Льва Бурчалкина будут футболисты не старше 13 лет из восьми команд семи стран: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия). Местом проведения турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса Санкт-Петербурга (проспект Обуховской Обороны, 130).\n\n17 мая в 09:30 перед официальной церемонией открытия стартует специальная экологическая акция «Дерево дружбы». Футбольные команды «Фенербахче С.К.», «Динамо-Минск» и «Кайрат», впервые принимающие участие в турнире, будут высаживать деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).\n\nВ 10:00 начнется торжественная церемония открытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. В ней примут участие представители руководства Концерна ВКО «Алмаз-Антей», Федерации футбола Санкт-Петербурга, почётные гости. Состоится парад юных футболистов из 8 команд, принимающих участие в мероприятии.\n\nВ 10:45 начнётся матч открытия группового этапа. Первыми в борьбу за главную награду вступят команды «Алмаз-Антей» и «Фенербахче С.К.». Игры будут идти весь день, начало последней запланировано на 19:30.\n\nВо второй соревновательный день состоятся матчи группового этапа и плей-офф. Начало первой игры запланировано на 10:00, последней – на 18:45. В этом году количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут).\n\nВ заключительный день турнира (19 мая) соревнования начнутся с 10:00. Финал стартует в 13:45. Награждение победителей и торжественная церемония закрытия пройдут в 15:20.\n\nПриглашаем представителей СМИ принять участие в освещении VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. Аккредитация СМИ на мероприятие проводится по тел. 8 (812) 207-21-10 или по почте pr-reklama@goz.ru , press@goz.ru: mailto:press@goz.ru.\n\nМатчи открыты для всех желающих. Трансляция будет доступна на сайте турнира burcup-production.up.railway.app, на страницах футбольного клуба «Алмаз-Антей» в YouTube и социальной сети «ВКонтакте».\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»).', '<p><strong>VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина состоится в Санкт-Петербурге с 17 по 19 мая 2024 г. в обновленном формате.</strong> В нём впервые примут участие шесть иностранных команд и два российских клуба. Состязания пройдут в два этапа: групповой и плей-офф.</p>\n<p>Бороться за Кубок Льва Бурчалкина будут футболисты не старше 13 лет из восьми команд семи стран: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия). Местом проведения турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса Санкт-Петербурга (проспект Обуховской Обороны, 130).</p>\n<p><strong>17 мая в 09:30</strong> перед официальной церемонией открытия стартует специальная экологическая акция «Дерево дружбы». Футбольные команды «Фенербахче С.К.», «Динамо-Минск» и «Кайрат», впервые принимающие участие в турнире, будут высаживать деревья на аллее Мира и Дружбы в саду Спартак. Такая традиция появилась в 2018 году. С тех пор в Санкт-Петербурге растут липы юных игроков из клубов «Вильярреал» (Испания), МТК (Венгрия), «Рома» (Италия), «Бока Хуниорс» (Аргентина), «Аталанта» (Италия), а также ЦСКА, «Краснодар», «Зенит» и «Алмаз-Антей» (Россия).</p>\n<p><strong>В 10:00</strong> начнется торжественная церемония открытия VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. В ней примут участие представители руководства Концерна ВКО «Алмаз-Антей», Федерации футбола Санкт-Петербурга, почётные гости. Состоится парад юных футболистов из 8 команд, принимающих участие в мероприятии.</p>\n<p>В<strong> 10:45</strong> начнётся матч открытия группового этапа. Первыми в борьбу за главную награду вступят команды «Алмаз-Антей» и «Фенербахче С.К.». Игры будут идти весь день, начало последней запланировано <strong>на 19:30</strong>.</p>\n<p>Во второй соревновательный день состоятся матчи группового этапа и плей-офф. Начало первой игры запланировано <strong>на 10:00</strong>, последней – <strong>на 18:45</strong>. В этом году количество матчей для каждой команды увеличилось с трёх до пяти, а время, напротив, сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут).</p>\n<p>В <strong>заключительный день</strong> турнира (19 мая) соревнования начнутся <strong>с 10:00</strong>. Финал стартует <strong>в 13:45</strong>. Награждение победителей и торжественная церемония закрытия пройдут <strong>в 15:20</strong>.</p>\n<p><strong>Приглашаем представителей СМИ принять участие в освещении V</strong><strong>I</strong><strong> Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина. Аккредитация СМИ на мероприятие проводится по тел. </strong>8 (812) 207-21-10 <strong>или по почте</strong> pr-reklama@goz.ru , <a href=\"mailto:press@goz.ru\">press@goz.ru</a>.</p>\n<p>Матчи открыты для всех желающих. Трансляция будет доступна на сайте турнира burchalkin-cup.ru, на страницах футбольного клуба «Алмаз-Антей» в YouTube и социальной сети «ВКонтакте».</p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз – Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. Он позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. В этом году мероприятие будет приурочено к 161-й годовщине образования Обуховского завода (входит в Концерн ВКО «Алмаз-Антей»).</p>', 'news-article.html?slug=vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-projdyot-v-peterburge-s-17-po-19-maya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365293/burcup/news/vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-lva-burchalkina-/images/whatsapp-image-2024-05-13-at-13-19-36-1776365292508.jpg', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (60, NULL, 'predstavlyaem-uchastnika-zenit-sankt-peterburg-2', '2024-05-12 00:00:00.000', 'Представляем участника — «Зенит» (Санкт-Петербург)', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».\n\nВ этом году «Зенит»-2011...', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».\n\nВ этом году «Зенит»-2011 стал победителем международного турнира «Науруз Кап», а также турнира «След на земле», который проходил в Казани.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2016 г. — 2 место\n\n2017 г. — 7 место\n\n2018 г. — 3 место\n\n2019 г. — 2 место\n\n2023 г. — 1 место\n\nГлавный тренер команды U-13 — Николай Красавин\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365295/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-2/images/zenit-1776365293942.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365295/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-2/images/zenit-1776365293942.png\" alt=\"\" /></a></p>\n<p>В этом году «Зенит»-2011 стал победителем международного турнира «Науруз Кап», а также турнира «След на земле», который проходил в Казани.</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2016 г. — 2 место<br />\n2017 г. — 7 место<br />\n2018 г. — 3 место<br />\n2019 г. — 2 место<br />\n2023 г. — 1 место</p>\n<p>Главный тренер команды U-13 — Николай Красавин</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-zenit-sankt-peterburg-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365295/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg-2/images/zenit-1776365293942.png', NULL, 1, '2026-04-21 11:19:56.000', '2026-04-21 11:19:56.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (61, NULL, 'kem-i-chem-mozhet-gorditsya-akademiya-dinamo-minsk', '2024-05-10 00:00:00.000', 'Кем и чем может гордиться Академия «Динамо-Минск»?', 'Минское «Динамо» всегда славилось своими воспитанниками. Футболисты, прошедшие подготовку в динамовской школе, успешно выступают не только на клубном уровне и в национальных сборных Беларуси разных возрастов, но и далеко за пределами страны.\nВ 1990-е годы минское «Динамо» в основном комплектовалось воспитанниками столичной СДЮШОР «Динамо», через...', 'Минское «Динамо» всегда славилось своими воспитанниками. Футболисты, прошедшие подготовку в динамовской школе, успешно выступают не только на клубном уровне и в национальных сборных Беларуси разных возрастов, но и далеко за пределами страны.\n\nВ 1990-е годы минское «Динамо» в основном комплектовалось воспитанниками столичной СДЮШОР «Динамо», через горнило которой прошли такие звезды отечественного футбола, как Александр Хацкевич, Валентин Белькевич, Александр Глеб.\n\nОтделение детско-юношеского футбола при ЗАО ФК «Динамо-Минск» возникло в сентябре 2000 года, когда тренеры Владимир Лукьяненко и Владимир Дятлов набрали группы ребят 1984 и 1985 года рождения. В их числе были тогда еще никому неизвестные Ян Тигорев, Кирилл Павлючек, Иван Денисевич, Антон Рябцев. На базе этой команды в СШ №44 г. Минска был создан спецкласс. Приняв участие в турнире «Хрустальный мяч», на следующий год команда под названием «Динамо-2» заявилась во вторую лигу чемпионата Беларуси.\n\nВ каждом наборе было немало ребят, которые сегодня играют заметные роли в белорусском футболе: Сергей Кисляк, Антон Путило, Александр Мартынович, Игорь Шитов, Виталий Трубило, Олег Веретило…В 2002-2003 годах воспитанники групп подготовки составляли костяк команды «Динамо-Юни», выступавшей в первой лиге чемпионата Беларуси. А затем Белорусская федерация футбола стала проводить юношеские первенства Беларуси, в которых динамовские дружины традиционно играют ведущие роли.\n\nВ 2009 году молодежная сборная Беларуси приняла участие в финальной части чемпионата Европы. СДЮШОР «Академия футбола ФК «Динамо-Минск» была представлена на топ-турнире сразу десятью воспитанниками – Александр Мартынович, Сергей Кисляк, Сергей Гигевич, Антон Путило, Леонид Ковель, Олег Веретило, Игорь Шитов, Алексей Янушкевич, Андрей Чухлей, Владимир Юрченко. Два воспитанника динамовской школы – Олег Веретило и Дмитрий Рекиш – в 2011 году в составе сборной Беларуси стали бронзовыми призерами молодежного чемпионата Европы в Дании. Не обошлось без динамовцев и на футбольном турнире Олимпиады-2012 в Лондоне, куда белорусская сборная пробилась впервые в истории. В состав национальной команды вошли Олег Веретило и Алексей Гаврилович.\n\nЕжегодно команды СДЮШОР «Академия футбола ФК «Динамо-Минск» выступают на многих международных турнирах: «Наше будущее», UTLC Cup, ФШМ Cup, Ateitis Cup, BFA Cup. Также воспитанники динамовской школы занимают лидирующие позиции на республиканских молодежных соревнованиях.\n\nВ структуре СДЮШОР «Академия футбола ФК «Динамо-Минск» занимаются более 400 человек, а сама Академия входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, которые стали профессиональными футболистами. Все больше выпускников пополняют ряды динамовского дубля и основного состава, а также отправляются покорять вершины других чемпионатов.\n\nСовсем скоро «динамовские» ребята 2011 г.р. впервые примут участие в Кубке Бурчалкина! Пожелаем им удачи!\n\nИсточник: сайт ФК «Динамо-Минск»', '<p>Минское «Динамо» всегда славилось своими воспитанниками. Футболисты, прошедшие подготовку в динамовской школе, успешно выступают не только на клубном уровне и в национальных сборных Беларуси разных возрастов, но и далеко за пределами страны.</p>\n<p>В 1990-е годы минское «Динамо» в основном комплектовалось воспитанниками столичной СДЮШОР «Динамо», через горнило которой прошли такие звезды отечественного футбола, как Александр Хацкевич, Валентин Белькевич, Александр Глеб.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365297/burcup/news/kem-i-chem-mozhet-gorditsya-akademiya-dinamo-minsk/gallery/765bcfd6-7554-4392-9d67-e4919a63feb0-1776365297423.webp\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365297/burcup/news/kem-i-chem-mozhet-gorditsya-akademiya-dinamo-minsk/gallery/765bcfd6-7554-4392-9d67-e4919a63feb0-1776365297423.webp\" alt=\"\" /></a></p>\n<p>Отделение детско-юношеского футбола при ЗАО ФК «Динамо-Минск» возникло в сентябре 2000 года, когда тренеры Владимир Лукьяненко и Владимир Дятлов набрали группы ребят 1984 и 1985 года рождения. В их числе были тогда еще никому неизвестные Ян Тигорев, Кирилл Павлючек, Иван Денисевич, Антон Рябцев. На базе этой команды в СШ №44 г. Минска был создан спецкласс. Приняв участие в турнире «Хрустальный мяч», на следующий год команда под названием «Динамо-2» заявилась во вторую лигу чемпионата Беларуси.</p>\n<figure data-type=\"101\" data-mode=\"1\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-76.userapi.com\\/impg\\/DqSYiKLs0x4fwfQS8isj_FTY2uTZ9zv68197eQ\\/sFxw5rFxeR0.jpg?size=52x75&amp;quality=95&amp;sign=4edf4222f9570bff9d4d7d04df9adbd9&amp;type=album&quot;,52,75],&quot;m&quot;:[&quot;https:\\/\\/sun9-76.userapi.com\\/impg\\/DqSYiKLs0x4fwfQS8isj_FTY2uTZ9zv68197eQ\\/sFxw5rFxeR0.jpg?size=90x130&amp;quality=95&amp;sign=50dcf6ab02bc1b3457a005aaf37f4b02&amp;type=album&quot;,90,130],&quot;x&quot;:[&quot;https:\\/\\/sun9-76.userapi.com\\/impg\\/DqSYiKLs0x4fwfQS8isj_FTY2uTZ9zv68197eQ\\/sFxw5rFxeR0.jpg?size=300x433&amp;quality=95&amp;sign=f1c7359d254e9efd78f8ab2b9a8fb5bb&amp;type=album&quot;,300,433]}]\"><img src=\"https://sun9-76.userapi.com/impg/DqSYiKLs0x4fwfQS8isj_FTY2uTZ9zv68197eQ/sFxw5rFxeR0.jpg?size=300x433&quality=95&sign=f1c7359d254e9efd78f8ab2b9a8fb5bb&type=album\" alt=\"Фелипе Кайседо и Ян Тигорев\" data-baseurl=\"\" /></div>\n</div>\n<div>В каждом наборе было немало ребят, которые сегодня играют заметные роли в белорусском футболе: Сергей Кисляк, Антон Путило, Александр Мартынович, Игорь Шитов, Виталий Трубило, Олег Веретило…В 2002-2003 годах воспитанники групп подготовки составляли костяк команды «Динамо-Юни», выступавшей в первой лиге чемпионата Беларуси. А затем Белорусская федерация футбола стала проводить юношеские первенства Беларуси, в которых динамовские дружины традиционно играют ведущие роли.</div>\n</div>\n</figure>\n<p>В 2009 году молодежная сборная Беларуси приняла участие в финальной части чемпионата Европы. СДЮШОР «Академия футбола ФК «Динамо-Минск» была представлена на топ-турнире сразу десятью воспитанниками – Александр Мартынович, Сергей Кисляк, Сергей Гигевич, Антон Путило, Леонид Ковель, Олег Веретило, Игорь Шитов, Алексей Янушкевич, Андрей Чухлей, Владимир Юрченко. Два воспитанника динамовской школы – Олег Веретило и Дмитрий Рекиш – в 2011 году в составе сборной Беларуси стали бронзовыми призерами молодежного чемпионата Европы в Дании. Не обошлось без динамовцев и на футбольном турнире Олимпиады-2012 в Лондоне, куда белорусская сборная пробилась впервые в истории. В состав национальной команды вошли Олег Веретило и Алексей Гаврилович.</p>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-32.userapi.com\\/impg\\/XGHMHdVvBm6J8n9nNNqBiBrY3O4sJg3dYbGNDw\\/BWEdf0tL2QY.jpg?size=75x43&amp;quality=95&amp;sign=c336304bd40a0582d8943ea816613ec5&amp;type=album&quot;,75,43],&quot;m&quot;:[&quot;https:\\/\\/sun9-32.userapi.com\\/impg\\/XGHMHdVvBm6J8n9nNNqBiBrY3O4sJg3dYbGNDw\\/BWEdf0tL2QY.jpg?size=130x74&amp;quality=95&amp;sign=a67f71faa8561e5fc812a270a246cde9&amp;type=album&quot;,130,74],&quot;x&quot;:[&quot;https:\\/\\/sun9-32.userapi.com\\/impg\\/XGHMHdVvBm6J8n9nNNqBiBrY3O4sJg3dYbGNDw\\/BWEdf0tL2QY.jpg?size=604x345&amp;quality=95&amp;sign=8dc7bbd4493eacf95ab67fc647dc218b&amp;type=album&quot;,604,345],&quot;y&quot;:[&quot;https:\\/\\/sun9-32.userapi.com\\/impg\\/XGHMHdVvBm6J8n9nNNqBiBrY3O4sJg3dYbGNDw\\/BWEdf0tL2QY.jpg?size=807x461&amp;quality=95&amp;sign=078f9fe007179c6ce2dd0dc8f7e9c42a&amp;type=album&quot;,807,461]}]\"><img src=\"https://sun9-32.userapi.com/impg/XGHMHdVvBm6J8n9nNNqBiBrY3O4sJg3dYbGNDw/BWEdf0tL2QY.jpg?size=807x461&quality=95&sign=078f9fe007179c6ce2dd0dc8f7e9c42a&type=album\" alt=\"Сборная Беларуси на Олимпиаде-2012\" data-baseurl=\"\" />Ежегодно команды СДЮШОР «Академия футбола ФК «Динамо-Минск» выступают на многих международных турнирах: «Наше будущее», UTLC Cup, ФШМ Cup, Ateitis Cup, BFA Cup. Также воспитанники динамовской школы занимают лидирующие позиции на республиканских молодежных соревнованиях.</div>\n</div>\n</div>\n</figure>\n<p>В структуре СДЮШОР «Академия футбола ФК «Динамо-Минск» занимаются более 400 человек, а сама Академия входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, которые стали профессиональными футболистами. Все больше выпускников пополняют ряды динамовского дубля и основного состава, а также отправляются покорять вершины других чемпионатов.</p>\n<p>Совсем скоро «динамовские» ребята 2011 г.р. впервые примут участие в Кубке Бурчалкина! Пожелаем им удачи!</p>\n<p><em>Источник: сайт ФК «Динамо-Минск»</em></p>', 'news-article.html?slug=kem-i-chem-mozhet-gorditsya-akademiya-dinamo-minsk', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365296/burcup/news/kem-i-chem-mozhet-gorditsya-akademiya-dinamo-minsk/images/000028-1584642836-383987-big-1776365295889.jpg', NULL, 1, '2026-04-21 11:19:57.000', '2026-04-21 11:19:57.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (62, NULL, 'predstavlyaem-uchastnika-dinamo-minsk-belarus', '2024-05-06 00:00:00.000', 'Представляем участника — «Динамо-Минск» (Беларусь)', 'Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в динамовской...', 'Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в динамовской Академии занимаются более 400 человек.\n\nДважды в год (май и сентябрь) проводится открытый просмотр для ребят в возрасте от 5 до 8 лет. Также регулярно проводятся отборы в группы подготовки для девочек.\n\nБелорусская команда впервые примет участие в нашем турнире 🔥\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Академия минского «Динамо» входит в топ-30 лучших футбольных школ Европы по количеству воспитанников, ставших профессиональными игроками. Молодые игроки непрерывно развиваются в структуре клуба и в дальнейшем успешно пополняют составы юношеских, дублирующей и основной команд, а также сборных нашей страны различных возрастов. Сейчас в динамовской Академии занимаются более 400 человек.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365299/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belarus/images/dinamo-minsk-1776365298753.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365299/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belarus/images/dinamo-minsk-1776365298753.png\" alt=\"\" /></a></p>\n<p>Дважды в год (май и сентябрь) проводится открытый просмотр для ребят в возрасте от 5 до 8 лет. Также регулярно проводятся отборы в группы подготовки для девочек.</p>\n<p>Белорусская команда впервые примет участие в нашем турнире &#x1f525;</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-dinamo-minsk-belarus', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365299/burcup/news/predstavlyaem-uchastnika-dinamo-minsk-belarus/images/dinamo-minsk-1776365298753.png', NULL, 1, '2026-04-21 11:19:57.000', '2026-04-21 11:19:57.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (63, NULL, 'predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-2', '2024-05-03 00:00:00.000', 'Представляем участника — «Алмаз-Антей» (Санкт-Петербург)', 'Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга среди команд до 14 лет (клубы категории «А»).\n\nПо итогам прошлого сезона ребята взяли серебро Первенства Санкт-Петербурга, а также стали серебряными призерами региональных соревнований «Зимний турнир».\n\nИстория выступлений на...', 'Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга среди команд до 14 лет (клубы категории «А»).\n\nПо итогам прошлого сезона ребята взяли серебро Первенства Санкт-Петербурга, а также стали серебряными призерами региональных соревнований «Зимний турнир».\n\nИстория выступлений на Кубке Бурчалкина:\n\n2016 г. — 7 место\n\n2017 г. — 3 место\n\n2018 г. — 5 место\n\n2019 г. — 4 место\n\n2023 г. — 4 место\n\nГлавный тренер ребят 2011 г.р. — Григорий Дробинин\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Футбольный клуб «Алмаз-Антей» был создан в 2014 году. Сейчас команда U-13 выступает в Первенстве Санкт-Петербурга среди команд до 14 лет (клубы категории «А»).</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365303/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-2/gallery/aa-1776365302561.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365303/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-2/gallery/aa-1776365302561.png\" alt=\"\" /></a></p>\n<p>По итогам прошлого сезона ребята взяли серебро Первенства Санкт-Петербурга, а также стали серебряными призерами региональных соревнований «Зимний турнир».</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2016 г. — 7 место<br />\n2017 г. — 3 место<br />\n2018 г. — 5 место<br />\n2019 г. — 4 место<br />\n2023 г. — 4 место</p>\n<p>Главный тренер ребят 2011 г.р. — Григорий Дробинин</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365301/burcup/news/predstavlyaem-uchastnika-almaz-antej-sankt-peterburg-2/images/aa-1-1776365300593.png', NULL, 1, '2026-04-21 11:19:57.000', '2026-04-21 11:19:57.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (64, NULL, 'ot-luchshego-igroka-kubka-burchalkina-do-luchshego-v-rpl', '2024-05-02 00:00:00.000', 'От лучшего игрока Кубка Бурчалкина до лучшего в РПЛ', '2018 год: воспитанник «Зенита» Данила Козлов получает награду лучшего игрока матча из рук старшего товарища Леандро Паредеса.\n\n2024 год: игрок калининградской «Балтики» Данила Козлов признается лучшим игроком матча уже в Премьер-Лиге.\n\nКак быстро растут наши дети! Гордимся!', '2018 год: воспитанник «Зенита» Данила Козлов получает награду лучшего игрока матча из рук старшего товарища Леандро Паредеса.\n\n2024 год: игрок калининградской «Балтики» Данила Козлов признается лучшим игроком матча уже в Премьер-Лиге.\n\nКак быстро растут наши дети! Гордимся!', '<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365305/burcup/news/ot-luchshego-igroka-kubka-burchalkina-do-luchshego-v-rpl/images/grp11l46llc-1776365304184.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365305/burcup/news/ot-luchshego-igroka-kubka-burchalkina-do-luchshego-v-rpl/images/grp11l46llc-1776365304184.jpg\" alt=\"\" /></a></p>\n<p>2018 год: воспитанник «Зенита» Данила Козлов получает награду лучшего игрока матча из рук старшего товарища Леандро Паредеса.</p>\n<p>2024 год: игрок калининградской «Балтики» Данила Козлов признается лучшим игроком матча уже в Премьер-Лиге.</p>\n<p>Как быстро растут наши дети! Гордимся!</p>', 'news-article.html?slug=ot-luchshego-igroka-kubka-burchalkina-do-luchshego-v-rpl', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365305/burcup/news/ot-luchshego-igroka-kubka-burchalkina-do-luchshego-v-rpl/images/grp11l46llc-1776365304184.jpg', NULL, 1, '2026-04-21 11:19:57.000', '2026-04-21 11:19:57.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (65, NULL, 'predstavlyaem-uchastnika-sepahan-iran-2', '2024-04-30 00:00:00.000', 'Представляем участника — «Сепахан» (Иран)', 'У себя в стране клуб из Исфахана — третьего по величине города Ирана, известен успешным и последовательным управлением юношеской академией. В последние годы представители этой футбольной школы все чаще приезжают в Россию на различные турниры. При этом обмен знаниями и опытом идет не только на уровне игроков, но и среди тренерских кадров.\n\n...', 'У себя в стране клуб из Исфахана — третьего по величине города Ирана, известен успешным и последовательным управлением юношеской академией. В последние годы представители этой футбольной школы все чаще приезжают в Россию на различные турниры. При этом обмен знаниями и опытом идет не только на уровне игроков, но и среди тренерских кадров.\n\nГлавная команда клуба — одна из самых титулованных в Иране. Она пять раз становилась чемпионом страны, а также четыре раза выигрывала Кубок Ирана. Выступает в высшей футбольной лиге — Про-лиге Персидского залива.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2023 г. — 8 место\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>У себя в стране клуб из Исфахана — третьего по величине города Ирана, известен успешным и последовательным управлением юношеской академией. В последние годы представители этой футбольной школы все чаще приезжают в Россию на различные турниры. При этом обмен знаниями и опытом идет не только на уровне игроков, но и среди тренерских кадров.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365306/burcup/news/predstavlyaem-uchastnika-sepahan-iran-2/images/sepahan-1776365305807.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365306/burcup/news/predstavlyaem-uchastnika-sepahan-iran-2/images/sepahan-1776365305807.png\" alt=\"\" /></a></p>\n<p>Главная команда клуба — одна из самых титулованных в Иране. Она пять раз становилась чемпионом страны, а также четыре раза выигрывала Кубок Ирана. Выступает в высшей футбольной лиге — Про-лиге Персидского залива.</p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2023 г. — 8 место</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-sepahan-iran-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365306/burcup/news/predstavlyaem-uchastnika-sepahan-iran-2/images/sepahan-1776365305807.png', NULL, 1, '2026-04-21 11:19:58.000', '2026-04-21 11:19:58.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (66, NULL, 'syuzhet-match-tv-o-predstoyashhem-vi-kubke-burchalkina', '2024-04-29 00:00:00.000', 'Сюжет «Матч ТВ» о предстоящем VI Кубке Бурчалкина', '', '', '<h2>Сюжет «Матч ТВ» о предстоящем VI Кубке Бурчалкина</h2>\n                            <div style=\"width: 640px;\"></div>', 'news-article.html?slug=syuzhet-match-tv-o-predstoyashhem-vi-kubke-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365308/burcup/news/syuzhet-match-tv-o-predstoyashhem-vi-kubke-burchalkina/images/snimok-ekrana-2024-04-29-145548-1776365307371.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365310/burcup/news/syuzhet-match-tv-o-predstoyashhem-vi-kubke-burchalkina/videos/match-tv-pro-kubok-burchalkina-1776365308629.mp4', 1, '2026-04-21 11:19:58.000', '2026-04-21 11:19:58.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (67, NULL, 'gde-budut-prohodit-igry-kubka-burchalkina-2', '2024-04-28 00:00:00.000', 'Где будут проходить игры Кубка Бурчалкина?', 'Стадион «Алмаз-Антей»\nАрена была открыта 12 сентября 2014 года (почти 10 лет назад). Находится недалеко от Обуховского завода. Стадион и его инфраструктура соответствуют всем современным технологиям.\n\n✅ Искусственное покрытие\n✅ Крытые трибуны на 700 мест\n✅ 4 раздевалки, судейская\n✅ Освещение\n\nАдрес: пр....', 'Стадион «Алмаз-Антей»\n\nАрена была открыта 12 сентября 2014 года (почти 10 лет назад). Находится недалеко от Обуховского завода. Стадион и его инфраструктура соответствуют всем современным технологиям.\n\n✅ Искусственное покрытие\n\n✅ Крытые трибуны на 700 мест\n\n✅ 4 раздевалки, судейская\n\n✅ Освещение\n\nАдрес: пр. Обуховской Обороны, д. 130', '<h3>Стадион «Алмаз-Антей»</h3>\n<p>Арена была открыта 12 сентября 2014 года (почти 10 лет назад). Находится недалеко от Обуховского завода. Стадион и его инфраструктура соответствуют всем современным технологиям.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365315/burcup/news/gde-budut-prohodit-igry-kubka-burchalkina-2/gallery/8p6ptkbtcso-1776365313001.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365315/burcup/news/gde-budut-prohodit-igry-kubka-burchalkina-2/gallery/8p6ptkbtcso-1776365313001.jpg\" alt=\"\" /></a><br />\n&#x2705; Искусственное покрытие<br />\n&#x2705; Крытые трибуны на 700 мест<br />\n&#x2705; 4 раздевалки, судейская<br />\n&#x2705; Освещение</p>\n<p>Адрес: пр. Обуховской Обороны, д. 130</p>', 'news-article.html?slug=gde-budut-prohodit-igry-kubka-burchalkina-2', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365312/burcup/news/gde-budut-prohodit-igry-kubka-burchalkina-2/images/8p6ptkbtcso-1-1776365311068.jpg', NULL, 1, '2026-04-21 11:19:58.000', '2026-04-21 11:19:58.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (68, NULL, 'predstavlyaem-uchastnika-kajrat-kazahstan', '2024-04-26 00:00:00.000', 'Представляем участника — «Кайрат» (Казахстан)', 'Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается более 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.\n\nТакже развитию футбольных навыков юных спортсменов помогает масштабный детский...', 'Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается более 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.\n\nТакже развитию футбольных навыков юных спортсменов помогает масштабный детский чемпионат — «Кайрат-Лига». В нем участвуют около 100 команд филиалов и франшиз клуба в пяти разных возрастных группах.\n\nВ 2023 году футболисты «Кайрата» 2011 г.р. стали победителями Юношеской лиги 1.\n\nНа наш турнир команда из Казахстана приедет впервые! Ребята усердно готовятся и уже с нетерпением ждут поездки в Санкт-Петербург. Поэтому они записали для нас видеопривет.\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Сегодня Академия «Кайрата» насчитывает более 1 000 воспитанников, а их футбольным образованием занимается более 50 высокопрофессиональных специалистов-тренеров. Вся работа в ней ведется по единой уникальной методологии и контролируется специальной программой.</p>\n\n<p>Также развитию футбольных навыков юных спортсменов помогает масштабный детский чемпионат — «Кайрат-Лига». В нем участвуют около 100 команд филиалов и франшиз клуба в пяти разных возрастных группах.</p>\n<p>В 2023 году футболисты «Кайрата» 2011 г.р. стали победителями Юношеской лиги 1.</p>\n<p>На наш турнир команда из Казахстана приедет впервые! Ребята усердно готовятся и уже с нетерпением ждут поездки в Санкт-Петербург. Поэтому они записали для нас видеопривет.</p>\n\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-uchastnika-kajrat-kazahstan', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365317/burcup/news/predstavlyaem-uchastnika-kajrat-kazahstan/images/kajrat-1776365316367.png', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365319/burcup/news/predstavlyaem-uchastnika-kajrat-kazahstan/videos/videoprivet-ot-kajrata-128075-1776365318308.mp4', 1, '2026-04-21 11:19:58.000', '2026-04-21 11:19:58.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (69, NULL, 'sluzhi-etomu-klubu-s-predannostyu-idushhej-ot-vsego-serdcza-kak-poyavilas-emblema-fenerbahche', '2024-04-25 00:00:00.000', '«Служи этому клубу с преданностью, идущей от всего сердца»: как появилась эмблема «Фенербахче»?', 'Логотип на форме команд — это не просто украшение. Это важный элемент, который несет в себе информацию о клубе, его истории, ценностях и традициях. Сегодняшнюю эмблему турецкого «Фенербахче» больше 100 лет назад нарисовал один из игроков команды. Рассказываем, что же символизируют дубовая ветка и пять цветов этого логотипа.\nМаяк, расположенный...', 'Логотип на форме команд — это не просто украшение. Это важный элемент, который несет в себе информацию о клубе, его истории, ценностях и традициях. Сегодняшнюю эмблему турецкого «Фенербахче» больше 100 лет назад нарисовал один из игроков команды. Рассказываем, что же символизируют дубовая ветка и пять цветов этого логотипа.\n\nМаяк, расположенный на мысе Фенербахче имел большое влияние на дизайн самой первой эмблемы клуба, в которой использовались жёлтый и белый цвета нарциссов, которые росли вокруг маяка. Форма также была разработана с жёлтыми и белыми полосами.\n\nЛоготип клуба «Фенербахче», который сегодня известен по всему миру, был нарисован в 1910 году. Его автором стал левый нападающий команды и «Король пенальти» Хикмет Топузер.\n\nСам Топузер описывает историю создания эмблемы клуба так:\n\n«После смены цветов нашего клуба трудно было создать герб, в котором бы фигурировали все наши цвета. Мои друзья доверили эту сложную работу мне. Во-первых, я постарался изобразить на гербе цвета нашего национального флага — красный и белый. Затем в центре на щите были размещены жёлтый цвет и тёмно-синий. Я написал имя клуба и дату основания на белом фоне. В каждый оттенок я вложил определённый смысл. Проект понравился, и эскизы были направлены дизайнеру Тевфику Хаккари».\n\nРисуя нашу эмблему, я постарался придать ей этот смысл: «Служи этому клубу с преданностью, идущей от всего сердца»\n\nДо сих пор цветами «Фенербахче» остаются жёлто-синие, а на гербовом щите клуба изображены пять разных цветов. Белый означает чистоту и раскрытое сердце, красный — любовь и преданность клубу, а также турецкий флаг, жёлтый — зависть конкурентов, тёмно-синий — благородство. Ветка дуба символизирует мощь и силу игроков «Фенербахче», зелёный цвет листа отражает успехи стамбульского клуба.\n\n#КубокБурчалкина #BurchalkinCup', '<p>Логотип на форме команд — это не просто украшение. Это важный элемент, который несет в себе информацию о клубе, его истории, ценностях и традициях. Сегодняшнюю эмблему турецкого «Фенербахче» больше 100 лет назад нарисовал один из игроков команды. Рассказываем, что же символизируют дубовая ветка и пять цветов этого логотипа.</p>\n<p>Маяк, расположенный на мысе Фенербахче имел большое влияние на дизайн самой первой эмблемы клуба, в которой использовались жёлтый и белый цвета нарциссов, которые росли вокруг маяка. Форма также была разработана с жёлтыми и белыми полосами.</p>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=75x33&amp;quality=95&amp;sign=92a80ef4a2e88991fadb2007986416ae&amp;type=album&quot;,75,33],&quot;m&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=130x57&amp;quality=95&amp;sign=bb09812942150cb84b1bc76b8a30c343&amp;type=album&quot;,130,57],&quot;x&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=604x263&amp;quality=95&amp;sign=196bc2d2725e545429764061f3221787&amp;type=album&quot;,604,263],&quot;y&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=807x351&amp;quality=95&amp;sign=08bde77317a40970dd954ba02a73f21e&amp;type=album&quot;,807,351],&quot;z&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=1280x556&amp;quality=95&amp;sign=f65f7d44c1204cf35a2ccc5f28f269c0&amp;type=album&quot;,1280,556],&quot;w&quot;:[&quot;https:\\/\\/sun9-58.userapi.com\\/impg\\/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ\\/ucXq-_wIQkA.jpg?size=2560x1113&amp;quality=95&amp;sign=a1186843a886bee21c31701f268b0b95&amp;type=album&quot;,2560,1113]}]\"><img src=\"https://sun9-58.userapi.com/impg/iXTqGoXaUpdIK5W8TxoLqTfDpq_EUheylCLcXQ/ucXq-_wIQkA.jpg?size=807x351&quality=95&sign=08bde77317a40970dd954ba02a73f21e&type=album\" alt=\"«Служи этому клубу с преданностью, идущей от всего сердца»: как появилась эмблема «Фенербахче»?, изображение №2\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<p>Логотип клуба «Фенербахче», который сегодня известен по всему миру, был нарисован в 1910 году. Его автором стал левый нападающий команды и «Король пенальти» <strong>Хикмет Топузер</strong>.</p>\n<p>Сам Топузер описывает историю создания эмблемы клуба так:</p>\n<blockquote><p>«После смены цветов нашего клуба трудно было создать герб, в котором бы фигурировали все наши цвета. Мои друзья доверили эту сложную работу мне. Во-первых, я постарался изобразить на гербе цвета нашего национального флага — красный и белый. Затем в центре на щите были размещены жёлтый цвет и тёмно-синий. Я написал имя клуба и дату основания на белом фоне. В каждый оттенок я вложил определённый смысл. Проект понравился, и эскизы были направлены дизайнеру Тевфику Хаккари».</p></blockquote>\n<p><cite><strong><em>Рисуя нашу эмблему, я постарался придать ей этот смысл: «Служи этому клубу с преданностью, идущей от всего сердца»</em></strong></cite></p>\n<p>До сих пор цветами «Фенербахче» остаются жёлто-синие, а на гербовом щите клуба изображены пять разных цветов. Белый означает чистоту и раскрытое сердце, красный — любовь и преданность клубу, а также турецкий флаг, жёлтый — зависть конкурентов, тёмно-синий — благородство. Ветка дуба символизирует мощь и силу игроков «Фенербахче», зелёный цвет листа отражает успехи стамбульского клуба.</p>\n<figure data-type=\"101\" data-mode=\"0\" data-done=\"1\">\n<div>\n<div>\n<div data-sizes=\"[{&quot;s&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA\\/mP7ExNF7zHg.jpg?size=75x50&amp;quality=95&amp;sign=159cbc7dc4253b328c2bc711fba1f642&amp;type=album&quot;,75,50],&quot;m&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA\\/mP7ExNF7zHg.jpg?size=130x87&amp;quality=95&amp;sign=49ad0cc6cb223c24194d6daa8df7dedf&amp;type=album&quot;,130,87],&quot;x&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA\\/mP7ExNF7zHg.jpg?size=604x403&amp;quality=95&amp;sign=a56a41f804fa8847b58f9b5267e09275&amp;type=album&quot;,604,403],&quot;y&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA\\/mP7ExNF7zHg.jpg?size=807x538&amp;quality=95&amp;sign=a829b9b800c04eae0c314143e527fc2d&amp;type=album&quot;,807,538],&quot;z&quot;:[&quot;https:\\/\\/sun9-74.userapi.com\\/impg\\/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA\\/mP7ExNF7zHg.jpg?size=1020x680&amp;quality=95&amp;sign=ea6aa57d173fab81fad87fbd75a1495a&amp;type=album&quot;,1020,680]}]\"><img src=\"https://sun9-74.userapi.com/impg/BTJaFDwvIPvoueTIUUNcHvGNXkyWUFW3R-rHwA/mP7ExNF7zHg.jpg?size=807x538&quality=95&sign=a829b9b800c04eae0c314143e527fc2d&type=album\" alt=\"«Служи этому клубу с преданностью, идущей от всего сердца»: как появилась эмблема «Фенербахче»?, изображение №3\" data-baseurl=\"\" /></div>\n</div>\n\n</div><figcaption data-captions=\"[&quot;&quot;]\"></figcaption></figure>\n<h3>#КубокБурчалкина #BurchalkinCup</h3>', 'news-article.html?slug=sluzhi-etomu-klubu-s-predannostyu-idushhej-ot-vsego-serdcza-kak-poyavilas-emblema-fenerbahche', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365323/burcup/news/sluzhi-etomu-klubu-s-predannostyu-idushhej-ot-vsego-serdcza-kak-poyavilas-emblem/images/c6029221b07c6a773047703c61c01859658f0e4f622a9435821824-1776365322681.jpg', NULL, 1, '2026-04-21 11:19:59.000', '2026-04-21 11:19:59.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (70, NULL, 'predstavlyaem-uchastnika-palmejras-braziliya', '2024-04-25 00:00:00.000', 'Представляем участника — «Палмейрас» (Бразилия)', 'Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.\n\nЦентр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из основных в...', 'Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.\n\nЦентр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из основных в Бразилии. На счету его воспитанников десятки крупных титулов и большое количество рекордов.\n\nВ Академии занимаются ребята девяти возрастов. Одной из особенностей подготовки является участие в соревнованиях за границей. Так как ребята приобретают важный опыт, играя с ведущими клубами мира.\n\nИстория выступлений на Кубке Бурчалкина:\n\n2023 г. — 2 место\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<div>Клуб из Сан-Паулу является самым титулованным по числу побед в чемпионатах Бразилии — 12 раз. Также «Палмейрас» трижды брал Кубок Либертадорес, что позволяет считать его одним из самых титулованных бразильских клубов на международной арене.</div>\n\n<div>Центр подготовки футболистов «Палмейраса» за последние годы зарекомендовал себя как один из основных в Бразилии. На счету его воспитанников десятки крупных титулов и большое количество рекордов.</div>\n\n<div>В Академии занимаются ребята девяти возрастов. Одной из особенностей подготовки является участие в соревнованиях за границей. Так как ребята приобретают важный опыт, играя с ведущими клубами мира.</div>\n\n<div>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365321/burcup/news/predstavlyaem-uchastnika-palmejras-braziliya/images/palmejras-1776365320710.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365321/burcup/news/predstavlyaem-uchastnika-palmejras-braziliya/images/palmejras-1776365320710.png\" alt=\"\" /></a></p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2023 г. — 2 место</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>\n</div>\n<div>\n<div>\n\n</div>\n</div>', 'news-article.html?slug=predstavlyaem-uchastnika-palmejras-braziliya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365321/burcup/news/predstavlyaem-uchastnika-palmejras-braziliya/images/palmejras-1776365320710.png', NULL, 1, '2026-04-21 11:19:58.000', '2026-04-21 11:19:58.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (71, NULL, 'predstavlyaem-uchastnika-fenerbahche-turcziya', '2024-04-21 00:00:00.000', 'Представляем участника — «Фенербахче» (Турция)', '«Фенербахче» является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.\n\nНаряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в...', '«Фенербахче» является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.\n\nНаряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в саду» и происходит от одноимённого района Кадыкёй в Стамбуле.\n\nВ академии «Фенербахче» занимаются юные футболисты от 10 до 19 лет.\n\nКоманда из Турции впервые примет участие в розыгрыше Кубка Бурчалкина.', '<p>«Фенербахче» является одним из старейших и самых успешных клубов в Турции. Он 19 раз становился чемпионом Суперлиги, завоевал 7 Кубков и 9 Суперкубков Турции, а также регулярно выступает в Еврокубках.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365325/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya/images/fener-1776365324524.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365325/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya/images/fener-1776365324524.png\" alt=\"\" /></a></p>\n<p>Наряду с «Бешикташем» и «Галатасараем» составляет так называемую большую тройку турецкого футбола. Название команды переводится как «Маяк в саду» и происходит от одноимённого района Кадыкёй в Стамбуле.</p>\n<p>В академии «Фенербахче» занимаются юные футболисты от 10 до 19 лет.</p>\n<p>Команда из Турции впервые примет участие в розыгрыше Кубка Бурчалкина.</p>', 'news-article.html?slug=predstavlyaem-uchastnika-fenerbahche-turcziya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365325/burcup/news/predstavlyaem-uchastnika-fenerbahche-turcziya/images/fener-1776365324524.png', NULL, 1, '2026-04-21 11:19:59.000', '2026-04-21 11:19:59.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (72, NULL, 'predstavlyaem-raspisanie-gruppovogo-etapa-kubka-burchalkina-2024', '2024-04-20 00:00:00.000', 'Представляем расписание группового этапа Кубка Бурчалкина-2024', 'Игровую программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Фенербахче».\n\nЗнакомимся с расписанием группового этапа нашего турнира', 'Игровую программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Фенербахче».\n\nЗнакомимся с расписанием группового этапа нашего турнира\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Игровую программу Кубка Бурчалкина откроет матч «Алмаз-Антей» — «Фенербахче».</p>\n<p>Знакомимся с расписанием группового этапа нашего турнира</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365329/burcup/news/predstavlyaem-raspisanie-gruppovogo-etapa-kubka-burchalkina-2024/gallery/raspisanie-gruppy-1776365327982.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365329/burcup/news/predstavlyaem-raspisanie-gruppovogo-etapa-kubka-burchalkina-2024/gallery/raspisanie-gruppy-1776365327982.png\" alt=\"\" /></a></p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=predstavlyaem-raspisanie-gruppovogo-etapa-kubka-burchalkina-2024', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365327/burcup/news/predstavlyaem-raspisanie-gruppovogo-etapa-kubka-burchalkina-2024/images/snimok-ekrana-2024-04-22-074307-1776365326560.jpg', NULL, 1, '2026-04-21 11:19:59.000', '2026-04-21 11:19:59.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (73, NULL, 'nashi-smi-ob-itogah-zherebevki-vi-kubka-burchalkina', '2024-04-19 00:00:00.000', 'Наши СМИ об итогах жеребьевки VI Кубка Бурчалкина', 'Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка будущего турнира.\n\nСпорт день за днем:', 'Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка будущего турнира.\n\nСпорт день за днем: https://www.sportsdaily.ru/articles/vozmozhnost-byt-v-mirovoy-sportivnoy-povestke-almaz-antey-i-zenit-gotovyatsya-k-vi-mezhdunarodnomu-k\n\nТАСС: https://tass.ru/sport/20588047\n\nФонтанка.ру: https://www.fontanka.ru/2024/04/18/73478333/?erid=2SDnjbq7xch\n\nСанкт-Петербургские Ведомости: https://spbvedomosti.ru/news/sport/v-peterburge-proydet-shestoy-po-schetu-mezhdunarodnyy-kubok-lva-burchalkina/\n\nКрасная звезда:', '<p>Ведущие российские СМИ посетили пресс-конференцию, на которой прошла жеребьевка будущего турнира.</p>\n<p><strong>Спорт день за днем:</strong> <a href=\"https://www.sportsdaily.ru/articles/vozmozhnost-byt-v-mirovoy-sportivnoy-povestke-almaz-antey-i-zenit-gotovyatsya-k-vi-mezhdunarodnomu-k\">https://www.sportsdaily.ru/articles/vozmozhnost-byt-v-mirovoy-sportivnoy-povestke-almaz-antey-i-zenit-gotovyatsya-k-vi-mezhdunarodnomu-k</a></p>\n<p><strong>ТАСС:</strong> <a href=\"https://tass.ru/sport/20588047\">https://tass.ru/sport/20588047</a></p>\n<p><strong>Фонтанка.ру:</strong> <a href=\"https://www.fontanka.ru/2024/04/18/73478333/?erid=2SDnjbq7xch\">https://www.fontanka.ru/2024/04/18/73478333/?erid=2SDnjbq7xch</a></p>\n<p><strong>Санкт-Петербургские Ведомости:</strong> <a href=\"https://spbvedomosti.ru/news/sport/v-peterburge-proydet-shestoy-po-schetu-mezhdunarodnyy-kubok-lva-burchalkina/\">https://spbvedomosti.ru/news/sport/v-peterburge-proydet-shestoy-po-schetu-mezhdunarodnyy-kubok-lva-burchalkina/ </a></p>\n<p style=\"text-align: left;\"><strong>Красная звезда:</strong></p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365363/burcup/news/nashi-smi-ob-itogah-zherebevki-vi-kubka-burchalkina/gallery/aoesxju4ry0-1776365362035.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365363/burcup/news/nashi-smi-ob-itogah-zherebevki-vi-kubka-burchalkina/gallery/aoesxju4ry0-1776365362035.jpg\" alt=\"\" /></a></p>', 'news-article.html?slug=nashi-smi-ob-itogah-zherebevki-vi-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367757/burcup/news/nashi-smi-ob-itogah-zherebevki-vi-kubka-burchalkina/images/240418-0004-1776367757169.jpg', NULL, 1, '2026-04-21 11:20:00.000', '2026-04-21 11:20:00.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (74, NULL, 'reportazh-vesti-sankt-peterburg-pro-podgotovku-k-vi-kubku-burchalkina', '2024-04-19 00:00:00.000', 'Репортаж «Вести-Санкт-Петербург» про подготовку к VI Кубку Бурчалкина', 'Видео: телеканал «Вести-Санкт-Петербург»', 'Видео: телеканал «Вести-Санкт-Петербург»', '<p>Видео: телеканал «Вести-Санкт-Петербург»</p>', 'news-article.html?slug=reportazh-vesti-sankt-peterburg-pro-podgotovku-k-vi-kubku-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365351/burcup/news/reportazh-vesti-sankt-peterburg-pro-podgotovku-k-vi-kubku-burchalkina/images/turnir-1776365350990.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365359/burcup/news/reportazh-vesti-sankt-peterburg-pro-podgotovku-k-vi-kubku-burchalkina/videos/reportazh-vesti-1776365352324.mp4', 1, '2026-04-21 11:20:00.000', '2026-04-21 11:20:00.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (75, NULL, 'syuzhet-ntv-pro-start-i-zherebevku-kubka-burchalkina', '2024-04-19 00:00:00.000', 'Сюжет НТВ про старт и жеребьевку Кубка Бурчалкина', 'Видео: телеканал НТВ', 'Видео: телеканал НТВ', '<p>Видео: телеканал НТВ</p>', 'news-article.html?slug=syuzhet-ntv-pro-start-i-zherebevku-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365330/burcup/news/syuzhet-ntv-pro-start-i-zherebevku-kubka-burchalkina/images/snimok-ekrana-2024-04-20-193737-1776365329829.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365349/burcup/news/syuzhet-ntv-pro-start-i-zherebevku-kubka-burchalkina/videos/reportazh-ntv-1776365331424.mp4', 1, '2026-04-21 11:19:59.000', '2026-04-21 11:19:59.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (76, NULL, 'konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-futbolu-na-kubok-lva-burchalkina', '2024-04-18 00:00:00.000', 'Концерн ВКО «Алмаз-Антей» объявил результаты жеребьёвки Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина', '8 апреля 2024 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 17 по 19 мая.\n«Это ежегодное мероприятие, которое...', '18 апреля 2024 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц VI Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 17 по 19 мая.\n\n«Это ежегодное мероприятие, которое Концерн проводит в Петербурге. Для детей не старше 13 лет важно проведение этого турнира, потому что это тот возраст, когда присутствует детский энтузиазм и юношеское отношение к спорту. Футбол – лучшая игра на свете, она формирует характер», – сказал в ходе пресс-конференции заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор АО «Обуховский завод», президент футбольного клуба «Алмаз-Антей» Михаил Подвязников.\n\nВ этом году в соревнованиях примут участие футболисты до 13 лет из двух российских и шести зарубежных команд. В ходе жеребьёвки они разделены на две группы.\n\nПредседатель Правления футбольного клуба «Зенит» Александр Медведев отметил важность спортивной дипломатии в современной геополитической обстановке.\n\n«Турнир на Кубок Льва Бурчалкина знаменателен тем, что с самого начала был международным. Несмотря на все геополитические и транспортные проблемы в этом турнире будут участвовать команды из разных стран, в которых футбол не менее популярен, чем у нас. Важно, что наши коллеги сразу отозвались. Спортивная дипломатия помогает создавать соответствующую обстановку для решения политических, экономических, социально-культурных проблем», – подчеркнул Александр Медведев.\n\nВ свою очередь президент Федерации футбола Санкт-Петербурга Алексей Игонин поблагодарил Концерн ВКО «Алмаз-Антей» за проведение турнира, который позволяет оставаться российскому спорту на международной арене.\n\n«В условиях мировой спортивной изоляции достаточно сложно развивать, а уж тем более конкурировать. Иметь объективную оценку развития футбола – практически невозможно. Нужно поблагодарить «Алмаз-Антей» за то, что мы можем быть в мировой спортивной повестке», – сказал Алексей Игонин.\n\nМестом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге. Спортсмены приедут в Северную столицу за день до начала соревнований. Накануне первых стартов для них будет организована культурная программа, а перед церемонией открытия впервые участвующие в турнире команды посадят липы на Аллее дружбы.\n\n«В этом году формат турнира изменился. Планируется два этапа: групповой и плей-офф. Каждая команда сыграет по пять игр – насыщенный график. Время матчей сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут). Есть небольшое условие по заменам: у команд будет три слота за игру. Судить будут молодые перспективные арбитры», – рассказал в ходе пресс-конференции главный судья турнира Иван Абросимов.\n\nТурнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.\n\nБолее подробная информация о VI Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина размещена на сайте burcup-production.up.railway.app. Контакты для аккредитации СМИ на турнир: тел.: 8 (812) 207-21-10, почта: pr-reklama@goz.ru: mailto:pr-reklama@goz.ru, press@goz.ru: mailto:press@goz.ru.', '<h4><strong>18 апреля 2024 года на территории АО «Обуховский завод» (входит в Концерн ВКО «Алмаз-Антей») в рамках пресс-конференции состоялась жеребьёвка команд-участниц </strong><strong>VI</strong><strong> Международного детско-юношеского турнира по футболу на Кубок Льва Бурчалкина, который пройдёт в Санкт-Петербурге с 17 по 19 мая. </strong></h4>\n<blockquote><p><em>«Это ежегодное мероприятие, которое Концерн проводит в Петербурге. Для детей не старше 13 лет важно проведение этого турнира, потому что это тот возраст, когда присутствует детский энтузиазм и юношеское отношение к спорту. Футбол – лучшая игра на свете, она формирует характер», – сказал в ходе пресс-конференции заместитель генерального директора Концерна ВКО «Алмаз-Антей», генеральный директор АО «Обуховский завод», президент футбольного клуба «Алмаз-Антей» <strong>Михаил Подвязников.</strong></em></p></blockquote>\n<p>В этом году в соревнованиях примут участие футболисты до 13 лет из двух российских и шести зарубежных команд. В ходе жеребьёвки они разделены на две группы.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/04/240418_0026-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367767/burcup/news/konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yu/gallery/240418-0026-1776367766769.jpg\" alt=\"\" /></a></p>\n<p>Председатель Правления футбольного клуба «Зенит» <strong>Александр Медведев</strong> отметил важность спортивной дипломатии в современной геополитической обстановке.</p>\n<blockquote><p><em>«Турнир на Кубок Льва Бурчалкина знаменателен тем, что с самого начала был международным. Несмотря на все геополитические и транспортные проблемы в этом турнире будут участвовать команды из разных стран, в которых футбол не менее популярен, чем у нас. Важно, что наши коллеги сразу отозвались. Спортивная дипломатия помогает создавать соответствующую обстановку для решения политических, экономических, социально-культурных проблем», – подчеркнул <strong>Александр Медведев.</strong></em></p>\n<p><em><strong><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/04/240418_0028-scaled.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367772/burcup/news/konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yu/gallery/240418-0028-1776367771986.jpg\" alt=\"\" /></a></strong></em></p></blockquote>\n<p>В свою очередь президент Федерации футбола Санкт-Петербурга <strong>Алексей Игонин</strong> поблагодарил Концерн ВКО «Алмаз-Антей» за проведение турнира, который позволяет оставаться российскому спорту на международной арене.</p>\n<blockquote><p>«В условиях мировой спортивной изоляции достаточно сложно развивать, а уж тем более конкурировать. Иметь объективную оценку развития футбола – практически невозможно. Нужно поблагодарить «Алмаз-Антей» за то, что мы можем быть в мировой спортивной повестке», – сказал <strong>Алексей Игонин.</strong></p>\n<p><strong><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/04/240418_0015-scaled.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367787/burcup/news/konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yu/gallery/240418-0015-1776367787297.jpg\" alt=\"\" /></a></strong></p></blockquote>\n<p>Местом проведения Международного турнира по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса в Санкт-Петербурге. Спортсмены приедут в Северную столицу за день до начала соревнований. Накануне первых стартов для них будет организована культурная программа, а перед церемонией открытия впервые участвующие в турнире команды посадят липы на Аллее дружбы.</p>\n<blockquote><p>«В этом году формат турнира изменился. Планируется два этапа: групповой и плей-офф. Каждая команда сыграет по пять игр – насыщенный график. Время матчей сократилось: два тайма по 25 минут (в прошлом году они длились по 30 минут). Есть небольшое условие по заменам: у команд будет три слота за игру. Судить будут молодые перспективные арбитры», – рассказал в ходе пресс-конференции главный судья турнира <strong>Иван Абросимов.</strong></p></blockquote>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2024/04/240418_0021-scaled.jpg\" data-rel=\"lightbox-image-3\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367793/burcup/news/konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yu/gallery/240418-0021-1776367792575.jpg\" alt=\"\" /></a></p>\n<p>Турнир памяти легендарного форварда ФК «Зенит» Льва Бурчалкина, начинавшего свою карьеру в команде СК «Большевик» (ныне ФК «Алмаз-Антей»), был учреждён в 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга. Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России. В этом году мероприятие также позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.</p>\n<p>Более подробная информация о VI Международном детско-юношеском турнире по футболу на Кубок Льва Бурчалкина размещена на сайте burchalkin-cup.ru. Контакты для аккредитации СМИ на турнир: тел.: 8 (812) 207-21-10, почта: <a href=\"mailto:pr-reklama@goz.ru\">pr-reklama@goz.ru</a>, <a href=\"mailto:press@goz.ru\">press@goz.ru</a>.</p>', 'news-article.html?slug=konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yunosheskogo-turnira-po-futbolu-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367761/burcup/news/konczern-vko-almaz-antej-obyavil-rezultaty-zherebyovki-mezhdunarodnogo-detsko-yu/images/240418-0022-1776367761137.jpg', NULL, 1, '2026-04-21 11:20:00.000', '2026-04-21 11:20:00.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (77, NULL, 'rezultaty-zherebevki-vi-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva-burchalkina', '2024-04-18 00:00:00.000', 'Результаты жеребьевки VI Международного детско-юношеского турнира на Кубок Льва Бурчалкина', 'Сегодня в Санкт-Петербурге участники нашего турнира узнали свои группы и будущих соперников.\n\nТурнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 17 по 19 мая 2024 года.', 'Сегодня в Санкт-Петербурге участники нашего турнира узнали свои группы и будущих соперников.\n\nТурнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 17 по 19 мая 2024 года.\n\n#КубокБурчалкина: https://vk.com/feed?section=search&q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0 #BurchalkinCup: https://vk.com/feed?section=search&q=%23BurchalkinCup', '<p>Сегодня в Санкт-Петербурге участники нашего турнира узнали свои группы и будущих соперников.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365420/burcup/news/rezultaty-zherebevki-vi-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva/images/3xbmpoe6ag-1776365419694.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365420/burcup/news/rezultaty-zherebevki-vi-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva/images/3xbmpoe6ag-1776365419694.jpg\" alt=\"\" /></a></p>\n<p>Турнир пройдет в Санкт-Петербурге на стадионе «Алмаз-Антей» с 17 по 19 мая 2024 года.</p>\n<p><a href=\"https://vk.com/feed?section=search&amp;q=%23%D0%9A%D1%83%D0%B1%D0%BE%D0%BA%D0%91%D1%83%D1%80%D1%87%D0%B0%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0\">#КубокБурчалкина</a> <a href=\"https://vk.com/feed?section=search&amp;q=%23BurchalkinCup\">#BurchalkinCup</a></p>', 'news-article.html?slug=rezultaty-zherebevki-vi-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365420/burcup/news/rezultaty-zherebevki-vi-mezhdunarodnogo-detsko-yunosheskogo-turnira-na-kubok-lva/images/3xbmpoe6ag-1776365419694.jpg', NULL, 1, '2026-04-21 11:20:00.000', '2026-04-21 11:20:00.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (78, NULL, 'reportazh-telekanala-sankt-peterburg-pro-zherebevku-vi-kubka-burchalkina', '2024-04-18 00:00:00.000', 'Репортаж телеканала «Санкт-Петербург» про жеребьевку VI Кубка Бурчалкина', 'Видео: телеканал «Санкт-Петербург»', 'Видео: телеканал «Санкт-Петербург»', '<p>Видео: телеканал «Санкт-Петербург»</p>', 'news-article.html?slug=reportazh-telekanala-sankt-peterburg-pro-zherebevku-vi-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365365/burcup/news/reportazh-telekanala-sankt-peterburg-pro-zherebevku-vi-kubka-burchalkina/images/videoframe-101051-1776365363793.png', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365417/burcup/news/reportazh-telekanala-sankt-peterburg-pro-zherebevku-vi-kubka-burchalkina/videos/reportazh-telekanala-sankt-peterburg-ot-18-04-2024-1776365365890.mp4', 1, '2026-04-21 11:20:00.000', '2026-04-21 11:20:00.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (79, NULL, 'chitaem-o-predstoyashhem-shestom-rozygryshe-kubka-burchalkina-na-straniczah-smi', '2024-04-16 00:00:00.000', 'Читаем о предстоящем шестом розыгрыше Кубка Бурчалкина на страницах СМИ', 'Новость о проведении VI Международного детско-юношеского турнира на Кубок Льва Бурчалкина появилась на страницах ведущих российских СМИ:\n\nСпорт день за днем:', 'Новость о проведении VI Международного детско-юношеского турнира на Кубок Льва Бурчалкина появилась на страницах ведущих российских СМИ:\n\nСпорт день за днем: https://www.sportsdaily.ru/news/almaz-antey-provedyet-vi-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina\n\nТАСС: https://tass.ru/sport/20547849\n\nПервый канал: https://www.1tv.ru/publikacii/obzor-smi/almaz-antey-v-mae-provedet-mezhdunarodnyy-turnir-po-futbolu-na-kubok-lva-burchalkina\n\n#YellowSport: https://yellowsport.ru/2024/04/16/pobolshe-detskih-turnirov/\n\nРоссия24.pro: https://sport.russia24.pro/spb/376665225/\n\nRussian.City: https://ria.city/spb/376665225/', '<p>Новость о проведении VI Международного детско-юношеского турнира на Кубок Льва Бурчалкина появилась на страницах ведущих российских СМИ:</p>\n<p><strong>Спорт день за днем:</strong> <a href=\"https://www.sportsdaily.ru/news/almaz-antey-provedyet-vi-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina\">https://www.sportsdaily.ru/news/almaz-antey-provedyet-vi-mezhdunarodnyy-turnir-na-kubok-lva-burchalkina</a></p>\n<p><strong>ТАСС:</strong> <a href=\"https://tass.ru/sport/20547849\">https://tass.ru/sport/20547849</a></p>\n<p><strong>Первый канал:</strong> <a href=\"https://www.1tv.ru/publikacii/obzor-smi/almaz-antey-v-mae-provedet-mezhdunarodnyy-turnir-po-futbolu-na-kubok-lva-burchalkina\">https://www.1tv.ru/publikacii/obzor-smi/almaz-antey-v-mae-provedet-mezhdunarodnyy-turnir-po-futbolu-na-kubok-lva-burchalkina</a></p>\n<p><strong>#YellowSport:</strong> <a href=\"https://yellowsport.ru/2024/04/16/pobolshe-detskih-turnirov/\">https://yellowsport.ru/2024/04/16/pobolshe-detskih-turnirov/</a></p>\n<p><b>Россия24.pro: </b><a href=\"https://sport.russia24.pro/spb/376665225/\">https://sport.russia24.pro/spb/376665225/</a></p>\n<p><b>Russian.City:</b> <a href=\"https://ria.city/spb/376665225/\">https://ria.city/spb/376665225/</a></p>', 'news-article.html?slug=chitaem-o-predstoyashhem-shestom-rozygryshe-kubka-burchalkina-na-straniczah-smi', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365426/burcup/news/chitaem-o-predstoyashhem-shestom-rozygryshe-kubka-burchalkina-na-straniczah-smi/images/yykpz-5adxg-1776365425552.jpg', NULL, 1, '2026-04-21 11:20:01.000', '2026-04-21 11:20:01.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (80, NULL, 'mihail-podvyaznikov-v-nyneshnem-godu-nemnogo-izmenitsya-formula-turnira', '2024-04-10 00:00:00.000', 'Михаил Подвязников: «В нынешнем году немного изменится формула турнира»', 'Генеральный директор АО «Северо-Западный региональный центр Концерна ВКО «Алмаз-Антей» — Обуховский завод» и глава клуба «Алмаз-Антей» Михаил Подвязников рассказал о том, как будет проходить Кубок Бурчалкина в этом году:\n— Раньше у нас участвовало по четыре российских и иностранных команды, и каждая проводила всего по три матча. Если...', 'Генеральный директор АО «Северо-Западный региональный центр Концерна ВКО «Алмаз-Антей» — Обуховский завод» и глава клуба «Алмаз-Антей» Михаил Подвязников рассказал о том, как будет проходить Кубок Бурчалкина в этом году:\n\n— Раньше у нас участвовало по четыре российских и иностранных команды, и каждая проводила всего по три матча. Если проиграешь первый, то на призовые места уже не можешь рассчитывать. Мы посчитали, что это нужно исправить.\n\nНа этот раз у нас будут только два российских коллектива: «Алмаз-Антей» и «Зенит», плюс шесть команд из иностранных дружественных государств. Они будут разделены на две группы и проведут круговой турнир.\n\nА в завершающий день состоятся стыковые матчи, когда первые места сыграют за кубок, вторые места, соответственно, за бронзу, ну и так далее.\n\nПочему мы приняли такое решение? Во-первых, хотелось расширить географию участников. Во-вторых — сделать так, чтобы дети провели как можно больше матчей, получили удовольствие от игры, ведь сроки проведения турнира очень сжатые.\n\nИсточник: сайт ЮФЛ: https://yflrussia.ru/posts/1114412', '<p>Генеральный директор АО «Северо-Западный региональный центр Концерна ВКО «Алмаз-Антей» — Обуховский завод» и глава клуба «Алмаз-Антей» <strong>Михаил Подвязников</strong> рассказал о том, как будет проходить Кубок Бурчалкина в этом году:</p>\n<blockquote><p>— Раньше у нас участвовало по четыре российских и иностранных команды, и каждая проводила всего по три матча. Если проиграешь первый, то на призовые места уже не можешь рассчитывать. Мы посчитали, что это нужно исправить.</p>\n<p>На этот раз у нас будут только два российских коллектива: «Алмаз-Антей» и «Зенит», плюс шесть команд из иностранных дружественных государств. Они будут разделены на две группы и проведут круговой турнир.</p>\n<p>А в завершающий день состоятся стыковые матчи, когда первые места сыграют за кубок, вторые места, соответственно, за бронзу, ну и так далее.</p>\n<p>Почему мы приняли такое решение? Во-первых, хотелось расширить географию участников. Во-вторых — сделать так, чтобы дети провели как можно больше матчей, получили удовольствие от игры, ведь сроки проведения турнира очень сжатые.</p></blockquote>\n<p><em>Источник: <a href=\"https://yflrussia.ru/posts/1114412\">сайт ЮФЛ</a></em></p>', 'news-article.html?slug=mihail-podvyaznikov-v-nyneshnem-godu-nemnogo-izmenitsya-formula-turnira', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365428/burcup/news/mihail-podvyaznikov-v-nyneshnem-godu-nemnogo-izmenitsya-formula-turnira/images/img-9450-1776365427164.png', NULL, 1, '2026-04-21 11:20:01.000', '2026-04-21 11:20:01.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (81, NULL, 'konczern-vko-almaz-antej-provedyot-vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-l-burchalkina', '2024-04-08 00:00:00.000', 'Концерн ВКО «Алмаз – Антей» проведёт VI Международный детско-юношеский турнир по футболу на Кубок Л. Бурчалкина', 'С 17 по 19 мая 2024 года в Санкт-Петербурге состоится VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\n\nВ 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга впервые был учреждён турнир...', 'С 17 по 19 мая 2024 года в Санкт-Петербурге состоится VI Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.\n\nВ 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга впервые был учреждён турнир памяти легендарного форварда ФК «Зенит», начавшего свое основание в команде СК «Большевик» (ныне ФК «Алмаз-Антей»). Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России.\n\nВ этом году побороться за Кубок Льва Бурчалкина приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: «Фенербахче С.К.» (Турция), «Палмейрас» (Бразилия), «Сепахан» (Иран), «Црвена Звезда» (Сербия), «Кайрат» (Казахстан), «Динамо-Минск» (Белоруссия), «Зенит» и «Алмаз-Антей» (Россия).\n\nМестом проведения Международного турнира на кубок Л. Бурчалкина по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса Санкт-Петербурга.\n\n18 апреля состоится пресс-конференция, на которой можно будет подробнее узнать о VI Международном детско-юношеском турнире по футболу на Кубок Л. Бурчалкина, и жеребьёвка команд на территории Обуховского завода. А с 17 по 19 мая российские и иностранные участники соберутся в Северной столице по адресу пр-т Обуховской Обороны, д. 130 и примут участие в матчах группового этапа, полуфиналах и финале.\n\nНадеемся, что мероприятие позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран.\n\nПриглашаем представителей СМИ принять участие в информационном освещении VI Международного детско-юношеского турнира по футболу на Кубке Льва Бурчалкина.\n\nКонтакты для аккредитации: тел.: 8 (812) 207-21-10,\n\nпочта: pr-reklama@goz.ru: mailto:pr-reklama@goz.ru , press@goz.ru: mailto:press@goz.ru .', '<p><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">С 17 по 19 мая 2024 года в Санкт-Петербурге состоится V</span></span></span></span></strong><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">I </span></span></span></span></strong><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Международный детско-юношеский турнир по футболу на Кубок Льва Бурчалкина.</span></span></span></span></strong></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">В 2016 году при поддержке Концерна ВКО «Алмаз-Антей» и Федерации футбола Санкт-Петербурга впервые был учреждён турнир памяти легендарного форварда ФК «Зенит», начавшего свое основание в команде СК «Большевик» (ныне ФК «Алмаз-Антей»). Основная цель проведения турнира – развитие международного футбольного движения и поддержка детско-юношеского спорта в России.</span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">В этом году побороться за Кубок Льва Бурчалкина приедут юные футболисты не старше 13 лет, игроки известных футбольных клубов России и мира: </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Фенербахче С.К.»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Турция), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Палмейрас»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Бразилия), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Сепахан»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Иран), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Црвена Звезда»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Сербия), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Кайрат»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Казахстан), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Динамо-Минск»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Белоруссия), </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Зенит»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> и </span></span><strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">«Алмаз-Антей»</span></span></strong><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> (Россия).</span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Местом проведения Международного турнира на кубок Л. Бурчалкина по традиции станет футбольный стадион «Алмаз-Антей», расположенный на территории одноименного спортивного комплекса Санкт-Петербурга.</span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">18 апреля состоится пресс-конференция, на которой можно будет подробнее узнать о VI Международном детско-юношеском турнире по футболу на Кубок Л. Бурчалкина, и жеребьёвка команд на территории Обуховского завода. А с 17 по 19 мая российские и иностранные участники соберутся в Северной столице по адресу пр-т Обуховской Обороны, д. 130 и примут участие в матчах группового этапа, полуфиналах и финале.</span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Надеемся, что мероприятие позволит укрепить позитивный имидж Российской Федерации, популяризировать спорт среди подрастающего поколения, способствовать налаживанию контактов с представителями других стран. </span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Приглашаем представителей СМИ принять участие в информационном освещении VI Международного детско-юношеского турнира по футболу на Кубке Льва Бурчалкина.</span></span></span></span></p>\n<p><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">Контакты для аккредитации: тел.: 8 (812) 207-21-10, </span></span></span></span><br />\n<span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">почта:  </span></span></span></span><a href=\"mailto:pr-reklama@goz.ru\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">pr-reklama@goz.ru</span></span></span></span></a><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> , </span></span></span></span><a href=\"mailto:press@goz.ru\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\">press@goz.ru</span></span></span></span></a><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"><span style=\"vertical-align: inherit;\"> .</span></span></span></span></p>', 'news-article.html?slug=konczern-vko-almaz-antej-provedyot-vi-mezhdunarodnyj-detsko-yunosheskij-turnir-po-futbolu-na-kubok-l-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365429/burcup/news/konczern-vko-almaz-antej-provedyot-vi-mezhdunarodnyj-detsko-yunosheskij-turnir-p/images/afisha-2024-1776365429003.jpg', NULL, 1, '2026-04-21 11:20:01.000', '2026-04-21 11:20:01.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (82, NULL, 'rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn', '2023-06-04 00:00:00.000', 'Родригу Кабрал: «Играть в мяч — наша культура, наша жизнь»', 'В розыгрыше Кубка Бурчалкина традиционно принимают участие команды с разных концов планеты, но представители бразильского футбола приехали в Санкт-Петербург впервые. Легендарный «Сантос», воспитавший множество звезд мирового футбола, привез своих юных талантов помериться силами с лучшими футбольными академиями России.\n\nКак игроки «Сантоса»...', 'В розыгрыше Кубка Бурчалкина традиционно принимают участие команды с разных концов планеты, но представители бразильского футбола приехали в Санкт-Петербург впервые. Легендарный «Сантос», воспитавший множество звезд мирового футбола, привез своих юных талантов помериться силами с лучшими футбольными академиями России.\n\nКак игроки «Сантоса» добирались на турнир? Как танцы и боевое искусство помогают развиваться в футболе? И чем Россия обворожила бразильцев? Об этом всем нам рассказал главный тренер Родригу Кабрал.\n\n— Расстояние от Бразилии до России почти 12 000 км. Как прошла дорога?\n\n— Мы выехали рано-рано утром и через 14 часов добрались только до Дубая… Из Дубая в Москву летели еще 6 часов, еще 1 час до Санкт-Петербурга. Все путешествие заняло у нас почти сутки. Мы вышли из аэропорта, сели в автобус, и дети сразу заснули, ведь они были очень вымотаны, хотя многие из них уже ездили на международные соревнования. Мне, как человеку привыкшему к длинным перелетам, было тоже тяжело.\n\n— Как вам Россия? Первый ли раз вы в нашей стране?\n\n— Мы все впервые приехали в Россию. Моим первым впечатлением было то, что здесь очень чисто, очень организованно, городская архитектура очень хорошо продумана, особенно футбольный комплекс, в котором мы играем. Но в основном поразило другое. В Бразилии мы хоть и изучаем историю, знаем какие-то основные черты русской культуры, но здесь мы прямо погрузились в историю России. Мы плавали на лодках по каналам Санкт-Петербурга, увидели Петропавловскую крепость и много других интересных сооружений и памятников. Раньше для нас Россия была чем-то далеким, недосягаемым, но мы смогли узнать ее получше. Мы под впечатлением.\n\n— Теперь про футбол. Бразилия — настоящая кузница футбольных талантов, одна из сильнейших сборных. В чем ваш секрет?\n\n— Бразилия — весьма разнообразная, многоликая страна. У нас очень много регионов, которые отличаются друг от друга. Мы из Сантоса, из города, который расположен на побережье Атлантического океана. У нас маленькие дети с самых юных лет играют в мяч, пинают и кидают его всевозможными способами, гоняются друг за другом. Это самое популярное времяпровождение в Сантосе. Играть в мяч — наша культура, наша жизнь. Конечно, в последнее время прослеживаются негативные тенденции, когда дети залипают в телефонах, не выходя из дома. Но несмотря на это для детей мяч — это игра, развлечение, радость, поэтому их к нему продолжает тянуть.\n\nТакже играет роль то, что Сантос — небольшой город, у нас все под рукой. Мы почти везде ходим пешком. Я выхожу из дома и за 10 минут добираюсь до работы на велосипеде. Для детей тоже все близко: 5 минут до пляжа, 5 минут до стадиона. Много времени остается для развлечений и футбола.\n\n— Есть ли все-таки какие-то уникальные упражнения, с помощью которых можно сделать из любого футболиста звезду?\n\n— Мы делаем очень много упражнений на дриблинг, постоянно обводим друг друга на тренировках. Также мы используем много упражнений с движениями, похожими на танцы. Научившись таким движениям, можно с легкостью обманывать соперников на поле. Показал, что будешь уходить в одну сторону, затем резко развернулся и ушел в другую… Вообще танцы — одна из основ нашей национальной культуры. У молодежи распространены движения в стиле фанк, очень популярна капоэйра — бразильское боевое искусство, сочетающее в себе борьбу и танец. Многие из наших ребят либо занимались, либо до сих пор занимаются этим видом спорта. Эти занятия очень помогают в дальнейшей футбольной карьере.\n\n— Есть ли у вас любимый тренер, который вас вдохновляет?\n\n— Одно время сборной Бразилии руководил тренер Тите, дважды выигрывавший за свою карьеру чемпионат Бразилии. Как тренер я стараюсь равняться на него. Его взгляды очень схожи с идеями Сантоса — подопечные Тите всегда стремятся получать радость от футбола. К тому же он часто использует в своих тренировках танцевальные движения и упражнения на дриблинг, как и мы.\n\n— Согласны ли вы с утверждением: «главное — не победа, а участие»?\n\n— Для ребят победы очень важны, несомненно. Они их мотивируют. Но мы стремимся донести до ребят одну простую мысль: каждая игра — это рост, в каждой игре вы учитесь. На фоне этого победы уходят на второй план.', '<p data-id=\"5f08c786-f723-49cc-8985-d37046aad281\" data-placeholder=\"Что замышляю только шалость\">В розыгрыше Кубка Бурчалкина традиционно принимают участие команды с разных концов планеты, но представители бразильского футбола приехали в Санкт-Петербург впервые. Легендарный «Сантос», воспитавший множество звезд мирового футбола, привез своих юных талантов помериться силами с лучшими футбольными академиями России.</p>\n<p data-id=\"5f08c786-f723-49cc-8985-d37046aad281\" data-placeholder=\"Что замышляю только шалость\"><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365431/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/images/8l6oc2uckhy-1776365430376.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365431/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/images/8l6oc2uckhy-1776365430376.jpg\" alt=\"\" /></a></p>\n<p data-id=\"89420523-788c-4a34-b4ef-e19b2f594f22\">Как игроки «Сантоса» добирались на турнир? Как танцы и боевое искусство помогают развиваться в футболе? И чем Россия обворожила бразильцев? Об этом всем нам рассказал главный тренер <strong>Родригу Кабрал.</strong></p>\n<p data-id=\"635b8965-ecf9-4336-80f2-1b1bac4beb63\"><strong>— Расстояние от Бразилии до России почти 12 000 км. Как прошла дорога?</strong></p>\n<p data-id=\"856b484a-5399-4484-82fb-d59495da136a\">— Мы выехали рано-рано утром и через 14 часов добрались только до Дубая… Из Дубая в Москву летели еще 6 часов, еще 1 час до Санкт-Петербурга. Все путешествие заняло у нас почти сутки. Мы вышли из аэропорта, сели в автобус, и дети сразу заснули, ведь они были очень вымотаны, хотя многие из них уже ездили на международные соревнования. Мне, как человеку привыкшему к длинным перелетам, было тоже тяжело.</p>\n<p data-id=\"f579ba9f-104a-4365-b8ea-67cf14972227\"><strong>— Как вам Россия? Первый ли раз вы в нашей стране?</strong></p>\n<p data-id=\"c21eb37a-e5ab-465d-adbc-5b18605b830a\">— Мы все впервые приехали в Россию. Моим первым впечатлением было то, что здесь очень чисто, очень организованно, городская архитектура очень хорошо продумана, особенно футбольный комплекс, в котором мы играем. Но в основном поразило другое. В Бразилии мы хоть и изучаем историю, знаем какие-то основные черты русской культуры, но здесь мы прямо погрузились в историю России. Мы плавали на лодках по каналам Санкт-Петербурга, увидели Петропавловскую крепость и много других интересных сооружений и памятников. Раньше для нас Россия была чем-то далеким, недосягаемым, но мы смогли узнать ее получше. Мы под впечатлением.</p>\n<p data-id=\"c21eb37a-e5ab-465d-adbc-5b18605b830a\"><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365433/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/gallery/qgsfcrw6dzu-1776365432097.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365433/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/gallery/qgsfcrw6dzu-1776365432097.jpg\" alt=\"\" /></a></p>\n<p data-id=\"553a3b0e-4088-43e8-a0eb-a190c6e1ce73\"><strong>— Теперь про футбол. Бразилия — настоящая кузница футбольных талантов, одна из сильнейших сборных. В чем ваш секрет?</strong></p>\n<p data-id=\"642a111e-f281-46d8-b391-5129f836f869\">— Бразилия — весьма разнообразная, многоликая страна. У нас очень много регионов, которые отличаются друг от друга. Мы из Сантоса, из города, который расположен на побережье Атлантического океана. У нас маленькие дети с самых юных лет играют в мяч, пинают и кидают его всевозможными способами, гоняются друг за другом. Это самое популярное времяпровождение в Сантосе. Играть в мяч — наша культура, наша жизнь. Конечно, в последнее время прослеживаются негативные тенденции, когда дети залипают в телефонах, не выходя из дома. Но несмотря на это для детей мяч — это игра, развлечение, радость, поэтому их к нему продолжает тянуть.</p>\n<p data-id=\"299f8610-6a73-445f-9bde-7c570f92e636\">Также играет роль то, что Сантос — небольшой город, у нас все под рукой. Мы почти везде ходим пешком. Я выхожу из дома и за 10 минут добираюсь до работы на велосипеде. Для детей тоже все близко: 5 минут до пляжа, 5 минут до стадиона. Много времени остается для развлечений и футбола.</p>\n<p data-id=\"918a77b7-08b4-4bd6-8ced-3bd21027325f\"><strong>— Есть ли все-таки какие-то уникальные упражнения, с помощью которых можно сделать из любого футболиста звезду?</strong></p>\n<p data-id=\"5e3533ff-cd3e-4cf1-bc84-01ccf1bbe7be\">— Мы делаем очень много упражнений на дриблинг, постоянно обводим друг друга на тренировках. Также мы используем много упражнений с движениями, похожими на танцы. Научившись таким движениям, можно с легкостью обманывать соперников на поле. Показал, что будешь уходить в одну сторону, затем резко развернулся и ушел в другую… Вообще танцы — одна из основ нашей национальной культуры. У молодежи распространены движения в стиле фанк, очень популярна капоэйра — бразильское боевое искусство, сочетающее в себе борьбу и танец. Многие из наших ребят либо занимались, либо до сих пор занимаются этим видом спорта. Эти занятия очень помогают в дальнейшей футбольной карьере.</p>\n<p data-id=\"5e3533ff-cd3e-4cf1-bc84-01ccf1bbe7be\"><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365435/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/gallery/k-x8viuoew0-1776365434745.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365435/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/gallery/k-x8viuoew0-1776365434745.jpg\" alt=\"\" /></a></p>\n<p data-id=\"d94bedcd-3031-4233-9115-15f41e609315\"><strong>— Есть ли у вас любимый тренер, который вас вдохновляет? </strong></p>\n<p data-id=\"fa4d0a65-0a3f-457f-a12f-c32a69208652\">— Одно время сборной Бразилии руководил тренер Тите, дважды выигрывавший за свою карьеру чемпионат Бразилии. Как тренер я стараюсь равняться на него. Его взгляды очень схожи с идеями Сантоса — подопечные Тите всегда стремятся получать радость от футбола. К тому же он часто использует в своих тренировках танцевальные движения и упражнения на дриблинг, как и мы.</p>\n<p data-id=\"e09120dc-3f72-443a-ba3e-e1a62d43fad5\"><strong>— Согласны ли вы с утверждением: «главное </strong>— <strong>не победа, а участие»?</strong></p>\n<p data-id=\"8d3c35f4-f9d2-499b-a4c7-25910c43030f\">— Для ребят победы очень важны, несомненно. Они их мотивируют. Но мы стремимся донести до ребят одну простую мысль: каждая игра — это рост, в каждой игре вы учитесь. На фоне этого победы уходят на второй план.</p>', 'news-article.html?slug=rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365431/burcup/news/rodrigu-kabral-igrat-v-myach-nasha-kultura-nasha-zhizn/images/8l6oc2uckhy-1776365430376.jpg', NULL, 1, '2026-04-21 11:20:06.000', '2026-04-21 11:20:06.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (83, NULL, 'fotografii-vseh-dnej-v-kubka-burchalkina', '2023-05-30 00:00:00.000', 'Фотографии всех дней V Кубка Бурчалкина', 'В нашей официальной группе в ВКонтакте добавлены фотографии со всего турнира:\n\nПервый день:', 'В нашей официальной группе в ВКонтакте добавлены фотографии со всего турнира:\n\nПервый день: https://vk.com/album-120721420_293264566\n\nВторой день: https://vk.com/album-120721420_293289346\n\nТретий день: https://vk.com/album-120721420_293339039\n\nЦеремония награждения: https://vk.com/album-120721420_293350269', '<p>В нашей официальной группе в ВКонтакте добавлены фотографии со всего турнира:</p>\n<p>Первый день: <a href=\"https://vk.com/album-120721420_293264566\">https://vk.com/album-120721420_293264566 </a></p>\n<p>Второй день: <a href=\"https://vk.com/album-120721420_293289346\">https://vk.com/album-120721420_293289346 </a></p>\n<p>Третий день: <a href=\"https://vk.com/album-120721420_293339039\">https://vk.com/album-120721420_293339039 </a></p>\n<p>Церемония награждения: <a href=\"https://vk.com/album-120721420_293350269\">https://vk.com/album-120721420_293350269 </a></p>', 'news-article.html?slug=fotografii-vseh-dnej-v-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365437/burcup/news/fotografii-vseh-dnej-v-kubka-burchalkina/images/kuywcfpm7v8-1776365436393.jpg', NULL, 1, '2026-04-21 11:20:06.000', '2026-04-21 11:20:06.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (84, NULL, 'vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost', '2023-05-27 00:00:00.000', 'Владимир Вучич: «Ключевое качество для футболиста — скорость!»', 'После заключительного для себя матча на турнире главный тренер «Црвены Звезды» был в хорошем расположении духа, ведь его команда смогла обыграть бразильский «Сантос». По итогам турнира сербский коллектив занял 5-е место.\nВ нашей беседе Владимир Вучич рассказал, почему название сербского клуба знакомо всем любителям футбола, и какими качествами...', 'После заключительного для себя матча на турнире главный тренер «Црвены Звезды» был в хорошем расположении духа, ведь его команда смогла обыграть бразильский «Сантос». По итогам турнира сербский коллектив занял 5-е место.\n\nВ нашей беседе Владимир Вучич рассказал, почему название сербского клуба знакомо всем любителям футбола, и какими качествами должны обладать игроки и футбольные тренеры.\n\n— Владимир, с победой! Как вам Россия? Вы у нас впервые?\n\n— Нет, это не первый мой визит в Россию. Я был дважды в Санкт-Петербурге, один раз в Москве. Впечатления самые лучшие!\n\n— «Црвена Звезда» — лучшая футбольная академия Сербии. Почему название вашего клуба знают во всем мире?\n\n— Мы считаемся лучшей академией не только своей страны, но и всего региона. К тому же в составе нашего клуба есть много команд по разным видам спорта, не только по футболу. «Црвена Звезда» — это целый бренд.\n\nМы громко заявили о себе благодаря победе в Лиге чемпионов в 1991 году, из-за чего наше имя прозвучало на весь мир. У многих футбольных болельщиков, когда они слышат название нашего клуба, возникает ассоциация именно с этим событием.\n\n— У вас в составе очень высокорослые игроки. Отбирали игроков по габаритам?\n\n— Нет, это не какой-то особый критерий. У нас есть и маленькие игроки, и высокие. В первую очередь мы обращаем внимание на характеристики игрока, на его способности.\n\n— Вы сыграли против нескольких российских команд: «Зенит», ЦСКА, «Краснодар». Что можете сказать про их уровень?\n\n— Все команды из России очень техничные, очень подвижные. Каждый игрок на поле знает, какое положение он должен занимать. Русские очень хорошо действуют в единоборствах, местами даже весьма агрессивно.\n\n— Какими ключевыми качествами должен обладать идеальный футболист, по вашему мнению?\n\n— Скорость.\n\n— Кратко и информативно. А тренер?\n\n— В первую очередь тренер должен быть педагогом. В детском футболе очень важном уметь общаться с детьми, ведь они проходят разные периоды в развитии, в том числе пубертат. Тренер должен знать, что и когда говорить своим подопечным.\n\nПомимо этого, тренер должен постоянно заниматься самообразованием, вкладываться в себя: посещать семинары, конференции, проходить курсы, получать сертификаты и тренерские лицензии.', '<p>После заключительного для себя матча на турнире главный тренер «Црвены Звезды» был в хорошем расположении духа, ведь его команда смогла обыграть бразильский «Сантос». По итогам турнира сербский коллектив занял 5-е место.</p>\n<p>В нашей беседе Владимир Вучич рассказал, почему название сербского клуба знакомо всем любителям футбола, и какими качествами должны обладать игроки и футбольные тренеры.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/230520_0356-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367799/burcup/news/vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost/images/230520-0356-1776367799156.jpg\" alt=\"\" /></a></p>\n<p><strong>—</strong> <strong>Владимир, с победой! Как вам Россия? Вы у нас впервые</strong>?</p>\n<p>— Нет, это не первый мой визит в Россию. Я был дважды в Санкт-Петербурге, один раз в Москве. Впечатления самые лучшие!</p>\n<p><strong>— «Црвена Звезда» — лучшая футбольная академия Сербии. Почему название вашего клуба знают во всем мире?</strong></p>\n<p>— Мы считаемся лучшей академией не только своей страны, но и всего региона. К тому же в составе нашего клуба есть много команд по разным видам спорта, не только по футболу. «Црвена Звезда» — это целый бренд.</p>\n<p>Мы громко заявили о себе благодаря победе в Лиге чемпионов в 1991 году, из-за чего наше имя прозвучало на весь мир. У многих футбольных болельщиков, когда они слышат название нашего клуба, возникает ассоциация именно с этим событием.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/230521_0250-scaled.jpg\" data-rel=\"lightbox-image-1\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365445/burcup/news/vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost/gallery/230521-0250-1776365439038.jpg\" alt=\"\" /></a></p>\n<p><strong>— У вас в составе очень высокорослые игроки. Отбирали игроков по габаритам?</strong></p>\n<p>— Нет, это не какой-то особый критерий. У нас есть и маленькие игроки, и высокие. В первую очередь мы обращаем внимание на характеристики игрока, на его способности.</p>\n<p><strong>— Вы сыграли против нескольких российских команд: «Зенит», ЦСКА, «Краснодар». Что можете сказать про их уровень?</strong></p>\n<p>— Все команды из России очень техничные, очень подвижные. Каждый игрок на поле знает, какое положение он должен занимать. Русские очень хорошо действуют в единоборствах, местами даже весьма агрессивно.</p>\n<p><strong>— Какими ключевыми качествами должен обладать идеальный футболист, по вашему мнению?</strong></p>\n<p>— Скорость.</p>\n<p><strong>— Кратко и информативно. А тренер?</strong></p>\n<p>— В первую очередь тренер должен быть педагогом. В детском футболе очень важном уметь общаться с детьми, ведь они проходят разные периоды в развитии, в том числе пубертат. Тренер должен знать, что и когда говорить своим подопечным.</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/230521_0235-scaled.jpg\" data-rel=\"lightbox-image-2\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365447/burcup/news/vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost/gallery/230521-0235-1776365446072.jpg\" alt=\"\" /></a></p>\n<p>Помимо этого, тренер должен постоянно заниматься самообразованием, вкладываться в себя: посещать семинары, конференции, проходить курсы, получать сертификаты и тренерские лицензии.</p>', 'news-article.html?slug=vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367799/burcup/news/vladimir-vuchich-klyuchevoe-kachestvo-dlya-futbolista-skorost/images/230520-0356-1776367799156.jpg', NULL, 1, '2026-04-21 11:20:06.000', '2026-04-21 11:20:06.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (85, NULL, 'rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-futbol', '2023-05-26 00:00:00.000', 'Родригу Жордан: «Я больше не верю в мифы и стереотипы про Россию и российский футбол»', 'В первой же игре на Кубке Бурчалкина «Палмейрас» заставил говорить о себе. Пропустив от ЦСКА два мяча в самом начале, юные бразильцы не только отыгрались, но и вырвали победу (3:2). Затем были четыре безответных мяча в ворота «Краснодара» и путевка в финал. Цель достигнута? Или главное все-таки не в этом?\nНаш разговор с главным тренером...', 'В первой же игре на Кубке Бурчалкина «Палмейрас» заставил говорить о себе. Пропустив от ЦСКА два мяча в самом начале, юные бразильцы не только отыгрались, но и вырвали победу (3:2). Затем были четыре безответных мяча в ворота «Краснодара» и путевка в финал. Цель достигнута? Или главное все-таки не в этом?\n\nНаш разговор с главным тренером «Палмейраса» Родругу Жорданом состоялся до начала финального поединка.\n\n— «Палмейрас» в финале Кубка Бурчалкина. Какую цель для себя ставили перед началом турнира?\n\n— Целью нашего участия в турнире было получить новый опыт. Безусловно, мы хотели выйти в финал, но это не было нашей главной задачей. В первую очередь мы приехали сюда именно за опытом.\n\n— Какие у вас отношения с «Сантосом»? Насколько мне известно, ваши матчи друг с другом в Бразилии — самые настоящие дерби. Кто чаще выигрывает?\n\n— В последние несколько лет «Палмейрас» побеждает чаще, потому что мы постепенно становимся всё более сильным клубом. Но наши отношения очень дружественные, на самом деле.\n\n— Не расстроились, что не получилось встретиться с «Сантосом» на турнире?\n\n— Нет, не расстроились, потому что играть с «Сантосом» мы можем по несколько раз в год в Бразилии. Мы рады, что здесь получили возможность сыграть против российских команд. Также могли сыграть с сербами, с иранцами. Такая возможность возникает нечасто, поэтому это огромный опыт для всех нас.\n\n— В рамках турнира прошел семинар, где тренеры всех команд-участниц делились опытом друг с другом. Расскажите о нем.\n\n— Семинар был очень интересным. Мы задавали много вопросов друг другу, я узнал много нового для себя и был рад рассказать, как проходят наши тренировки. Кроме того, я понял несостоятельность мифов и стереотипов про Россию и российский футбол, в которые верил до приезда сюда.\n\n— Отметили ли что-нибудь, что будете использовать в своей практике при подготовке футболистов?\n\n— Конечно. Все команды на турнире очень высокого уровня, от каждого можно было услышать много полезного. Будем анализировать и применять.\n\n— Какая команда, по вашему мнению, самая интересная на Кубке Бурчалкина? Сможете кого-нибудь отметить?\n\n— Все команды довольно интересны. Каждая имела шансы выйти в финал, но поскольку до финала кроме нас дошел «Зенит», то, пожалуй, выделю его.\n\n— В конце задам немного философский вопрос. Какими качествами должен обладать идеальный футболист?\n\n— Кроме техники футболист должен быть смелым, он должен уметь адаптироваться к условиям каждого матча, чтобы быть способным принимать правильные своевременные решения на поле. Но самое главное — футболист должен хотеть играть в футбол, хотеть участвовать в каждом матче.', '<p>В первой же игре на Кубке Бурчалкина «Палмейрас» заставил говорить о себе. Пропустив от ЦСКА два мяча в самом начале, юные бразильцы не только отыгрались, но и вырвали победу (3:2). Затем были четыре безответных мяча в ворота «Краснодара» и путевка в финал. Цель достигнута? Или главное все-таки не в этом?</p>\n<p>Наш разговор с главным тренером «Палмейраса» <strong>Родругу Жорданом </strong>состоялся до начала финального поединка.</p>\n<p><a href=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365450/burcup/news/rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-/images/iuxbpjvclfg-1776365448781.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365450/burcup/news/rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-/images/iuxbpjvclfg-1776365448781.jpg\" alt=\"\" /></a></p>\n<p><strong>— «Палмейрас» в финале Кубка Бурчалкина. Какую цель для себя ставили перед началом турнира?</strong></p>\n<p>— Целью нашего участия в турнире было получить новый опыт. Безусловно, мы хотели выйти в финал, но это не было нашей главной задачей. В первую очередь мы приехали сюда именно за опытом.</p>\n<p><strong>— Какие у вас отношения с «Сантосом»? Насколько мне известно, ваши матчи друг с другом в Бразилии — самые настоящие дерби. Кто чаще выигрывает?</strong></p>\n<p>— В последние несколько лет «Палмейрас» побеждает чаще, потому что мы постепенно становимся всё более сильным клубом. Но наши отношения очень дружественные, на самом деле.</p>\n<p><strong>— Не расстроились, что не получилось встретиться с «Сантосом» на турнире?</strong></p>\n<p>— Нет, не расстроились, потому что играть с «Сантосом» мы можем по несколько раз в год в Бразилии. Мы рады, что здесь получили возможность сыграть против российских команд. Также могли сыграть с сербами, с иранцами. Такая возможность возникает нечасто, поэтому это огромный опыт для всех нас.</p>\n<p><img src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365452/burcup/news/rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-/gallery/slemwm8jy3w-1776365450793.jpg\" alt=\"\" /></p>\n<p><strong>— В рамках турнира прошел семинар, где тренеры всех команд-участниц делились опытом друг с другом. Расскажите о нем.</strong></p>\n<p>— Семинар был очень интересным. Мы задавали много вопросов друг другу, я узнал много нового для себя и был рад рассказать, как проходят наши тренировки. Кроме того, я понял несостоятельность мифов и стереотипов про Россию и российский футбол, в которые верил до приезда сюда.</p>\n<p><strong>— Отметили ли что-нибудь, что будете использовать в своей практике при подготовке футболистов?</strong></p>\n<p>— Конечно. Все команды на турнире очень высокого уровня, от каждого можно было услышать много полезного. Будем анализировать и применять.</p>\n<p><strong>— Какая команда, по вашему мнению, самая интересная на Кубке Бурчалкина? Сможете кого-нибудь отметить?</strong></p>\n<p>— Все команды довольно интересны. Каждая имела шансы выйти в финал, но поскольку до финала кроме нас дошел «Зенит», то, пожалуй, выделю его.</p>\n<p><strong>— В конце задам немного философский вопрос. Какими качествами должен обладать идеальный футболист?</strong></p>\n<p>— Кроме техники футболист должен быть смелым, он должен уметь адаптироваться к условиям каждого матча, чтобы быть способным принимать правильные своевременные решения на поле. Но самое главное — футболист должен хотеть играть в футбол, хотеть участвовать в каждом матче.</p>', 'news-article.html?slug=rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-futbol', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365450/burcup/news/rodrigu-zhordan-ya-bolshe-ne-veryu-v-mify-i-stereotipy-pro-rossiyu-i-rossijskij-/images/iuxbpjvclfg-1776365448781.jpg', NULL, 1, '2026-04-21 11:20:07.000', '2026-04-21 11:20:07.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (86, NULL, 'opredeleny-luchshie-igroki-turnira', '2023-05-25 00:00:00.000', 'Определены лучшие игроки турнира', 'Поздравляем лучших игроков V Кубка Бурчалкина:\n\nЛучший вратарь — Максим Калачев («Зенит»)\nЛучший защитник — Григорий Барсуков («Алмаз-Антей»)\nЛучший полузащитник — Роман Калинин («Краснодар»)\nЛучший нападающий — Вук Югович («Црвена Звезда»)\nЛучший бомбардир — Паулу Энрике («Сантос»)\nЛучший игрок — Педру Рибейру («Палмейрас»)\nСамый...', 'Поздравляем лучших игроков V Кубка Бурчалкина:\n\nЛучший вратарь — Максим Калачев («Зенит»)\n\nЛучший защитник — Григорий Барсуков («Алмаз-Антей»)\n\nЛучший полузащитник — Роман Калинин («Краснодар»)\n\nЛучший нападающий — Вук Югович («Црвена Звезда»)\n\nЛучший бомбардир — Паулу Энрике («Сантос»)\n\nЛучший игрок — Педру Рибейру («Палмейрас»)\n\nСамый красивый гол турнира — Тимофей Латту («Зенит»)\n\nСамый лучший сейв турнира — Сайед Эрфан Хоссейни («Сепахан»)\n\nПриз зрительских симпатий — Амбарцум Алексанян (ЦСКА)', '<p>Поздравляем лучших игроков V Кубка Бурчалкина:</p>\n<p>Лучший вратарь — Максим Калачев («Зенит»)<br />\nЛучший защитник — Григорий Барсуков («Алмаз-Антей»)<br />\nЛучший полузащитник — Роман Калинин («Краснодар»)<br />\nЛучший нападающий — Вук Югович («Црвена Звезда»)<br />\nЛучший бомбардир — Паулу Энрике («Сантос»)<br />\nЛучший игрок — Педру Рибейру («Палмейрас»)<br />\nСамый красивый гол турнира — Тимофей Латту («Зенит»)<br />\nСамый лучший сейв турнира — Сайед Эрфан Хоссейни («Сепахан»)<br />\nПриз зрительских симпатий — Амбарцум Алексанян (ЦСКА)</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/230521_1175-scaled.jpg\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367808/burcup/news/opredeleny-luchshie-igroki-turnira/images/230521-1175-1776367807896.jpg\" alt=\"\" /></a></p>', 'news-article.html?slug=opredeleny-luchshie-igroki-turnira', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367808/burcup/news/opredeleny-luchshie-igroki-turnira/images/230521-1175-1776367807896.jpg', NULL, 1, '2026-04-21 11:20:07.000', '2026-04-21 11:20:07.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (87, NULL, 'reportazh-telekanala-sankt-peterburg-ob-itogah-yubilejnogo-rozygrysha-kubka-burchalkina', '2023-05-23 00:00:00.000', 'Репортаж телеканала «Санкт-Петербург» об итогах юбилейного розыгрыша Кубка Бурчалкина', '«Зенит» стал победителем V Международного юношеского турнира «Кубок Льва Бурчалкина»\n\nВидео: телеканал «Санкт-Петербург»', '«Зенит» стал победителем V Международного юношеского турнира «Кубок Льва Бурчалкина»\n\n• 13_szht-burchalov_hd720\n\nВидео: телеканал «Санкт-Петербург»', '<p><strong>«Зенит» стал победителем V Международного юношеского турнира «Кубок Льва Бурчалкина»</strong></p>\n<div>\n\t\t\n\t\n\t\n\t<noscript>\n\t<ol>\n\t\t<li><a href=\'https://burchalkin-cup.ru/wp-content/uploads/2023/05/13_szht-burchalov_hd720.mp4\'>13_szht-burchalov_hd720</a></li>\t</ol>\n\t</noscript>\n\t\n</div>\n\t\n<p>Видео: телеканал «Санкт-Петербург»</p>', 'news-article.html?slug=reportazh-telekanala-sankt-peterburg-ob-itogah-yubilejnogo-rozygrysha-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365454/burcup/news/reportazh-telekanala-sankt-peterburg-ob-itogah-yubilejnogo-rozygrysha-kubka-burc/images/13-szht-burchalov-hd720-moment-1776365453681.jpg', NULL, 1, '2026-04-21 11:20:07.000', '2026-04-21 11:20:07.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (88, NULL, 'telekanal-match-tv-rasskazyvaet-pro-v-kubok-burchalkina', '2023-05-22 00:00:00.000', 'Телеканал «Матч ТВ» рассказывает про V Кубок Бурчалкина', 'Сюжет «Матч ТВ» о нашем турнире', 'Сюжет «Матч ТВ» о нашем турнире', '<p>Сюжет «Матч ТВ» о нашем турнире</p>', 'news-article.html?slug=telekanal-match-tv-rasskazyvaet-pro-v-kubok-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365459/burcup/news/telekanal-match-tv-rasskazyvaet-pro-v-kubok-burchalkina/images/syuzhet-match-tv-moment-1776365458247.jpg', 'https://res.cloudinary.com/dcqvo4aoj/video/upload/v1776365473/burcup/news/telekanal-match-tv-rasskazyvaet-pro-v-kubok-burchalkina/videos/syuzhet-match-tv-2-1776365460137.mp4', 1, '2026-04-21 11:20:07.000', '2026-04-21 11:20:07.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (89, NULL, 'v-mezhdunarodnyj-turnir-po-futbolu-na-kubok-l-burchalkina-zavershilsya-pobedoj-zenita', '2023-05-22 00:00:00.000', 'V Международный турнир по футболу на Кубок Л. Бурчалкина завершился победой «Зенита»', 'С 19 по 21 мая 2023 года в Санкт-Петербурге проходил V Международный турнир по футболу на Кубок Льва Бурчалкина. В соревнованиях приняли «Сантос» (Бразилия), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Сепахан» (Иран), ЦСКА (Москва), ФК Краснодар (Краснодар), ФК Зенит (Санкт-Петербург) и ФК «Алмаз-Антей» (Санкт-Петербург). Турнир был...', 'С 19 по 21 мая 2023 года в Санкт-Петербурге проходил V Международный турнир по футболу на Кубок Льва Бурчалкина. В соревнованиях приняли «Сантос» (Бразилия), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Сепахан» (Иран), ЦСКА (Москва), ФК Краснодар (Краснодар), ФК Зенит (Санкт-Петербург) и ФК «Алмаз-Антей» (Санкт-Петербург). Турнир был приурочен к юбилею Обуховского завода, которому 16 мая 2023 года исполнилось 160 лет, и 320-летию Санкт-Петербурга.\n\nПо итогам турнира впервые победителем стала команда «Зенит», обыграв «Палмейрас» в финальном матче со счетом 2:1. В этом году турнир проводится Концерном ВКО «Алмаз-Антей» в юбилейный 5-й раз при поддержке Российского футбольного союза и Федерации футбола Санкт-Петербурга.\n\nВ торжественной церемонии, которая состоялась 21 мая 2023 года, приняли участие Президент Федерации футбола Санкт-Петербурга Елена Илюхина и генеральный директор АО «Обуховский завод», заместитель генерального директора АО «Концерн ВКО «Алмаз-Антей» Михаил Подвязников. Также на стадионе присутствовали: Полномочный представитель Президента Российской Федерации в Северо-Западном федеральном округе Александр Гуцан, заместитель генерального директора Концерна ВКО «Алмаз-Антей» Рустам Улумбеков, помощник генерального директора Концерна ВКО «Алмаз-Антей» Александр Коваленко и другие гости, приехавшие поддержать юных футболистов.\n\n«Этот турнир – это не только история про победы и результаты, а огромное удовольствие и счастье, которое испытывают как игроки на поле, так и зрители на трибуне. Самое главное, что ребята могут познать другую школу, сравнить себя, – поделилась своими впечатлениями Елена Илюхина. – Сегодня хочу сказать спасибо организаторам – Концерну «Алмаз – Антей», они приложили огромные усилия, сделали праздник не только для российских клубов, но и в принципе для Санкт-Петербурга».\n\nТри игровых дня проходили напряженно и зрелищно. Каждая из команд старалась показать хорошую техничную игру, реализовать как можно больше голевых моментов. Трибуны стадиона «Алмаз-Антей» были заполнены болельщиками, в том числе, из иностранных государств, и неравнодушными зрителями в течение всего турнира. Игры сопровождались бурей эмоций: после каждого гола или упущенного момента трибуны взрывались кричалками, а барабаны гремели на весь стадион. Организаторы соревнований подарили городу детскую версию чемпионата мира по футболу.\n\nДля гостей Санкт-Петербурга была предусмотрена интересная культурная программа. Так, футболисты «Црвена Звезда», «Сантос» и «Палмейрас» посетили «Газпром Арену». Гости из Ирана успели побывать в Петергофе и в Академии «Зенит». Футболисты каждой команды турнира прокатились на корабликах по рекам и каналам Северной столицы.\n\nНе обошлось и без ярких футбольных событий. В первый день соревнований команда «Алмаз–Антей» с разгромным счетом 5:0 победила иранский «Сепахан», занявший в итоговой турнирной таблице последнее место. Петербургский «Зенит» прервал череду побед иностранных футболистов в предыдущих четырех турнира, обыграв в финальной игре бразильскую команду «Палмейрас».\n\nФинальный день турнира открылся игрой за 7 место между командами «Сепахан» и «ЦСКА». Победу в матче по итогам серии пенальти одержали юные футболисты из России. За 5 место боролись: бразильская команда «Сантос» и сербская «Црвена Звезда». Победу одержали сербы со счетом 2:0, оставив бразильцев позади. Матч за 3 место прошел между командой – хозяйкой турнира «Алмаз-Антей» и командой «Краснодар», гости турнира отвоевали третье место со счетом 1:0.\n\nВ финальном матче за главный приз V Международного детско-юношеского футбольного турнира на Кубок Льва Бурчалкина встретились команды «Зенит» и «Палмейрас». Игра шла в напряженной борьбе. Но россияне оказались сильнее и забили бразильской команде два победных гола. Кубок Льва Бурчалкина впервые остался в России.\n\n«Я благодарю всех участников соревнований: ребят из Бразилии, Ирана, Сербии и, конечно, России за то, что они приехали на этот турнир, прекрасно выступили, подарили нам праздник футбола и дружбы. Желаю ребятам вырасти в настоящих звезд футбола», – отметил Михаил Подвязников.\n\nПо результатам соревнований сформировалась следующая турнирная таблица:\n\nВ планах организаторов Международного турнира по футболу на Кубок Л.Д. Бурчалкина в следующем году продолжить добрую традицию и провести турнир с привлечением детского-юношеских команд (футболисты не старше 13 лет) из ведущих футбольных клубов России и мира.', '<p><strong>С 19 по 21 мая 2023 года в Санкт-Петербурге проходил V Международный турнир по футболу на Кубок Льва Бурчалкина. В соревнованиях приняли «Сантос» (Бразилия), «Палмейрас» (Бразилия), «Црвена Звезда» (Сербия), «Сепахан» (Иран), ЦСКА (Москва), ФК Краснодар (Краснодар), ФК Зенит (Санкт-Петербург) и ФК «Алмаз-Антей» (Санкт-Петербург). Турнир был приурочен к юбилею Обуховского завода, которому 16 мая 2023 года исполнилось 160 лет, и 320-летию Санкт-Петербурга.       </strong></p>\n<p>По итогам турнира впервые победителем стала команда «Зенит», обыграв «Палмейрас» в финальном матче со счетом 2:1. В этом году  турнир проводится Концерном ВКО «Алмаз-Антей» в юбилейный 5-й раз при поддержке Российского футбольного союза и Федерации футбола Санкт-Петербурга.</p>\n<p>В торжественной церемонии, которая состоялась 21 мая 2023 года, приняли участие Президент Федерации футбола Санкт-Петербурга Елена Илюхина и генеральный директор АО «Обуховский завод», заместитель генерального директора АО «Концерн ВКО «Алмаз-Антей» Михаил Подвязников. Также на стадионе присутствовали: Полномочный представитель Президента Российской Федерации в Северо-Западном федеральном округе Александр Гуцан, заместитель генерального директора Концерна ВКО «Алмаз-Антей» Рустам Улумбеков, помощник генерального директора Концерна ВКО «Алмаз-Антей» Александр Коваленко и другие гости, приехавшие поддержать юных футболистов.</p>\n<blockquote><p>«Этот турнир – это не только история про победы и результаты, а огромное удовольствие и счастье, которое испытывают как игроки на поле, так и зрители на трибуне. Самое главное, что ребята могут познать другую школу, сравнить себя, – поделилась своими впечатлениями <strong>Елена Илюхина.</strong> – Сегодня хочу сказать спасибо организаторам – Концерну «Алмаз – Антей», они приложили огромные усилия, сделали праздник не только для российских клубов, но и в принципе для Санкт-Петербурга».</p></blockquote>\n<p>Три игровых дня проходили напряженно и зрелищно. Каждая из команд старалась показать хорошую техничную игру, реализовать как можно больше голевых моментов. Трибуны стадиона «Алмаз-Антей» были заполнены болельщиками, в том числе, из иностранных государств, и неравнодушными зрителями в течение всего турнира. Игры сопровождались бурей эмоций: после каждого гола или упущенного момента трибуны взрывались кричалками, а барабаны гремели на весь стадион. Организаторы соревнований подарили городу детскую версию чемпионата мира по футболу.</p>\n<p>Для гостей Санкт-Петербурга была предусмотрена интересная культурная программа. Так, футболисты «Црвена Звезда», «Сантос» и «Палмейрас» посетили «Газпром Арену». Гости из Ирана успели побывать в Петергофе и в Академии «Зенит». Футболисты каждой команды турнира прокатились на корабликах по рекам и каналам Северной столицы.</p>\n<p>Не обошлось и без ярких футбольных событий. В первый день соревнований команда «Алмаз–Антей» с разгромным счетом 5:0 победила иранский «Сепахан», занявший в итоговой турнирной таблице последнее место. Петербургский «Зенит» прервал череду побед иностранных футболистов в предыдущих четырех турнира, обыграв в финальной игре бразильскую команду «Палмейрас».</p>\n<p>Финальный день турнира открылся игрой за 7 место между командами «Сепахан» и «ЦСКА». Победу в матче по итогам серии пенальти одержали юные футболисты из России. За 5 место боролись: бразильская команда «Сантос» и сербская «Црвена Звезда». Победу одержали сербы со счетом 2:0, оставив бразильцев позади. Матч за 3 место прошел между командой – хозяйкой турнира «Алмаз-Антей» и командой «Краснодар», гости турнира отвоевали третье место со счетом 1:0.</p>\n<p>В финальном матче за главный приз V Международного детско-юношеского футбольного турнира на Кубок Льва Бурчалкина встретились команды «Зенит» и «Палмейрас». Игра шла в напряженной борьбе. Но россияне оказались сильнее и забили бразильской команде два победных гола. Кубок Льва Бурчалкина впервые остался в России.</p>\n<blockquote><p> «Я благодарю всех участников соревнований: ребят из Бразилии, Ирана, Сербии и, конечно, России за то, что они приехали на этот турнир, прекрасно выступили, подарили нам праздник футбола и дружбы. Желаю ребятам вырасти в настоящих звезд футбола», – отметил  <strong>Михаил Подвязников.</strong></p></blockquote>\n<p>По результатам соревнований сформировалась следующая турнирная таблица:</p>\n<p><a href=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/afisha.pngitogi.png\" data-rel=\"lightbox-image-0\" data-rl_title=\"\" data-rl_caption=\"\" title=\"\"><img fetchpriority=\"high\" src=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/afisha.pngitogi-1024x576.png\" alt=\"\" /></a></p>\n<p>В планах организаторов Международного турнира по футболу на Кубок Л.Д. Бурчалкина  в следующем году продолжить добрую традицию и провести турнир с привлечением детского-юношеских команд (футболисты не старше 13 лет) из ведущих футбольных клубов России и мира.</p>', 'news-article.html?slug=v-mezhdunarodnyj-turnir-po-futbolu-na-kubok-l-burchalkina-zavershilsya-pobedoj-zenita', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776367815/burcup/news/v-mezhdunarodnyj-turnir-po-futbolu-na-kubok-l-burchalkina-zavershilsya-pobedoj-z/images/230521-0110-1776367814381.jpg', NULL, 1, '2026-04-21 11:20:07.000', '2026-04-21 11:20:07.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (90, NULL, 'rezultaty-v-kubka-burchalkina', '2023-05-21 00:00:00.000', 'Результаты V Кубка Бурчалкина', 'Поздравляем победителей и призеров нашего турнира!', 'Поздравляем победителей и призеров нашего турнира!', '<p>Поздравляем победителей и призеров нашего турнира!</p>\n<p><img fetchpriority=\"high\" src=\"https://burchalkin-cup.ru/wp-content/uploads/2023/05/afisha.pngitogi-1024x576.png\" alt=\"\" /></p>', 'news-article.html?slug=rezultaty-v-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365457/burcup/news/v-mezhdunarodnyj-turnir-po-futbolu-na-kubok-l-burchalkina-zavershilsya-pobedoj-z/gallery/afisha-pngitogi-1776365456241.png', NULL, 1, '2026-04-21 11:20:08.000', '2026-04-21 11:20:08.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (91, NULL, 'obilie-golov-i-imena-finalistov-kakim-byl-vtoroj-den-v-kubka-burchalkina', '2023-05-20 00:00:00.000', 'Обилие голов и имена финалистов. Каким был второй день V Кубка Бурчалкина?', 'На стадии 1/4 финала игровые пары комплектовались по принципу «российский клуб — иностранный клуб». Но уже во второй день турнирный жребий свел вместе команды из Ирана и Бразилии. И они подарили болельщикам множество красивых голов, а главное — задали высокую планку для оставшихся игр дня.\n\nДва...', 'На стадии 1/4 финала игровые пары комплектовались по принципу «российский клуб — иностранный клуб». Но уже во второй день турнирный жребий свел вместе команды из Ирана и Бразилии. И они подарили болельщикам множество красивых голов, а главное — задали высокую планку для оставшихся игр дня.\n\nДва пенальти, гол с углового и хет-трик юного бразильца\n\n«Сепахан» (Иран) — «Сантос» (Бразилия) — 2:4\n\nГолы: Мохаммад Парса Рахами (23), Беньямин Алмашманеш (53) — Жулиу Сезар (15), Паулу\n\nЭнрике (18, 39, 44)\n\nВ первом матче игрового дня бразильский «Сантос» в упорной борьбе переиграл иранский «Сепахан» — 4:2. Счет забитым мячам бразильцев на турнире открыл Жулиу Сезар, остальные же голы записал на себя Пауло Энрике, оформивший хет-трик. Сначала он сильно зарядил в левый нижний угол с 11-метровой отметки, затем прямым ударом с углового, а третий мяч — легким касанием после скрытой передачи партнера в штрафную. У «Сепахана» отличились Мохаммад Парса Рахати и Беньямин Алмашманеш. Один из иранских голов также был забит с пенальти.\n\nГабариты решают\n\n«Црвена Звезда» (Сербия) — ЦСКА (Москва) — 3:1\n\nГолы: Вук Югович (10, 45), Андрей Арсениевич (41) — Ашот Озманян (59)\n\nМосквичи и сербы в очном матче оспаривали право бороться за 5-6 места. В первом тайма игроки «Црвены» довольно быстро взяли мяч под контроль. Уже на 10-й минуте Вук Югович продавил оборону россиян и после смещения в право пробил низом. Во втором тайме сербам удалось быстро забить еще два мяча, что практически решило исход встречи. ЦСКА пытался изменить ситуацию, но так и не нашел ключик к габаритным игрокам соперника. Частые нарушения разбили игру на эпизоды, эмоции стали закипать у обеих команд, и все внимание как болельщиков, так и футболистов переключилось на эти околофутбольные разборки. В концовке встречи армейцы отыграли один мяч, но времени спастись у них уже не было.\n\nБитва на Неве за финал\n\n«Алмаз-Антей» (Санкт-Петербург) — «Зенит» (Санкт-Петербург) — 1:2\n\nГолы: Кирилл Романенко (60) — Тимофей Латту (37), Клим Денисов (57)\n\nПетербургское дерби в первом полуфинале турнира получилось завораживающим. Огромные скорости и самоотдача на протяжении всего матча, борьба до последней секунды. Но какая бы равная и феноменальная ни была игра, в финал вышла только одна команда — «Зенит». В первом тайме мячей забито не было, зато во втором Тимофей Латту и Клим Денисов смогли поразить ворота «Алмаз-Антея» и обеспечить своей команде комфортное преимущество в счете. Хозяева турнира приложили все силы, чтобы отыграться, но забить им удалось лишь один мяч — Кирилл Романенко точным ударом низом реализовал пенальти. «Зенит» идет дальше, «Алмаз-Антей» сыграет в воскресенье за третье место.\n\nБразильцы все-таки в финале\n\n«Краснодар» (Краснодар) — «Палмейрас» (Бразилия) — 0:4\n\nГолы: Педру Рибейру (9, 20), Маркус Винисиус (37), Луис Густаво (45)\n\nПосле матча с ЦСКА, где «Палмейрасу» пришлось уходить с 0:2, встреча с краснодарскими «быками» интриговала как никогда. Москвичи показали, что с этими бразильцами можно играть. Но, похоже, что наши иностранные гости провели серьезную работу над ошибками перед полуфиналом. Поиграть на равных командам удалось только первые десять минут. Более физически развитыми бразильцами стали превосходить россиян в скорости и нацеленности на ворота. Два мяча в первом тайма, два мяча во втором — стабильность, которая позволила «Палмейрасу» выйти в финал V Кубка Бурчалкина.\n\nВ воскресенье в матче за 7-8 место сыграют «Сепахан» и ЦСКА, за 5-6 место будут бороться «Црвена Звезда» и «Сантос». В медальных матчах турнира сыграют «Алмаз-Антей» и «Краснодар», которые разыграют между собой бронзу, а за главный трофей Кубка Бурчалкина поспорят «Зенит» и «Палмейрас».', '<div>\n<div>\n<div>\n<div>\n<div>\n<div aria-live=\"polite\" aria-relevant=\"additions\">\n<div data-peer=\"27594787\" data-admin=\"0\">\n<div>На стадии 1/4 финала игровые пары комплектовались по принципу «российский клуб — иностранный клуб». Но уже во второй день турнирный жребий свел вместе команды из Ирана и Бразилии. И они подарили болельщикам множество красивых голов, а главное — задали высокую планку для оставшихся игр дня.</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n<div>\n<div>\n<div>\n<div>\n<div>\n<div>\n<div>\n<div>\n<div aria-live=\"polite\" aria-relevant=\"additions\">\n<div data-peer=\"27594787\" data-admin=\"0\">\n<div>\n<h3>Два пенальти, гол с углового и хет-трик юного бразильца</h3>\n<p><strong>«Сепахан» (Иран) — «Сантос» (Бразилия) — 2:4</strong><br />\nГолы: Мохаммад Парса Рахами (23), Беньямин Алмашманеш (53) — Жулиу Сезар (15), Паулу<br />\nЭнрике (18, 39, 44)</p>\n<p>В первом матче игрового дня бразильский «Сантос» в упорной борьбе переиграл иранский «Сепахан» — 4:2. Счет забитым мячам бразильцев на турнире открыл Жулиу Сезар, остальные же голы записал на себя Пауло Энрике, оформивший хет-трик. Сначала он сильно зарядил в левый нижний угол с 11-метровой отметки, затем прямым ударом с углового, а третий мяч — легким касанием после скрытой передачи партнера в штрафную. У «Сепахана» отличились Мохаммад Парса Рахати и Беньямин Алмашманеш. Один из иранских голов также был забит с пенальти.</p>\n\n\n<h3>Габариты решают</h3>\n<p><strong>«Црвена Звезда» (Сербия) — ЦСКА (Москва) — 3:1</strong><br />\nГолы: Вук Югович (10, 45), Андрей Арсениевич (41) — Ашот Озманян (59)</p>\n<p>Москвичи и сербы в очном матче оспаривали право бороться за 5-6 места. В первом тайма игроки «Црвены» довольно быстро взяли мяч под контроль. Уже на 10-й минуте Вук Югович продавил оборону россиян и после смещения в право пробил низом. Во втором тайме сербам удалось быстро забить еще два мяча, что практически решило исход встречи. ЦСКА пытался изменить ситуацию, но так и не нашел ключик к габаритным игрокам соперника. Частые нарушения разбили игру на эпизоды, эмоции стали закипать у обеих команд, и все внимание как болельщиков, так и футболистов переключилось на эти околофутбольные разборки. В концовке встречи армейцы отыграли один мяч, но времени спастись у них уже не было.</p>\n\n<h3>Битва на Неве за финал</h3>\n<p><strong>«Алмаз-Антей» (Санкт-Петербург) — «Зенит» (Санкт-Петербург) — 1:2</strong><br />\nГолы: Кирилл Романенко (60) — Тимофей Латту (37), Клим Денисов (57)</p>\n<p>Петербургское дерби в первом полуфинале турнира получилось завораживающим. Огромные скорости и самоотдача на протяжении всего матча, борьба до последней секунды. Но какая бы равная и феноменальная ни была игра, в финал вышла только одна команда — «Зенит». В первом тайме мячей забито не было, зато во втором Тимофей Латту и Клим Денисов смогли поразить ворота «Алмаз-Антея» и обеспечить своей команде комфортное преимущество в счете. Хозяева турнира приложили все силы, чтобы отыграться, но забить им удалось лишь один мяч — Кирилл Романенко точным ударом низом реализовал пенальти. «Зенит» идет дальше, «Алмаз-Антей» сыграет в воскресенье за третье место.</p>\n\n<h3>Бразильцы все-таки в финале</h3>\n<p><strong>«Краснодар» (Краснодар) — «Палмейрас» (Бразилия) — 0:4</strong><br />\nГолы: Педру Рибейру (9, 20), Маркус Винисиус (37), Луис Густаво (45)</p>\n<p>После матча с ЦСКА, где «Палмейрасу» пришлось уходить с 0:2, встреча с краснодарскими «быками» интриговала как никогда. Москвичи показали, что с этими бразильцами можно играть. Но, похоже, что наши иностранные гости провели серьезную работу над ошибками перед полуфиналом. Поиграть на равных командам удалось только первые десять минут. Более физически развитыми бразильцами стали превосходить россиян в скорости и нацеленности на ворота. Два мяча в первом тайма, два мяча во втором &#8212; стабильность, которая позволила «Палмейрасу» выйти в финал V Кубка Бурчалкина.</p>\n\n</div>\n</div>\n</div>\n<div>В воскресенье в матче за 7-8 место сыграют «Сепахан» и ЦСКА, за 5-6 место будут бороться «Црвена Звезда» и «Сантос». В медальных матчах турнира сыграют «Алмаз-Антей» и «Краснодар», которые разыграют между собой бронзу, а за главный трофей Кубка Бурчалкина поспорят «Зенит» и «Палмейрас».</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n<div>\n<div>\n\n</div>\n</div>\n</div>\n</div>', 'news-article.html?slug=obilie-golov-i-imena-finalistov-kakim-byl-vtoroj-den-v-kubka-burchalkina', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365481/burcup/news/obilie-golov-i-imena-finalistov-kakim-byl-vtoroj-den-v-kubka-burchalkina/images/230520-0625-1776365480511.jpg', 'https://www.youtube.com/embed/HWqy11oh0tE?feature=oembed', 1, '2026-04-21 11:20:08.000', '2026-04-21 11:20:08.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (92, NULL, 'raspisanie-21-maya', '2023-05-20 00:00:00.000', 'Расписание на 21 мая', '21 мая — финалы\n10:00 — «Сепахан» – ЦСКА (матч за 7-е место)\n\n11:30 — «Сантос» – «Црвена Звезд» (матч за 5-е место)\n\n13:00 — «Алмаз-Антей» – «Краснодар» (матч за 3-е место)\n\n14:30 — «Зенит» – «Палмейрас» (финал)\n\n16:30 Церемония закрытия и награждение команд', '21 мая — финалы\n\n10:00 — «Сепахан» – ЦСКА (матч за 7-е место)\n\n11:30 — «Сантос» – «Црвена Звезд» (матч за 5-е место)\n\n13:00 — «Алмаз-Антей» – «Краснодар» (матч за 3-е место)\n\n14:30 — «Зенит» – «Палмейрас» (финал)\n\n16:30 Церемония закрытия и награждение команд', '<h3>21 мая — финалы</h3>\n<p>10:00 — «Сепахан» – ЦСКА (матч за 7-е место)</p>\n<p>11:30 — «Сантос» – «Црвена Звезд» (матч за 5-е место)</p>\n<p>13:00 — «Алмаз-Антей» – «Краснодар» (матч за 3-е место)</p>\n<p>14:30 — «Зенит» – «Палмейрас» (финал)</p>\n<p>16:30 Церемония закрытия и награждение команд</p>', 'news-article.html?slug=raspisanie-21-maya', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365479/burcup/news/raspisanie-21-maya/images/230519-0064-1-1776365478263.jpg', NULL, 1, '2026-04-21 11:20:08.000', '2026-04-21 11:20:08.000');
INSERT INTO `news_articles` (`id`, `tournament_id`, `slug`, `published_on`, `title`, `excerpt`, `body`, `body_html`, `link_path`, `image_url`, `video_url`, `is_published`, `created_at`, `updated_at`) VALUES (93, NULL, 'predstavlyaem-uchastnika-zenit-sankt-peterburg', '2023-05-19 00:00:00.000', 'Представляем участника — «Зенит» (Санкт-Петербург)', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».', 'Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».\n\nИстория выступлений на Кубке Бурчалкина:\n\n2016 г. — 2 место\n\n2017 г. — 7 место\n\n2018 г. — 3 место\n\n2019 г. — 2 место\n\nГлавный тренер команды U-13 — Максим Коваленко', '<p>Академия ФК «Зенит» является многократным победителем и призером соревнований по футболу как на российском, так и на международном уровне. Спортивная школа берет свое начало с 1968 года, когда на базе Центральной ДЮСШ ГОРОНО была образована ДЮСШ «Смена». В 2009 году она была преобразована в Академию ФК «Зенит».</p>\n<p><img fetchpriority=\"high\" src=\"https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365494/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg/gallery/zenit-13-1-1776365493518.png\" alt=\"\" /></p>\n<p>История выступлений на Кубке Бурчалкина:</p>\n<p>2016 г. — 2 место<br />\n2017 г. — 7 место<br />\n2018 г. — 3 место<br />\n2019 г. — 2 место</p>\n<p>Главный тренер команды U-13 — Максим Коваленко</p>', 'news-article.html?slug=predstavlyaem-uchastnika-zenit-sankt-peterburg', 'https://res.cloudinary.com/dcqvo4aoj/image/upload/v1776365492/burcup/news/predstavlyaem-uchastnika-zenit-sankt-peterburg/images/zenit-13-1776365491675.png', NULL, 1, '2026-04-21 11:20:09.000', '2026-04-21 11:20:09.000');
